// ════════════════════════════════════════════════════════════════
// AUTH — login / register / session management
// Runs before anything else. Shows auth screen if unauthenticated.
// ════════════════════════════════════════════════════════════════

let _currentUser = null;

// ── Theme (light / dark) ──────────────────────────────────────────
// Applied as early as possible; stored choice wins, otherwise the OS
// preference decides. (Inline <script> is blocked by CSP, so a brief
// first-paint flash on the very first load is expected.)
// Three themes now: the calm sage default ('light'), 'dark' (Warm Dusk), and
// 'vibrant' — a brighter, higher-energy light palette for a younger crowd who
// find the default a touch sober. Same layout and contrast rules; only the
// accent + canvas variables change.
const _THEME_ORDER = ['light', 'dark', 'vibrant'];
const _THEME_META = {
  light:   { icon: '🌙', label: 'Dark mode',    color: '#20362D' },  // shows the NEXT theme
  dark:    { icon: '✨', label: 'Vibrant mode', color: '#191612' },
  vibrant: { icon: '☀️', label: 'Calm mode',    color: '#0E9F8B' },
};

function _currentTheme() {
  return document.documentElement.dataset.theme || 'light';
}

(function initTheme() {
  let stored = localStorage.getItem('me_theme');
  if (!stored) {
    stored = (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches)
      ? 'dark' : 'light';
  }
  if (stored && stored !== 'light') document.documentElement.dataset.theme = stored;
})();

function _syncThemeToggleUI() {
  const meta = _THEME_META[_currentTheme()] || _THEME_META.light;
  const icon = document.getElementById('theme-toggle-icon');
  const label = document.getElementById('theme-toggle-label');
  if (icon)  icon.textContent  = meta.icon;
  if (label) label.textContent = t(meta.label);
  const mc = document.querySelector('meta[name="theme-color"]');
  if (mc) mc.content = meta.color;
}

function toggleTheme() {
  const el = document.documentElement;
  const next = _THEME_ORDER[(_THEME_ORDER.indexOf(_currentTheme()) + 1) % _THEME_ORDER.length];
  if (next === 'light') delete el.dataset.theme;
  else el.dataset.theme = next;
  localStorage.setItem('me_theme', next);
  _syncThemeToggleUI();
}

document.addEventListener('DOMContentLoaded', _syncThemeToggleUI);
document.addEventListener('DOMContentLoaded', _syncSimpleToggleUI);
document.addEventListener('DOMContentLoaded', _applySimpleLabels);

// ── Language (English / हिन्दी) ────────────────────────────────────
// A lightweight i18n layer that mirrors how Simple View swaps labels: any
// element tagged data-i18n="English text" has its textContent replaced with the
// current language's translation (or left as the English key when untranslated).
// The dictionary is keyed by the English source string, so tagging more elements
// later is just adding an attribute — the map grows without renaming keys.
// Translation packs are fetched on demand, not shipped inside this file.
//
// The Hindi pack alone is 242KB of source. Bundled, a second language pushed
// app.js past its payload budget and — worse — made every English reader
// download a language they will never see. Packs now live in
// /static/i18n/<code>.json and are fetched only when someone actually selects
// that language, which is what makes a third and fourth possible at all.
//
// `en` is the base: keys ARE the English strings, so there is nothing to load.
const I18N = { en: {} };

// Fetched packs, by code. A pack that fails to load leaves the entry absent
// rather than empty, so a network blip shows English rather than being
// remembered as "this language has no translations".
async function loadLangPack(code) {
  if (!code || code === 'en' || I18N[code]) return true;
  try {
    const pack = await fetch(`/static/i18n/${encodeURIComponent(code)}.json`,
                             {credentials: 'same-origin'}).then(r => r.ok ? r.json() : null);
    if (!pack || typeof pack !== 'object') return false;
    I18N[code] = pack;
    return true;
  } catch (e) {
    return false;
  }
}
// Languages the app offers. English is the base (keys ARE English, so it needs
// no pack). Any other code appears in the picker only once I18N[code] exists —
// so a half-built pack can't be selected. To add Tamil etc.: write I18N.ta = {…}
// then add {code:'ta', native:'தமிழ்', english:'Tamil'} here (mirror SERVER_LANGS
// in i18n_server.py for emails/push). Scaffolded, not yet translated: ta/te/bn/mr.
// `reviewed` says whether a native speaker has read the pack. It is not
// decoration: an app that talks about doses and symptoms in a language nobody
// fluent has checked can be confidently wrong, and the person reading it has no
// way to tell. An unreviewed language is still offered — half the point of
// shipping it is to get it read — but it says so, once, on the way in.
//
// A language only belongs in this list once its pack covers EVERY string the UI
// can ask for. That is enforced by tests/test_i18n_coverage.py rather than at
// runtime, because a partly-translated medical interface is worse than an
// English one: the reader cannot tell which half they are looking at.
// `locale` is the BCP-47 tag for dates and numbers. It lives here, on the
// language record, rather than in a second list beside it: a separate map is a
// list you can forget to add to, and forgetting it is silent — the language
// switches, the dates quietly stay English. Keeping it on the record makes
// omission a missing field the coverage test can see.
const SUPPORTED_LANGS = [
  { code: 'en', native: 'English',  english: 'English', locale: 'en-GB', reviewed: true },
  { code: 'hi', native: 'हिन्दी',   english: 'Hindi',   locale: 'hi-IN', reviewed: false },
  { code: 'bn', native: 'বাংলা',   english: 'Bengali', locale: 'bn-IN', reviewed: false },
  { code: 'mr', native: 'मराठी',   english: 'Marathi', locale: 'mr-IN', reviewed: false },
  // { code: 'ta', native: 'தமிழ்',   english: 'Tamil',   locale: 'ta-IN' },  // add I18N.ta first
  // { code: 'te', native: 'తెలుగు',  english: 'Telugu',  locale: 'te-IN' },
];
// Only offer a language that is English (the base) or actually has a pack.
function _availableLangs() {
  // Every listed language is offerable. It used to check that a pack was
  // already loaded, which was the right guard when packs were bundled and is
  // exactly wrong now that they are fetched on demand — it would hide every
  // language the user had not already chosen. Completeness is guaranteed at
  // build time instead: tests/test_i18n_coverage.py refuses to let a language
  // into SUPPORTED_LANGS until its pack covers every string.
  return SUPPORTED_LANGS.slice();
}
function _langMeta(code) { return SUPPORTED_LANGS.find(l => l.code === code) || SUPPORTED_LANGS[0]; }

function _lang() {
  try {
    const v = localStorage.getItem('arogo_lang') || 'en';
    // A stored code with no pack (e.g. left over from a removed language) falls
    // back to English rather than showing untranslated keys as if localized.
    return _availableLangs().some(l => l.code === v) ? v : 'en';
  } catch (e) { return 'en'; }
}
function t(s) { const d = I18N[_lang()]; return (d && d[s]) || s; }

// The locale for dates and numbers, following the app's language.
//
// 26 call sites passed 'en-US' outright, so "Friday, August 28" stayed English
// on every screen no matter what the user had chosen — the app spoke Hindi and
// dated everything in English. Region matters for more than month names: an
// Indian-language user reading d/m/y should not be handed m/d/y.
function _locale() {
  return _langMeta(_lang()).locale || 'en-GB';
}
// Interpolating translate: the key carries %1, %2… placeholders that are
// filled from the trailing arguments AFTER translation. In English mode t()
// returns the key verbatim, so the English sentence renders too. Used for the
// JS-generated strings that splice in live numbers ("3 of 5 doses taken").
function tformat(s) {
  const a = [].slice.call(arguments, 1);
  return t(s).replace(/%(\d+)/g, (_, i) => (a[i - 1] !== undefined ? a[i - 1] : ''));
}

function applyLang() {
  const lang = _lang();
  try { document.documentElement.lang = lang; } catch (e) {}
  document.querySelectorAll('[data-i18n]').forEach(el => {
    el.textContent = t(el.getAttribute('data-i18n'));
  });
  // Input placeholders (tagged data-i18n-ph="English placeholder").
  document.querySelectorAll('[data-i18n-ph]').forEach(el => {
    el.setAttribute('placeholder', t(el.getAttribute('data-i18n-ph')));
  });
  // The nav control shows the CURRENT language's own name; tapping it opens the
  // picker (rather than blindly flipping to a single "other" language).
  const lbl = document.getElementById('lang-toggle-label');
  if (lbl) lbl.textContent = _langMeta(lang).native;
}
function _activeViewName() {
  const el = document.querySelector('.view.active');
  return el ? el.id.replace(/^view-/, '') : null;
}
async function setLanguage(code) {
  const avail = _availableLangs();
  if (!avail.some(l => l.code === code)) return;   // not a language we offer
  // Fetch the pack BEFORE storing the choice. Switching first and loading
  // second would paint one frame of English under a Hindi label, and if the
  // fetch failed the app would sit in a language it cannot actually render.
  if (!(await loadLangPack(code))) {
    showToast(t('Could not load that language — still on %1')
                .replace('%1', _langMeta(_lang()).native), 'error');
    return;
  }
  try { localStorage.setItem('arogo_lang', code); } catch (e) {}
  closeLanguagePicker();
  applyLang();
  // Static [data-i18n] nodes are swept by applyLang; JS-rendered content only
  // re-localizes when its view re-renders, so re-run the active view's loader.
  const v = _activeViewName();
  if (v) { try { switchView(v); } catch (e) {} }
  // Chrome outside any view: the greeting is written once at boot, so switching
  // language left it in the old one until the next reload. (The daily briefing
  // beside it is rebuilt from dose data by its own caller, and is one of the
  // strings still not wired for translation at all — see the note in
  // tests/test_i18n_coverage.py.)
  try { setGreeting(); } catch (e) {}
  // Said once, in the language being switched to, so it is legible to the
  // person it concerns. Not a blocking dialog — it is a caveat, not a warning.
  try {
    const meta = _langMeta(code);
    if (code !== 'en' && meta && meta.reviewed === false) {
      showToast(t('This translation has not been checked by a native speaker yet. Tell us anything that reads wrong.'), 'info');
    }
  } catch (e) {}
  // Mirror the choice to the server profile so the headless mailer + scheduler
  // (emails, push reminders) can localize too — they have no localStorage.
  // Fire-and-forget; the localStorage value above already drives the UI.
  try {
    fetch('/api/food/profile', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin', body: JSON.stringify({ language: code }),
    }).catch(() => {});
  } catch (e) {}
}

function openLanguagePicker() {
  const langs = _availableLangs();
  // With a single language available there's nothing to pick — no menu.
  if (langs.length < 2) return;
  closeLanguagePicker();
  const cur = _lang();
  const ov = document.createElement('div');
  ov.className = 'lang-picker-overlay';
  ov.id = 'lang-picker-overlay';
  ov.setAttribute('data-ev-click', "langPickerBackdrop(event)");
  ov.innerHTML = `<div class="lang-picker" role="menu">
    <div class="lang-picker-head">${t('Choose language')}</div>
    ${langs.map(l => `<button class="lang-opt${l.code === cur ? ' selected' : ''}" role="menuitemradio"
        aria-checked="${l.code === cur}" data-ev-click="setLanguage('${l.code}')">
        <span class="lang-opt-native">${escHtml(l.native)}</span>
        <span class="lang-opt-en">${escHtml(l.english)}</span>
        ${l.code === cur ? '<span class="lang-opt-check">✓</span>' : ''}
      </button>`).join('')}
  </div>`;
  document.body.appendChild(ov);
}
function langPickerBackdrop(ev) { if (ev.target && ev.target.id === 'lang-picker-overlay') closeLanguagePicker(); }
function closeLanguagePicker() { const el = document.getElementById('lang-picker-overlay'); if (el) el.remove(); }

// Back-compat: the nav control used to call toggleLanguage(); now it opens the
// picker. With only two languages this still feels like a quick switch.
function toggleLanguage() { openLanguagePicker(); }
document.addEventListener('DOMContentLoaded', applyLang);

// ── Simple View (senior / large-type mode) ────────────────────────
// A second display axis alongside dark/light. 'simple' enlarges text and
// tap targets, raises contrast, and collapses the nav to the essentials.
// localStorage me_ui_mode is the source of truth for a no-flash first paint;
// the profile.ui_mode column mirrors it so the choice follows the user across
// devices (and lets a caregiver set it for the patient). Values:
//   'simple'   → large UI on
//   'standard' → explicitly declined (do not re-prompt)
//   (absent)   → never chosen (age>=60 prompt may still offer it)
(function initUiMode() {
  try {
    if (localStorage.getItem('me_ui_mode') === 'simple')
      document.documentElement.dataset.mode = 'simple';
  } catch (e) {}
})();

function _syncSimpleToggleUI() {
  const on = document.documentElement.dataset.mode === 'simple';
  const icon   = document.getElementById('simple-toggle-icon');
  const text   = on ? 'Standard view' : 'Simple view';
  if (icon) icon.textContent = on ? '🔎' : '🔍';
  // Both the sidebar toggle (desktop) and the "More"-menu toggle (mobile).
  for (const id of ['simple-toggle-label', 'simple-toggle-label-m']) {
    const el = document.getElementById(id);
    if (el) el.textContent = text;
  }
}

// Swap medical/tracker jargon for plain language in Simple View. Any static
// element with a `data-simple` attribute shows that text in Simple View and
// its original text otherwise — e.g. <button data-simple="❤️ BP & Sugar">.
// The original is stashed on first swap so Standard View restores exactly.
function _applySimpleLabels() {
  const on = document.documentElement.dataset.mode === 'simple';
  document.querySelectorAll('[data-simple]').forEach(el => {
    if (on) {
      if (el.dataset.stdLabel === undefined) el.dataset.stdLabel = el.textContent;
      el.textContent = el.dataset.simple;
    } else if (el.dataset.stdLabel !== undefined) {
      el.textContent = el.dataset.stdLabel;
    }
  });
}

function applyUiMode(mode) {
  const el = document.documentElement;
  if (mode === 'simple') el.dataset.mode = 'simple';
  else delete el.dataset.mode;
  _syncSimpleToggleUI();
  _applySimpleLabels();
}

// Persist a choice both locally (instant, no-flash next load) and to the
// profile (cross-device). `mode` is 'simple' or 'standard'.
function setUiMode(mode) {
  applyUiMode(mode);
  try { localStorage.setItem('me_ui_mode', mode); } catch (e) {}
  fetch('/api/food/profile', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'same-origin',
    body: JSON.stringify({ ui_mode: mode }),
  }).catch(() => {});
}

function toggleSimpleMode() {
  setUiMode(document.documentElement.dataset.mode === 'simple' ? 'standard' : 'simple');
  dismissSimplePrompt();
}

// One-time offer shown to users aged 60+ who haven't chosen a view yet.
function offerSimpleMode() {
  if (document.getElementById('simple-prompt')) return;
  const card = document.createElement('div');
  card.id = 'simple-prompt';
  card.setAttribute('role', 'dialog');
  card.setAttribute('aria-label', 'Simple view offer');
  card.innerHTML =
    '<div class="simple-prompt-inner">' +
      '<div class="simple-prompt-icon">🔎</div>' +
      '<div class="simple-prompt-title">Prefer bigger text?</div>' +
      '<div class="simple-prompt-body">Simple View makes text larger, buttons easier to tap, ' +
        'and keeps just the essentials on screen. You can switch back any time in Settings.</div>' +
      '<div class="simple-prompt-actions">' +
        '<button class="simple-prompt-yes" type="button">' + t('Turn on Simple View') + '</button>' +
        '<button class="simple-prompt-no" type="button">' + t('No thanks') + '</button>' +
      '</div>' +
    '</div>';
  document.body.appendChild(card);
  card.querySelector('.simple-prompt-yes').addEventListener('click', () => { setUiMode('simple'); dismissSimplePrompt(); });
  card.querySelector('.simple-prompt-no').addEventListener('click', () => { setUiMode('standard'); dismissSimplePrompt(); });
}

function dismissSimplePrompt() {
  const card = document.getElementById('simple-prompt');
  if (card) card.remove();
}

// Reconcile with the server profile: adopt a cross-device choice if this
// device hasn't decided, then offer Simple View to 60+ users who never have.
function reconcileUiMode(profile) {
  if (!profile) return;
  let local = null;
  try { local = localStorage.getItem('me_ui_mode'); } catch (e) {}
  const server = profile.ui_mode || null;   // 'simple' | 'standard' | null
  if (!local && server) {
    // Another device chose for this account — honour it here too.
    applyUiMode(server);
    try { localStorage.setItem('me_ui_mode', server); } catch (e) {}
    local = server;
  }
  const decided = local || server;          // any explicit choice, anywhere
  const age = parseInt(profile.age, 10);
  if (!decided && Number.isFinite(age) && age >= 60) offerSimpleMode();
}

// Adopt a language chosen on another device when this one hasn't decided, so the
// choice follows the account. Mirrors reconcileUiMode; localStorage stays the
// per-device source of truth for a no-flash first paint.
function reconcileLanguage(profile) {
  if (!profile) return;
  let local = null;
  try { local = localStorage.getItem('arogo_lang'); } catch (e) {}
  const server = profile.language || null;   // 'hi' | 'en' | null
  if (!local && server && server !== _lang()) {
    try { localStorage.setItem('arogo_lang', server); } catch (e) {}
    applyLang();
    const v = _activeViewName();
    if (v) { try { switchView(v); } catch (e) {} }
  }
}

// ── CSP-safe event dispatch ───────────────────────────────────────
// Inline on*="…" attributes are blocked by our Content-Security-Policy
// (script-src carries no 'unsafe-inline'). Markup uses data-ev-click /
// data-ev-change / data-ev-input / data-ev-keydown instead, and this
// dispatcher interprets the expression WITHOUT eval: semicolon-separated
// calls fn(arg,…) where each arg is a string/number/bool literal, `this`,
// `event`, `this.value`, `this.checked`, or a JSON object/array.

function _evTokenize(expr, sep) {
  // Split on `sep` at bracket depth 0, outside quotes
  const parts = [];
  let depth = 0, q = null, cur = '';
  for (let i = 0; i < expr.length; i++) {
    const ch = expr[i];
    if (q) {
      cur += ch;
      if (ch === '\\') cur += expr[++i] || '';
      else if (ch === q) q = null;
    } else if (ch === "'" || ch === '"') { q = ch; cur += ch; }
    else if ('([{'.includes(ch)) { depth++; cur += ch; }
    else if (')]}'.includes(ch)) { depth--; cur += ch; }
    else if (ch === sep && depth === 0) { parts.push(cur); cur = ''; }
    else cur += ch;
  }
  if (cur.trim()) parts.push(cur);
  return parts.map(s => s.trim()).filter(Boolean);
}

function _evArg(a, el, ev) {
  if (a === 'this')         return el;
  if (a === 'event')        return ev;
  if (a === 'this.value')   return el.value;
  if (a === 'this.checked') return el.checked;
  if (a === 'true')  return true;
  if (a === 'false') return false;
  if (a === 'null')  return null;
  if (/^-?\d+(\.\d+)?$/.test(a)) return parseFloat(a);
  if ((a[0] === "'" || a[0] === '"') && a[a.length - 1] === a[0])
    return a.slice(1, -1).replace(/\\(['"\\])/g, '$1');
  if (a[0] === '{' || a[0] === '[') return JSON.parse(a);
  console.warn('[ev] unsupported arg:', a);
  return undefined;
}

function _evRun(expr, el, ev) {
  for (const stmt of _evTokenize(expr, ';')) {
    if (stmt === 'return false' ||
        stmt === 'event.preventDefault()') { ev.preventDefault(); continue; }
    if (stmt === 'event.stopPropagation()') { ev.stopPropagation(); continue; }
    const m = stmt.match(/^([A-Za-z_$][\w$]*)\((.*)\)$/s);
    if (!m || typeof window[m[1]] !== 'function') {
      console.warn('[ev] unsupported statement:', stmt);
      continue;
    }
    window[m[1]].apply(el, _evTokenize(m[2], ',').map(a => _evArg(a, el, ev)));
  }
}

for (const _t of ['click', 'change', 'input', 'keydown']) {
  document.addEventListener(_t, ev => {
    const el = ev.target && ev.target.closest && ev.target.closest(`[data-ev-${_t}]`);
    if (!el) return;
    if (el.tagName === 'A') ev.preventDefault();
    try { _evRun(el.getAttribute(`data-ev-${_t}`), el, ev); }
    catch (err) { console.error('[ev]', el.getAttribute(`data-ev-${_t}`), err); }
  });
}

// Named replacements for what used to be inline JS expressions
function hideEl(id)  { const el = document.getElementById(id); if (el) el.style.display = 'none'; }
function clickEl(id) { const el = document.getElementById(id); if (el) el.click(); }
function backdropClose(ev, el, fnName) { if (ev.target === el) window[fnName](); }
function quickAdd(view) {
  switchView(view);
  const openers = { food: 'openAddFoodModal', fitness: 'openActivityModal', todos: 'openTodoModal' };
  setTimeout(() => { const f = window[openers[view]]; if (f) f(); }, 200);
}
function enterAddCustomSymptom(ev) {
  if (ev.key === 'Enter') { addCustomSymptom(); ev.preventDefault(); }
}
function setGymField(subId, i, field, val) {
  if (typeof gymSets !== 'undefined' && gymSets[subId] && gymSets[subId][i])
    gymSets[subId][i][field] = val;
}

// ── Undo toast (replaces confirm() dialogs) ──────────────────────
// Destructive actions run after a short grace window with a visible
// Undo button, instead of interrupting with a browser confirm().
let _pendingUndoable = null;

function undoable(message, commit, delayMs = 4500) {
  // Starting a new action commits any still-pending one immediately
  if (_pendingUndoable) _pendingUndoable.flush();

  const bar = document.createElement('div');
  bar.style.cssText =
    'position:fixed;bottom:24px;left:50%;transform:translateX(-50%);' +
    'background:var(--gray-900);color:#fff;padding:12px 18px;border-radius:12px;' +
    'display:flex;align-items:center;gap:16px;font-size:13px;z-index:10000;' +
    'box-shadow:0 8px 24px rgba(0,0,0,.28);font-family:inherit;max-width:90vw';
  const txt = document.createElement('span');
  txt.textContent = message;
  const btn = document.createElement('button');
  btn.textContent = 'Undo';
  btn.style.cssText =
    'background:none;border:none;color:#5EEAD4;font-weight:700;font-size:13px;' +
    'cursor:pointer;padding:0;font-family:inherit';
  bar.append(txt, btn);
  document.body.appendChild(bar);

  let settled = false;
  const timer = setTimeout(run, delayMs);

  async function run() {
    if (settled) return;
    settled = true;
    bar.remove();
    _pendingUndoable = null;
    try { await commit(); }
    catch (e) { showToast('Action failed', 'error'); console.error('[undoable]', e); }
  }
  btn.addEventListener('click', () => {
    if (settled) return;
    settled = true;
    clearTimeout(timer);
    bar.remove();
    _pendingUndoable = null;
  });
  _pendingUndoable = { flush: () => { clearTimeout(timer); run(); } };
}

// ── Date helpers — always use LOCAL date, never UTC ───────────
// new Date().toISOString() returns UTC — wrong for users in UTC+N timezones.
// Example: in India (UTC+5:30) at 11pm, toISOString() gives yesterday's date.
// The YYYY-MM-DD key for any date, in local time. This is a storage key, not
// something a user reads, so it must NOT follow the app's language: one call
// site built it with toLocaleDateString('en-CA') — correct output, but the
// moment that locale followed the UI it would have produced Devanagari
// numerals, the key would have matched nothing, and the only symptom would
// have been a date label quietly going wrong. Keys are built, never formatted.
function localDateKey(date) {
  const d = date || new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function localToday() {
  return localDateKey();
}

function localDatetime(date) {
  // Return YYYY-MM-DDTHH:MM in local time for datetime-local inputs
  const d = date || new Date();
  const y  = d.getFullYear();
  const mo = String(d.getMonth() + 1).padStart(2, '0');
  const da = String(d.getDate()).padStart(2, '0');
  const h  = String(d.getHours()).padStart(2, '0');
  const mi = String(d.getMinutes()).padStart(2, '0');
  return `${y}-${mo}-${da}T${h}:${mi}`;
}

function browserTimezone() {
  return Intl.DateTimeFormat().resolvedOptions().timeZone;
}

// Called on page load — check if we have a valid session
async function initAuth() {
  // The pack, before anything decides what to render. Packs are fetched on
  // demand and that only used to happen after sign-in, so the sign-in screen
  // itself was English for everyone — someone who had set the app to Marathi
  // signed out and hit an English wall on the way back in. Awaited here rather
  // than inside showAuthScreen() because that function is synchronous and is
  // called from three places.
  //
  // Failure is not fatal: loadLangPack returns false and applyLang falls back
  // to the English keys. A sign-in screen in the wrong language beats no
  // sign-in screen.
  try { await loadLangPack(_lang()); } catch (e) {}

  // Arriving from a password-reset email link (/?reset=TOKEN)
  const resetToken = new URLSearchParams(location.search).get('reset');
  if (resetToken) {
    _resetToken = resetToken;
    showAuthScreen();
    showAuthForm('auth-form-reset');
    return;
  }
  // Arriving from a family invite link (/?family_invite=TOKEN) —
  // stash it; it's redeemed in showApp() once the user is signed in
  const inviteToken = new URLSearchParams(location.search).get('family_invite');
  if (inviteToken) {
    sessionStorage.setItem('me_family_invite', inviteToken);
    history.replaceState({}, '', location.pathname);
  }
  // Home-screen PWA shortcut (/?action=log-dose|log-water|checkin). Stash it so
  // it still fires if a sign-in stands between the tap and the app; consumed in
  // showApp() once the user is in.
  const shortcut = new URLSearchParams(location.search).get('action');
  if (shortcut) {
    sessionStorage.setItem('me_shortcut_action', shortcut);
    history.replaceState({}, '', location.pathname);
  }
  // Landing back from the email verification link (/?verified=1|0)
  const verified = new URLSearchParams(location.search).get('verified');
  if (verified !== null) {
    history.replaceState({}, '', location.pathname);
    setTimeout(() => showToast(
      verified === '1' ? 'Email verified ✅'
                       : 'Verification link is invalid or expired', verified === '1' ? '' : 'error'), 400);
  }
  const r = await fetch('/auth/me', {credentials: 'same-origin'}).catch(() => null);
  if (r && r.ok) {
    _currentUser = await r.json();
    showApp();
  } else {
    showAuthScreen();
  }
}

function showAuthScreen() {
  const screen = document.getElementById('auth-screen');
  const sidebar = document.getElementById('app-sidebar');
  const main    = document.getElementById('app-main');
  if (screen)  screen.style.display = '';
  if (sidebar) sidebar.style.display = 'none';
  if (main)    main.style.display    = 'none';
  const fab = document.getElementById('quick-fab');
  if (fab) fab.style.display = 'none';
  const tabbar = document.getElementById('mobile-tabbar');
  if (tabbar) tabbar.style.visibility = 'hidden';
  // applyLang already ran at DOMContentLoaded, before initAuth had fetched the
  // pack, so at that point every key still resolved to its English self. Re-run
  // it now that the pack is in.
  try { applyLang(); } catch (e) {}
}

// ── PWA install coaching ──────────────────────────────────────────
// iOS web push only works once Arogo is on the home screen, so a nudge to
// install is part of making reminders reliable — not just a growth trick.
// Android/Chrome fires beforeinstallprompt (programmatic install); iOS needs
// the manual Share → Add to Home Screen, so we coach it. Shown once, then never
// again (localStorage me_install), and never when already installed.
let _deferredInstallPrompt = null;
let _installPromptScheduled = false;

window.addEventListener('beforeinstallprompt', (e) => {
  e.preventDefault();                 // suppress Chrome's mini-infobar; we pick the moment
  _deferredInstallPrompt = e;
});
window.addEventListener('appinstalled', () => {
  _deferredInstallPrompt = null;
  try { localStorage.setItem('me_install', 'installed'); } catch (e) {}
  dismissInstallPrompt();
});

function _isStandalone() {
  return (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) ||
         window.navigator.standalone === true;
}
function _isIOS() {
  return /iphone|ipad|ipod/i.test(navigator.userAgent) && !window.MSStream;
}

function scheduleInstallPrompt() {
  if (_installPromptScheduled) return;
  _installPromptScheduled = true;
  // Give the dashboard a moment to land (and any first-run prompts to clear)
  // before nudging — a nag on first paint would be hostile.
  setTimeout(maybeShowInstallPrompt, 6000);
}

function maybeShowInstallPrompt() {
  if (_isStandalone()) return;                       // already installed
  let seen = null;
  try { seen = localStorage.getItem('me_install'); } catch (e) {}
  if (seen) return;                                  // installed or dismissed before
  const android = !!_deferredInstallPrompt;
  const ios = _isIOS();
  if (!android && !ios) return;                      // desktop / unsupported → nothing to do
  if (document.getElementById('install-banner')) return;
  if (document.getElementById('simple-prompt')) {    // don't stack on the 60+ prompt
    setTimeout(maybeShowInstallPrompt, 4000); return;
  }

  const card = document.createElement('div');
  card.id = 'install-banner';
  card.setAttribute('role', 'dialog');
  card.setAttribute('aria-label', 'Add Arogo to your home screen');

  if (ios) {
    // iOS has no programmatic install — Safari only offers it through the
    // Share sheet. So instead of a dead button, we coach the exact taps with a
    // numbered guide and the real Share glyph, and point down to the toolbar
    // where that icon actually lives on iPhone.
    card.classList.add('install-banner--ios');
    const shareGlyph =
      '<svg class="ios-share-glyph" viewBox="0 0 24 24" width="16" height="16" fill="none" ' +
        'stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" ' +
        'aria-label="' + t('Share') + '">' +
        '<path d="M12 3v12"/><path d="M8 7l4-4 4 4"/>' +
        '<path d="M6 11H5a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-6a2 2 0 0 0-2-2h-1"/>' +
      '</svg>';
    card.innerHTML =
      '<div class="install-inner">' +
        '<div class="install-title">' + t('Put Arogo on your home screen') + '</div>' +
        '<div class="install-text">' +
          t('So dose reminders reach you even when the app is closed.') + '</div>' +
        '<ol class="ios-steps">' +
          '<li><span class="ios-step-n">1</span><span>' +
            t('In Safari, tap the Share icon') + ' ' + shareGlyph + '</span></li>' +
          '<li><span class="ios-step-n">2</span><span>' +
            t('Choose “Add to Home Screen”') + '</span></li>' +
          '<li><span class="ios-step-n">3</span><span>' +
            t('Tap “Add” — that’s it') + '</span></li>' +
        '</ol>' +
        '<div class="install-actions">' +
          '<button class="install-yes" type="button">' + t('Got it') + '</button>' +
          '<button class="install-no" type="button">' + t('Not now') + '</button>' +
        '</div>' +
      '</div>' +
      '<div class="install-arrow" aria-hidden="true">▾</div>';
    document.body.appendChild(card);
    // "Got it" just dismisses (the user does the taps themselves); "Not now"
    // is the same, but only "Got it" implies they'll follow through.
    card.querySelector('.install-yes').addEventListener('click', () => { _markInstallSeen(); dismissInstallPrompt(); });
    card.querySelector('.install-no').addEventListener('click', () => { _markInstallSeen(); dismissInstallPrompt(); });
    return;
  }

  // Android / Chrome: real programmatic install behind one button.
  card.innerHTML =
    '<div class="install-inner">' +
      '<div class="install-ico">📲</div>' +
      '<div class="install-body">' +
        '<div class="install-title">' + t('Never miss a reminder') + '</div>' +
        '<div class="install-text">' +
          t('Add Arogo to your home screen so dose reminders reach you even when the app is closed.') + '</div>' +
        '<div class="install-actions">' +
          '<button class="install-yes" type="button">' + t('Add to Home Screen') + '</button>' +
          '<button class="install-no" type="button">' + t('Not now') + '</button>' +
        '</div>' +
      '</div>' +
    '</div>';
  document.body.appendChild(card);
  card.querySelector('.install-no').addEventListener('click', () => { _markInstallSeen(); dismissInstallPrompt(); });
  card.querySelector('.install-yes').addEventListener('click', doInstall);
}

async function doInstall() {
  if (!_deferredInstallPrompt) { _markInstallSeen(); dismissInstallPrompt(); return; }
  _deferredInstallPrompt.prompt();
  try { await _deferredInstallPrompt.userChoice; } catch (e) {}
  _deferredInstallPrompt = null;
  _markInstallSeen();
  dismissInstallPrompt();
}

function _markInstallSeen() { try { localStorage.setItem('me_install', 'seen'); } catch (e) {} }
function dismissInstallPrompt() {
  const el = document.getElementById('install-banner');
  if (el) el.remove();
}

// async so the first render can wait on the user's locale (currency + units)
// instead of rendering with defaults and re-fetching the whole dashboard to
// correct itself. Callers don't await it; nothing after their call depends on
// the dashboard having finished loading, which was already asynchronous.
async function showApp() {
  const screen  = document.getElementById('auth-screen');
  const sidebar = document.getElementById('app-sidebar');
  const main    = document.getElementById('app-main');
  if (screen)  screen.style.display  = 'none';
  if (sidebar) sidebar.style.display = '';
  if (main)    main.style.display    = '';
  const fab = document.getElementById('quick-fab');
  if (fab) fab.style.display = 'flex';
  const tabbar = document.getElementById('mobile-tabbar');
  if (tabbar) tabbar.style.visibility = '';

  // Populate user name in header
  const nameEl = document.getElementById('header-user-name');
  if (nameEl && _currentUser) nameEl.textContent = _currentUser.name || _currentUser.email;

  // Nudge unverified accounts (banner has a resend button)
  const vBanner = document.getElementById('verify-banner');
  if (vBanner) vBanner.style.display =
    (_currentUser && _currentUser.verified === false) ? 'flex' : 'none';

  // Restore the managing banner if a caregiver was acting-as a member (the
  // acting-as state lives in the signed session, so it survives reloads).
  try { refreshActingAs(); } catch (e) {}

  // Sync browser timezone to profile (silently, no await needed)
  fetch('/api/food/profile', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    credentials: 'same-origin',
    body: JSON.stringify({ timezone: browserTimezone() }),
  }).then(r => r.ok ? r.json() : null)
    .then(d => { if (d && d.profile) { reconcileUiMode(d.profile); reconcileLanguage(d.profile); } })
    .catch(() => {});

  // The language pack comes FIRST, before anything renders.
  //
  // It was originally loaded alongside applyLang() further down, which looked
  // reasonable and was wrong: setGreeting() and the dashboard cards had already
  // painted by then, in English, and applyLang only re-sweeps [data-i18n] nodes
  // — so JS-rendered text stayed English until something happened to re-render
  // it, which on the dashboard is never. Awaited, so nothing paints before the
  // words exist.
  try { await loadLangPack(_lang()); } catch(e) {}

  // Run all setup functions that DOMContentLoaded used to run
  try { setGreeting(); }             catch(e) {}
  try { setDates(); }                catch(e) {}
  try { setupNavigation(); }         catch(e) {}
  try { setupDropzone(); }           catch(e) {}
  try { setupTagPicker(); }          catch(e) {}
  try { setupUploadForm(); }         catch(e) {}
  try { setupMedForm(); }            catch(e) {}
  try { setupActivityForm(); }       catch(e) {}
  try { setupIconColorPicker(); }    catch(e) {}
  try { setupFreqPicker(); }         catch(e) {}
  try { setupActivityTypePicker(); } catch(e) {}
  try { setupFilters(); }            catch(e) {}
  try { updateSidebarUser(); }       catch(e) {}
  try { checkNotifPermission(); }    catch(e) {}
  try { setupPushSubscription(); }   catch(e) {}
  // If permission was revoked in browser settings, the server still holds a
  // subscription and would keep pushing. setupPushSubscription returns early in
  // that case, so clearing it needs its own call.
  try { reconcilePushPermission(); } catch(e) {}
  try { _watchModalVisibility(); }   catch(e) {}
  try { _watchForLockedResponses(); } catch(e) {}
  try { loadLock(); }                catch(e) {}
  try { scheduleTodoReminderChecks(); } catch(e) {}
  try { scheduleInstallPrompt(); }   catch(e) {}
  try { applyLang(); }               catch(e) {}
  // Record who is signed in before touching the queue. The service worker can't
  // ask — a notification tap fires with no page open — so it reads this to stamp
  // anything it queues, which is what stops one person's offline dose being
  // replayed into another's account on a shared phone.
  try { if (_currentUser && _currentUser.id) _outboxSetUid(_currentUser.id); } catch (e) {}
  // Replay anything that was logged while offline, and show a pending badge.
  try { _updateOutboxBadge(); flushOutbox(); } catch(e) {}

  const tdp = document.getElementById('thoughts-date-picker');
  if (tdp) tdp.value = localToday();

  // Redeem a pending family invite (user arrived via emailed link)
  const inviteToken = sessionStorage.getItem('me_family_invite');
  if (inviteToken) {
    sessionStorage.removeItem('me_family_invite');
    fetch('/api/family/invite/accept', {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      credentials: 'same-origin', body: JSON.stringify({token: inviteToken}),
    }).then(async r => {
      const d = await r.json().catch(() => ({}));
      if (r.ok) { showToast('You joined the family group 🎉'); switchView('family'); }
      else      { showToast(d.error || 'Invite could not be accepted', 'error'); switchView('dashboard'); }
    }).catch(() => switchView('dashboard'));
    return;
  }

  // Resolve the user's currency, country and units BEFORE the first render.
  // This used to fire alongside switchView('dashboard') and then re-run
  // loadDashboard() when it resolved — twenty endpoints fetched a second time,
  // ~235ms apart, purely to restate money in the right currency. It also meant
  // the first paint showed ₹ and kg to someone who uses $ and lb, then flipped.
  //
  // One cheap request, raced against a short timeout so a slow or dead /api/locale
  // can never hold the app hostage: if it doesn't answer in time we render with
  // the defaults, exactly as before.
  try {
    await Promise.race([
      loadUserLocale().catch(() => {}),
      new Promise(res => setTimeout(res, 1200)),
    ]);
  } catch (e) {}

  // Load the dashboard
  switchView('dashboard');

  // Fire a pending home-screen shortcut once the app is up.
  try { _runShortcutAction(); } catch (e) {}

  // First-timers get one gentle guided tour (skips if onboarding/any overlay
  // is already showing). Re-openable later from the More nav.
  try { maybeAutoTour(); } catch (e) {}
}

// Dispatch a stashed PWA home-screen shortcut (see the manifest `shortcuts`).
// Each lands the user one tap from the action: the dashboard's next-dose hero,
// the food view's water quick-add, or the daily check-in.
function _runShortcutAction() {
  const action = sessionStorage.getItem('me_shortcut_action');
  if (!action) return;
  sessionStorage.removeItem('me_shortcut_action');
  setTimeout(() => {
    try {
      if (action === 'log-water')   switchView('food');
      else if (action === 'checkin') startDailyCheckin();
      else                           switchView('dashboard');   // log-dose (default)
    } catch (e) {}
  }, 300);
}

// Show one auth form, hide the others (login / register / forgot / reset)
function showAuthForm(id) {
  for (const f of ['auth-form-login', 'auth-form-register', 'auth-form-forgot', 'auth-form-reset']) {
    const el = document.getElementById(f);
    if (el) el.style.display = (f === id) ? '' : 'none';
  }
  hideAuthError();
  hideAuthSuccess();
}

function switchAuthTab(tab) {
  const isLogin = tab === 'login';
  showAuthForm(isLogin ? 'auth-form-login' : 'auth-form-register');
  document.getElementById('auth-tab-login').style.background    = isLogin ? 'var(--gray-0)' : 'transparent';
  document.getElementById('auth-tab-login').style.color         = isLogin ? 'var(--gray-800)' : 'var(--gray-400)';
  document.getElementById('auth-tab-register').style.background = isLogin ? 'transparent' : 'var(--gray-0)';
  document.getElementById('auth-tab-register').style.color      = isLogin ? 'var(--gray-400)' : 'var(--gray-800)';
}

function showForgotForm() { showAuthForm('auth-form-forgot'); }
function backToLogin()    { switchAuthTab('login'); }

function showAuthError(msg) {
  const el = document.getElementById('auth-error');
  if (el) { el.textContent = msg; el.style.display = ''; }
}
function hideAuthError() {
  const el = document.getElementById('auth-error');
  if (el) el.style.display = 'none';
}
function showAuthSuccess(msg) {
  const el = document.getElementById('auth-success');
  if (el) { el.textContent = msg; el.style.display = ''; }
}
function hideAuthSuccess() {
  const el = document.getElementById('auth-success');
  if (el) el.style.display = 'none';
}

function setAuthBtnLoading(id, loading, label) {
  const btn = document.getElementById(id);
  if (!btn) return;
  btn.disabled    = loading;
  btn.textContent = loading ? 'Please wait…' : label;
}

async function submitLogin() {
  hideAuthError();
  const email = (document.getElementById('login-email')?.value || '').trim();
  const pw    = document.getElementById('login-password')?.value || '';
  if (!email || !pw) { showAuthError('Please enter your email and password'); return; }

  setAuthBtnLoading('login-btn', true, 'Sign in');

  let r, data;
  try {
    r = await fetch('/auth/login', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      credentials: 'same-origin',
      body: JSON.stringify({email, password: pw}),
    });
    const ct = r.headers.get('content-type') || '';
    if (ct.includes('application/json')) {
      data = await r.json();
    } else {
      const text = await r.text();
      data = { error: `Server error (${r.status}): route not found. Check Flask is running the latest app.py.` };
    }
  } catch (err) {
    setAuthBtnLoading('login-btn', false, 'Sign in');
    showAuthError('Could not reach server. Is Flask running?');
    console.error('Login fetch error:', err);
    return;
  }

  setAuthBtnLoading('login-btn', false, 'Sign in');

  if (!r.ok) {
    showAuthError(data.error || 'Login failed');
    return;
  }

  _currentUser = data.user;
  await new Promise(res => setTimeout(res, 50));
  showApp();
}

async function submitRegister() {
  hideAuthError();
  const email = (document.getElementById('reg-email')?.value || '').trim();
  const pw    = document.getElementById('reg-password')?.value || '';
  const name  = (document.getElementById('reg-name')?.value || '').trim();

  if (!email) { showAuthError('Please enter your email address'); return; }
  if (!pw)    { showAuthError('Please enter a password (8+ characters)'); return; }

  setAuthBtnLoading('register-btn', true, 'Create account');

  let r, data;
  try {
    r = await fetch('/auth/register', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      credentials: 'same-origin',
      body: JSON.stringify({ name: name || email.split('@')[0], email, password: pw }),
    });
    const ct = r.headers.get('content-type') || '';
    if (ct.includes('application/json')) {
      data = await r.json();
    } else {
      const text = await r.text();
      data = { error: `Server error (${r.status}): ${text.slice(0, 120)}` };
    }
  } catch (err) {
    setAuthBtnLoading('register-btn', false, 'Create account');
    showAuthError('Could not reach server. Is Flask running?');
    console.error('Register fetch error:', err);
    return;
  }

  setAuthBtnLoading('register-btn', false, 'Create account');

  if (!r.ok) {
    showAuthError(data.error || 'Registration failed');
    return;
  }

  _currentUser = data.user;
  await new Promise(res => setTimeout(res, 50));
  // New users go through onboarding before seeing the dashboard
  showOnboarding();
}

let _resetToken = null;

async function submitForgot() {
  hideAuthError(); hideAuthSuccess();
  const email = (document.getElementById('forgot-email')?.value || '').trim();
  if (!email) { showAuthError('Please enter your email address'); return; }

  setAuthBtnLoading('forgot-btn', true, 'Send reset link');
  try {
    const r = await fetch('/auth/forgot-password', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      credentials: 'same-origin',
      body: JSON.stringify({email}),
    });
    const data = await r.json().catch(() => ({}));
    if (!r.ok) { showAuthError(data.error || 'Could not send reset link'); return; }
    showAuthSuccess(data.message || 'If that email is registered, a reset link is on its way.');
  } catch (err) {
    showAuthError('Could not reach server. Is Flask running?');
    console.error('Forgot-password fetch error:', err);
  } finally {
    setAuthBtnLoading('forgot-btn', false, 'Send reset link');
  }
}

async function submitReset() {
  hideAuthError(); hideAuthSuccess();
  const pw = document.getElementById('reset-password')?.value || '';
  if (!pw)          { showAuthError('Please choose a new password (8+ characters)'); return; }
  if (!_resetToken) { showAuthError('Reset link missing — open the link from your email again.'); return; }

  setAuthBtnLoading('reset-btn', true, 'Set new password');
  try {
    const r = await fetch('/auth/reset-password', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      credentials: 'same-origin',
      body: JSON.stringify({token: _resetToken, password: pw}),
    });
    const data = await r.json().catch(() => ({}));
    if (!r.ok) { showAuthError(data.error || 'Password reset failed'); return; }
    _resetToken = null;
    history.replaceState({}, '', location.pathname);   // drop ?reset=… from the URL
    switchAuthTab('login');
    showAuthSuccess(data.message || 'Password updated. You can log in now.');
  } catch (err) {
    showAuthError('Could not reach server. Is Flask running?');
    console.error('Reset-password fetch error:', err);
  } finally {
    setAuthBtnLoading('reset-btn', false, 'Set new password');
  }
}

async function resendVerification() {
  const r = await fetch('/auth/resend-verification', {method: 'POST', credentials: 'same-origin'})
    .catch(() => null);
  const d = r ? await r.json().catch(() => ({})) : {};
  if (r && r.ok) showToast(d.message || 'Verification email sent');
  else           showToast(d.error || 'Could not send verification email', 'error');
}

async function signOut() {
  await fetch('/auth/logout', {method: 'POST', credentials: 'same-origin'});
  // Take the offline copies too. They live in a per-origin cache the session
  // cookie does not protect, so leaving them would let the next person on this
  // device read the last one's records simply by going offline.
  try {
    const reg = await navigator.serviceWorker?.ready;
    reg?.active?.postMessage({type: 'arogo-signed-out'});
  } catch (e) {}
  _currentUser = null;
  showAuthScreen();
}

// ── Celebrations: confetti + milestone card ───────────────────────
const STREAK_MILESTONES = [7, 30, 100, 365];

function confettiBurst() {
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const colors = ['#4F8D74', '#5E8299', '#E0A34E', '#D07D4E', '#C15646', '#5A9E70'];
  const n = 42;
  for (let i = 0; i < n; i++) {
    const p = document.createElement('div');
    const size = 6 + Math.random() * 6;
    p.style.cssText =
      `position:fixed;top:-12px;left:${8 + Math.random() * 84}vw;z-index:10001;` +
      `width:${size}px;height:${size * 0.6}px;pointer-events:none;` +
      `background:${colors[i % colors.length]};border-radius:2px`;
    document.body.appendChild(p);
    const fall = p.animate([
      { transform: 'translateY(0) rotate(0deg)', opacity: 1 },
      { transform: `translateY(${70 + Math.random() * 25}vh) ` +
                   `translateX(${(Math.random() - 0.5) * 30}vw) ` +
                   `rotate(${360 + Math.random() * 540}deg)`, opacity: 0 },
    ], { duration: 1600 + Math.random() * 1200, easing: 'cubic-bezier(.2,.6,.4,1)' });
    fall.onfinish = () => p.remove();
  }
}

function celebrate(title, sub = '') {
  confettiBurst();
  const card = document.createElement('div');
  card.style.cssText =
    'position:fixed;top:38%;left:50%;transform:translate(-50%,-50%) scale(.9);' +
    'background:var(--gray-0);border:1px solid var(--gray-100);border-radius:18px;' +
    'padding:26px 34px;text-align:center;z-index:10002;' +
    'box-shadow:0 20px 60px rgba(0,0,0,.25);transition:transform .25s, opacity .3s';
  card.innerHTML =
    `<div style="font-size:34px;margin-bottom:8px">🎉</div>` +
    `<div style="font-size:16px;font-weight:700;color:var(--gray-900)">${escapeHtml(title)}</div>` +
    (sub ? `<div style="font-size:12.5px;color:var(--gray-400);margin-top:5px">${escapeHtml(sub)}</div>` : '');
  document.body.appendChild(card);
  requestAnimationFrame(() => { card.style.transform = 'translate(-50%,-50%) scale(1)'; });
  setTimeout(() => { card.style.opacity = '0'; setTimeout(() => card.remove(), 350); }, 2600);
}

function _celebrateOnce(key, title, sub) {
  const k = `me_celebrated_${_currentUser?.id || 'x'}_${key}`;
  if (localStorage.getItem(k)) return;
  localStorage.setItem(k, '1');
  celebrate(title, sub);
}

// Called after any habit toggle — fires on streak milestones and
// on completing every habit for the day (each at most once)
async function checkHabitCelebrations() {
  const d = await fetch('/api/habits', {credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  const habits = d?.habits || [];
  if (!habits.length) return;
  for (const h of habits) {
    if (h.done_today && STREAK_MILESTONES.includes(h.streak || 0)) {
      _celebrateOnce(`streak_${h.id}_${h.streak}`,
                     `${h.streak}-day streak!`,
                     `“${h.name}” — that's real consistency`);
      return;
    }
  }
  if (habits.every(h => h.done_today)) {
    _celebrateOnce(`allhabits_${localToday()}`,
                   'All habits done today ✅',
                   `${habits.length} of ${habits.length} — clean sweep`);
  }
}

// ── Barcode food scanner ──────────────────────────────────────────
let _bcStream = null;      // active MediaStream (must be stopped on close)
let _bcScanning = false;

async function openBarcodeScanner() {
  const modal = document.getElementById('barcode-modal');
  if (!modal) return;
  modal.style.display = 'flex';
  document.getElementById('bc-result').style.display = 'none';
  document.getElementById('bc-manual').value = '';

  const stage = document.getElementById('bc-scan-stage');
  const hint = document.getElementById('bc-scan-hint');

  // BarcodeDetector is Chrome/Android only; elsewhere use manual entry
  if (!('BarcodeDetector' in window)) {
    stage.style.display = 'none';
    return;
  }
  stage.style.display = '';
  try {
    _bcStream = await navigator.mediaDevices.getUserMedia({
      video: { facingMode: 'environment' } });
    const video = document.getElementById('bc-video');
    video.srcObject = _bcStream;
    await video.play();
    const detector = new BarcodeDetector({
      formats: ['ean_13', 'ean_8', 'upc_a', 'upc_e', 'code_128', 'code_39'] });
    _bcScanning = true;
    _scanLoop(video, detector, hint);
  } catch (e) {
    // Permission denied or no camera — fall back to manual entry
    stage.style.display = 'none';
    console.warn('[barcode] camera unavailable:', e);
  }
}

async function _scanLoop(video, detector, hint) {
  if (!_bcScanning) return;
  try {
    const codes = await detector.detect(video);
    if (codes && codes.length) {
      const code = codes[0].rawValue;
      hint.textContent = 'Found: ' + code;
      _stopBarcodeCamera();
      lookupBarcode(code);
      return;
    }
  } catch (e) { /* transient detect errors are fine */ }
  requestAnimationFrame(() => _scanLoop(video, detector, hint));
}

function _stopBarcodeCamera() {
  _bcScanning = false;
  if (_bcStream) {
    _bcStream.getTracks().forEach(t => t.stop());
    _bcStream = null;
  }
}

function closeBarcodeScanner() {
  _stopBarcodeCamera();
  const modal = document.getElementById('barcode-modal');
  if (modal) modal.style.display = 'none';
}

function lookupBarcodeManual() {
  const code = (document.getElementById('bc-manual')?.value || '').trim();
  if (!/^\d{8,14}$/.test(code)) { showToast('Enter a valid 8–14 digit barcode', 'error'); return; }
  _stopBarcodeCamera();
  lookupBarcode(code);
}

async function lookupBarcode(code) {
  const box = document.getElementById('bc-result');
  box.style.display = '';
  box.innerHTML = '<div style="font-size:13px;color:var(--gray-400)">Looking up…</div>';
  const r = await fetch(`/api/food/barcode/${encodeURIComponent(code)}`,
                        {credentials: 'same-origin'});
  const d = await r.json().catch(() => ({}));
  if (!r.ok || !d.found) {
    box.innerHTML = `
      <div style="font-size:13px;color:var(--gray-600);margin-bottom:8px">
        ${escapeHtml(d.error || 'Not found.')}</div>
      <button class="qlg-chip" data-ev-click="renderScanForm({&quot;barcode&quot;:&quot;${escapeHtml(code)}&quot;,&quot;name&quot;:&quot;&quot;,&quot;serving_g&quot;:100})">${t('Add manually')}</button>`;
    return;
  }
  renderScanForm(d.food, d.food.source);
}

function renderScanForm(food, source) {
  const box = document.getElementById('bc-result');
  const f = k => Number(food[k] || 0);
  const src = source === 'saved'
    ? '<span style="color:var(--teal-600)">✓ Saved earlier</span>'
    : source === 'openfoodfacts'
      ? '<span style="color:var(--gray-400)">from Open Food Facts</span>' : '';
  window._scanBarcode = food.barcode || '';
  box.innerHTML = `
    <div style="border-top:1px solid var(--gray-100);padding-top:12px">
      <div class="qlg-label">Name ${src}</div>
      <input type="text" class="form-input" id="bc-name" value="${escapeHtml(food.name || '')}"
             placeholder="Food name" style="width:100%;margin-bottom:6px">
      <div style="font-size:11px;color:var(--gray-400);margin-bottom:6px">Per ${f('serving_g') || 100}g</div>
      <div class="bc-nutri-grid">
        <div><label>Calories</label><input type="number" class="form-input" id="bc-cal" value="${f('calories')}"></div>
        <div><label>Protein (g)</label><input type="number" class="form-input" id="bc-protein" value="${f('protein')}"></div>
        <div><label>Carbs (g)</label><input type="number" class="form-input" id="bc-carbs" value="${f('carbs')}"></div>
        <div><label>Fat (g)</label><input type="number" class="form-input" id="bc-fat" value="${f('fat')}"></div>
        <div><label>Fiber (g)</label><input type="number" class="form-input" id="bc-fiber" value="${f('fiber')}"></div>
        <div><label>Sugar (g)</label><input type="number" class="form-input" id="bc-sugar" value="${f('sugar')}"></div>
        <div><label>Sodium (mg)</label><input type="number" class="form-input" id="bc-sodium" value="${f('sodium')}"></div>
      </div>
      <button class="btn-primary" style="width:100%" data-ev-click="saveScannedFood()">${t('Save to my foods')}</button>
    </div>`;
}

async function saveScannedFood() {
  const val = id => parseFloat(document.getElementById(id)?.value) || 0;
  const name = (document.getElementById('bc-name')?.value || '').trim();
  if (!name) { showToast('Give the food a name', 'error'); return; }
  const payload = {
    name, barcode: window._scanBarcode || '', serving_g: 100,
    calories: val('bc-cal'), protein: val('bc-protein'), carbs: val('bc-carbs'),
    fat: val('bc-fat'), fiber: val('bc-fiber'), sugar: val('bc-sugar'),
    sodium: val('bc-sodium'), category: 'Scanned',
  };
  const r = await fetch('/api/food/custom', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    credentials: 'same-origin', body: JSON.stringify(payload),
  });
  const d = await r.json().catch(() => ({}));
  if (!r.ok || !d.success) { showToast(d.error || 'Could not save', 'error'); return; }
  closeBarcodeScanner();
  showToast(tformat('📷 %1 saved to your foods', name));
  try { if (document.getElementById('view-food')?.classList.contains('active')) loadFoodTracker(); } catch (e) {}
}

// ── Quick-log FAB + sheet ─────────────────────────────────────────
function toggleQuickLog() {
  const sheet = document.getElementById('quick-log-sheet');
  if (!sheet) return;
  if (sheet.style.display === 'none') openQuickLog();
  else closeQuickLog();
}
function closeQuickLog() {
  const sheet = document.getElementById('quick-log-sheet');
  if (sheet) sheet.style.display = 'none';
}

async function openQuickLog() {
  const sheet = document.getElementById('quick-log-sheet');
  if (!sheet) return;
  sheet.style.display = 'flex';
  // Label the weight box with the unit we'll actually interpret it as, so a
  // lb-preference user is never asked for "kg" and silently converted.
  sheet.querySelectorAll('[data-unit-ph="weight"]').forEach(el => {
    el.placeholder = weightUnitLabel();
  });

  // Habits: toggle chips for today
  const habitsBox = document.getElementById('qlg-habits');
  fetch('/api/habits', {credentials: 'same-origin'}).then(r => r.json()).then(d => {
    const habits = (d.habits || []).filter(h => h.active !== 0);
    habitsBox.innerHTML = habits.length
      ? habits.map(h =>
          `<button class="qlg-chip${h.done_today ? ' done' : ''}" id="qlg-habit-${h.id}"
                   data-ev-click="quickToggleHabit('${h.id}')">${h.emoji || '⭐'} ${escapeHtml(h.name)}</button>`).join('')
      : '<span style="font-size:12px;color:var(--gray-400)">No habits yet — add one in the Habits view</span>';
  }).catch(() => { habitsBox.innerHTML = ''; });

  // Yesterday's meals shortcut
  const yBox = document.getElementById('qlg-yesterday');
  fetch('/api/food/recent-meals', {credentials: 'same-origin'}).then(r => r.json()).then(d => {
    const items = Object.values(d.yesterday || {}).flat();
    if (!items.length) { yBox.innerHTML = ''; return; }
    window._qlgYesterday = items;
    yBox.innerHTML =
      `<button class="qlg-chip" style="width:100%" data-ev-click="quickCopyYesterday()">
         🍽️ Copy yesterday's meals — ${items.length} item(s), ${Math.round(d.yesterday_total_cal || 0)} kcal
       </button>`;
  }).catch(() => { yBox.innerHTML = ''; });
}

async function quickWater(ml) {
  const r = await loggedFetch('/api/hydration',
    { amount_ml: ml, drink_type: 'water', date_key: localToday() });
  if (r?.success === false) { showToast('Could not log water', 'error'); return; }
  closeQuickLog();
  showToast(r?.queued ? t("Saved offline — it'll sync when you're back online")
                      : tformat('💧 +%1ml logged', ml));
  try { loadWellnessStrip(); } catch (e) {}
}

async function quickMood(mood) {
  const r = await fetch('/api/thoughts', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    credentials: 'same-origin',
    body: JSON.stringify({content: `Quick check-in — feeling ${mood}`, mood, date_key: localToday()}),
  }).then(r => r.json()).catch(() => null);
  if (!r || r.error) { showToast(r?.error || 'Could not log mood', 'error'); return; }
  closeQuickLog();
  showToast('Mood logged 😊');
}

async function quickWeight() {
  const val = parseFloat(document.getElementById('qlg-weight')?.value);
  // The number is in the user's chosen unit; convert to kg (canonical) to save.
  const kg = weightInputToKg(val);
  if (!val || kg < 20 || kg > 400) { showToast(tformat('Enter a weight in %1', weightUnitLabel()), 'error'); return; }
  const r = await fetch('/api/body-metrics', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    credentials: 'same-origin',
    body: JSON.stringify({date_key: localToday(), weight_kg: kg}),
  }).then(r => r.json()).catch(() => null);
  if (!r || r.error) { showToast('Could not save weight', 'error'); return; }
  document.getElementById('qlg-weight').value = '';
  closeQuickLog();
  showToast(tformat('⚖️ %1 saved', fmtWeight(kg)));
}

async function quickToggleHabit(id) {
  const r = await fetch(`/api/habits/${id}/toggle`, {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    credentials: 'same-origin',
    body: JSON.stringify({date_key: localToday()}),
  }).then(r => r.json()).catch(() => null);
  const chip = document.getElementById(`qlg-habit-${id}`);
  if (chip && r) chip.classList.toggle('done', !!r.done);
  try { loadWellnessStrip(); } catch (e) {}
  if (r?.done) { try { checkHabitCelebrations(); } catch (e) {} }
}

async function quickCopyYesterday() {
  const items = window._qlgYesterday || [];
  if (!items.length) return;
  await Promise.all(items.map(item => fetch('/api/food/log', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    credentials: 'same-origin',
    body: JSON.stringify({
      food_id: item.food_id, food_name: item.food_name, meal_type: item.meal_type,
      date_key: localToday(), quantity_g: item.quantity_g,
      calories: item.calories, protein: item.protein, carbs: item.carbs,
      fat: item.fat, fiber: item.fiber,
    }),
  }).catch(() => {})));
  closeQuickLog();
  showToast(tformat('🍽️ %1 item(s) copied from yesterday', items.length));
  try { if (document.getElementById('view-food').classList.contains('active')) loadFoodTracker(); } catch (e) {}
}

// ── Web Push subscription ─────────────────────────────────────────
function _urlB64ToUint8(b64) {
  const pad = '='.repeat((4 - b64.length % 4) % 4);
  const raw = atob((b64 + pad).replace(/-/g, '+').replace(/_/g, '/'));
  return Uint8Array.from([...raw].map(c => c.charCodeAt(0)));
}

// The only reminder path. The client used to run a second one beside it — a
// setInterval loop that fired its own dose/water/habit/sleep/mood
// notifications whenever the tab was open. It was strictly worse and actively
// harmful, so it's gone; don't bring it back:
//
//   - Two notifications for one dose, worded differently, whenever the tab
//     happened to be open. Only the server's had a working button.
//   - Its "✓ Mark as Taken" button emitted the action `taken`, which the
//     service worker doesn't handle — so it fell through to "open the app"
//     and the dose was never logged. The user believed it was.
//   - It registered a second, blob-built service worker at scope '/', which
//     would have displaced the real /sw.js — killing push and offline — if
//     browsers hadn't rejected blob: script URLs.
//
// scheduler.py covers every one of those reminders, works with the tab closed,
// and its action buttons write straight through the service worker.
async function setupPushSubscription() {
  try {
    if (!('serviceWorker' in navigator) || !('PushManager' in window)) return;
    if (Notification.permission !== 'granted') return;
    const reg = await navigator.serviceWorker.ready;
    let sub = await reg.pushManager.getSubscription();
    if (!sub) {
      const cfg = await fetch('/api/push/vapid-public-key', {credentials: 'same-origin'})
        .then(r => r.json()).catch(() => null);
      if (!cfg || !cfg.enabled || !cfg.key) return;
      sub = await reg.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: _urlB64ToUint8(cfg.key),
      });
    }
    await fetch('/api/push/subscribe', {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      credentials: 'same-origin',
      body: JSON.stringify({subscription: sub.toJSON()}),
    });
  } catch (e) {
    console.warn('[push] subscription setup failed:', e);
  }
}

// The other half of the switch, which was missing.
//
// The server endpoint for this existed and nothing ever called it, so there was
// no way to stop push reminders: revoking permission in browser settings stops
// the browser SHOWING them, while the server keeps the subscription and keeps
// sending. A health app pushing "time for your 9pm dose" to someone who turned
// notifications off is a real failure, not a cosmetic one.
//
// Both halves matter and they can fail independently — the browser
// subscription and the server's copy of it — so each is attempted separately.
async function teardownPushSubscription() {
  let endpoint = null;
  try {
    if (!('serviceWorker' in navigator) || !('PushManager' in window)) return false;
    const reg = await navigator.serviceWorker.ready;
    const sub = await reg.pushManager.getSubscription();
    if (!sub) return false;
    endpoint = sub.endpoint;
    try { await sub.unsubscribe(); } catch (e) { /* tell the server regardless */ }
  } catch (e) {
    console.warn('[push] could not read the current subscription:', e);
    return false;
  }
  try {
    await fetch('/api/push/unsubscribe', {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      credentials: 'same-origin', body: JSON.stringify({endpoint}),
    });
  } catch (e) {
    console.warn('[push] the server was not told to stop:', e);
    return false;
  }
  return true;
}

// Called at startup: if the browser permission is gone but the server still
// holds a subscription, clear it. Someone who revokes permission in browser
// settings never comes back through the app's own off switch.
async function reconcilePushPermission() {
  try {
    if (!('Notification' in window)) return;
    if (Notification.permission === 'granted') return;
    await teardownPushSubscription();
  } catch (e) { /* best effort */ }
}

async function disablePushNotifications() {
  const ok = await teardownPushSubscription();
  showToast(ok ? t('Push reminders are off on this device')
                : t('There were no push reminders to turn off on this device'),
            ok ? 'success' : 'info');
  try { renderPushControl(); } catch (e) {}
}

async function enablePushNotifications() {
  if (!('Notification' in window)) { showToast(t('This browser cannot show notifications'), 'info'); return; }
  if (Notification.permission === 'denied') {
    showToast(t('Notifications are blocked in your browser settings — turn them back on there first'), 'warn');
    return;
  }
  if (Notification.permission === 'default') {
    const perm = await Notification.requestPermission();
    if (perm !== 'granted') { showToast(t('Notifications were not allowed'), 'info'); return; }
  }
  await setupPushSubscription();
  showToast(t('✓ Push reminders are on for this device'), 'success');
  try { renderPushControl(); } catch (e) {}
}

// Per DEVICE, and the wording says so — someone who turns these off on their
// phone has not turned them off on their laptop, and assuming otherwise is how
// a dose reminder gets missed.
async function renderPushControl() {
  const el = document.getElementById('push-control');
  if (!el) return;
  let subscribed = false;
  try {
    const reg = await navigator.serviceWorker.ready;
    subscribed = !!(await reg.pushManager.getSubscription());
  } catch (e) { subscribed = false; }
  const perm = ('Notification' in window) ? Notification.permission : 'unsupported';
  const on = subscribed && perm === 'granted';
  el.innerHTML = `<div class="restore-row">
      <span>${on ? t('Push reminders are on for this device')
                 : t('Push reminders are off for this device')}</span>
      <button class="btn-outline" style="font-size:12px"
              data-ev-click="${on ? 'disablePushNotifications()' : 'enablePushNotifications()'}">
        ${on ? t('Turn off') : t('Turn on')}</button>
    </div>
    ${perm === 'denied' ? `<div class="restore-note">${t(
      'Your browser is blocking notifications for this site. Turning them on here needs that changed in browser settings first.')}</div>` : ''}
    <div class="restore-note">${t(
      'This setting is for this device only. Reminders on your other devices are unaffected.')}</div>`;
  _a11yEnhance(el);
}

// ── PWA: register the service worker ─────────────────────────────
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/sw.js').catch(err =>
      console.warn('[pwa] service worker registration failed:', err));
  });
}

// ── Keyboard: Enter submits the active form ──────────────────────
document.addEventListener('keydown', e => {
  if (e.key !== 'Enter') return;
  const screen = document.getElementById('auth-screen');
  if (!screen || screen.style.display === 'none') return;
  const visible = id => document.getElementById(id)?.style.display !== 'none';
  if      (visible('auth-form-reset'))  submitReset();
  else if (visible('auth-form-forgot')) submitForgot();
  else if (visible('auth-form-login'))  submitLogin();
  else                                  submitRegister();
});

// ── Accessibility: overlay focus + keyboard handling ──
// Every full-screen overlay in the app matches one of these. Kept in one place
// so Escape-to-close, focus-restore, and the Tab focus-trap all agree on what
// "an open overlay" is (the Q1 pass only knew about the first three).
const _A11Y_OVERLAY_SEL = '.modal-overlay, .checkin-overlay, .global-search-wrap, .fd-overlay, #onboarding-overlay';

// Remember the last thing focused OUTSIDE any overlay, so closing a modal can
// return focus where it was instead of dumping it at the top of the document.
let _a11yLastFocus = null;
document.addEventListener('focusin', e => {
  const t = e.target;
  if (t && t.closest && !t.closest(_A11Y_OVERLAY_SEL)) _a11yLastFocus = t;
});

function _a11yShown(el) {
  // Robust "is it visible" that works for position:fixed overlays too, where
  // offsetParent is always null even when the element is on screen.
  const st = getComputedStyle(el);
  if (st.display === 'none' || st.visibility === 'hidden') return false;
  return !!(el.offsetWidth || el.offsetHeight || el.getClientRects().length);
}
function _a11yVisibleOverlays() {
  return [...document.querySelectorAll(_A11Y_OVERLAY_SEL)].filter(_a11yShown);
}
function _a11yTopOverlay() {
  const open = _a11yVisibleOverlays();
  return open.length ? open[open.length - 1] : null;
}
function _a11yFocusables(el) {
  return [...el.querySelectorAll(
    'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),' +
    'textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')]
    .filter(n => _a11yShown(n) || n === document.activeElement);
}

// Escape closes the topmost open overlay and restores focus.
document.addEventListener('keydown', e => {
  if (e.key !== 'Escape') return;
  const top = _a11yTopOverlay();
  if (!top) return;
  if (top.id === 'feature-dir-overlay') top.remove();   // this one is built/torn-down
  else top.style.display = 'none';
  e.preventDefault();
  try { if (_a11yLastFocus && document.contains(_a11yLastFocus)) _a11yLastFocus.focus(); } catch (err) {}
});

// Trap Tab within the topmost overlay so keyboard focus can't wander behind it.
document.addEventListener('keydown', e => {
  if (e.key !== 'Tab') return;
  const top = _a11yTopOverlay();
  if (!top) return;
  const f = _a11yFocusables(top);
  if (!f.length) return;
  const first = f[0], last = f[f.length - 1];
  const active = document.activeElement;
  if (e.shiftKey && (active === first || !top.contains(active))) { last.focus(); e.preventDefault(); }
  else if (!e.shiftKey && active === last) { first.focus(); e.preventDefault(); }
});

// Enter/Space activate a non-native clickable (div/span carrying data-ev-click
// that we've marked role="button"). Bridges the CSP-safe delegation to keyboard.
document.addEventListener('keydown', e => {
  if (e.key !== 'Enter' && e.key !== ' ' && e.key !== 'Spacebar') return;
  const el = e.target;
  if (!el || el.getAttribute('role') !== 'button' || !el.hasAttribute('data-ev-click')) return;
  const tag = el.tagName;
  if (tag === 'BUTTON' || tag === 'A' || tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
  e.preventDefault();
  try { _evRun(el.getAttribute('data-ev-click'), el, e); } catch (err) {}
});

// ── Accessibility: label modals + icon-only controls for screen readers ──
function _applyA11yLabels() {
  document.querySelectorAll('.modal').forEach(m => {
    m.setAttribute('role', 'dialog');
    m.setAttribute('aria-modal', 'true');
    const title = m.querySelector('.modal-title');
    if (title && !m.getAttribute('aria-label')) m.setAttribute('aria-label', title.textContent.trim());
  });
  document.querySelectorAll('.modal-close').forEach(b => {
    if (!b.getAttribute('aria-label')) b.setAttribute('aria-label', 'Close');
  });
}
document.addEventListener('DOMContentLoaded', _applyA11yLabels);

// ── Accessibility: make rendered markup keyboard- & screen-reader-friendly ──
// Runs over the shell on load and over each view after it renders. Idempotent
// (marks processed elements) so repeat passes on navigation stay cheap.
const _A11Y_NATIVE = { BUTTON: 1, A: 1, INPUT: 1, SELECT: 1, TEXTAREA: 1, LABEL: 1 };
let _a11yIdSeq = 0;
function _a11yEnhance(root) {
  if (!root || !root.querySelectorAll) return;

  // 1. Keyboard-operable click surfaces: a div/span carrying data-ev-click is
  //    mouse-only. Give it button semantics so it's focusable + Enter/Space
  //    works (see the keydown bridge above). Skip native controls and the
  //    click-outside backdrops (announcing those as buttons is noise).
  root.querySelectorAll('[data-ev-click]:not([data-a11y])').forEach(el => {
    el.setAttribute('data-a11y', '1');
    if (_A11Y_NATIVE[el.tagName] || el.getAttribute('role')) return;
    const ev = el.getAttribute('data-ev-click') || '';
    if (/backdropClose/.test(ev)) return;                 // dismiss-on-outside-click, not a control
    el.setAttribute('role', 'button');
    if (!el.hasAttribute('tabindex')) el.setAttribute('tabindex', '0');
  });

  // 2. Hide purely decorative inline icons from the a11y tree — every icon in
  //    this app sits beside its own visible text label, so an unlabeled SVG is
  //    just duplicate noise for a screen reader.
  root.querySelectorAll('svg:not([data-a11y])').forEach(svg => {
    svg.setAttribute('data-a11y', '1');
    if (svg.getAttribute('role') === 'img' || svg.getAttribute('aria-label')) return;
    svg.setAttribute('aria-hidden', 'true');
    svg.setAttribute('focusable', 'false');
  });

  // 2b. Name the icon-only buttons. With every icon inside them marked
  //     aria-hidden by the rule above, a button whose only content is an SVG
  //     announces as "button" and nothing else — which is most of the toolbar
  //     controls in this app. Where the button already carries a title (a
  //     tooltip written for sighted users), that text is the name; a title is
  //     not reliably announced on its own, and copying it costs nothing.
  root.querySelectorAll('button:not([data-a11y-name])').forEach(btn => {
    btn.setAttribute('data-a11y-name', '1');
    if (btn.getAttribute('aria-label') || btn.getAttribute('aria-labelledby')) return;
    if ((btn.textContent || '').trim()) return;          // it has visible text
    const title = (btn.getAttribute('title') || '').trim();
    if (title) btn.setAttribute('aria-label', title);
  });

  // 3. Programmatically associate visible labels with their control. The app's
  //    labels rely on proximity (no for=); wire them up so a screen reader
  //    announces the field name, without editing every form by hand.
  root.querySelectorAll('label.form-label:not([data-a11y])').forEach(lbl => {
    lbl.setAttribute('data-a11y', '1');
    if (lbl.htmlFor || lbl.querySelector('input,select,textarea')) return;
    let ctl = lbl.nextElementSibling;
    while (ctl && !/^(INPUT|SELECT|TEXTAREA)$/.test(ctl.tagName)) ctl = ctl.nextElementSibling;
    if (!ctl) return;
    if (!ctl.id) ctl.id = 'a11y-f-' + (++_a11yIdSeq);
    lbl.htmlFor = ctl.id;
  });
}
document.addEventListener('DOMContentLoaded', () => { try { _a11yEnhance(document); } catch (e) {} });

// ── Modern interaction layer: click ripple + animated count-up ───────────────
function _prefersReducedMotion() {
  try { return window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches; }
  catch (e) { return false; }
}

// A material-style ripple on buttons. CSP-safe (element.style, not inline attrs).
document.addEventListener('pointerdown', e => {
  if (_prefersReducedMotion() || (e.button != null && e.button !== 0)) return;
  const btn = e.target.closest && e.target.closest(
    '.btn-primary, .btn-secondary, .btn-outline, .btn-outline-sm, .btn-connect, .btn-sm');
  if (!btn) return;
  const rect = btn.getBoundingClientRect();
  const size = Math.max(rect.width, rect.height);
  const ink = document.createElement('span');
  ink.className = 'ripple-ink';
  ink.style.width = ink.style.height = size + 'px';
  ink.style.left = (e.clientX - rect.left - size / 2) + 'px';
  ink.style.top = (e.clientY - rect.top - size / 2) + 'px';
  btn.classList.add('ripple-host');
  btn.appendChild(ink);
  setTimeout(() => ink.remove(), 620);
}, true);

// Count a number up from 0 for any .count-up[data-to] in `root`. Snaps to the
// final value under reduced-motion. Eased, tabular so width stays steady.
function _fmtCount(n) { return (Math.round(n * 10) / 10 % 1 === 0) ? String(Math.round(n)) : n.toFixed(1); }
function _animateCounts(root) {
  if (!root || !root.querySelectorAll) return;
  const reduce = _prefersReducedMotion();
  root.querySelectorAll('.count-up[data-to]').forEach(el => {
    if (el.dataset.counted) return;
    const to = parseFloat(el.getAttribute('data-to'));
    if (isNaN(to)) return;
    el.dataset.counted = '1';
    const suffix = el.getAttribute('data-suffix') || '';
    if (reduce) { el.textContent = _fmtCount(to) + suffix; return; }
    const dur = 700, start = performance.now();
    const tick = now => {
      const p = Math.min(1, (now - start) / dur);
      const eased = 1 - Math.pow(1 - p, 3);
      el.textContent = _fmtCount(to * eased) + suffix;
      if (p < 1) requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  });
}

