// Render pending todos on dashboard
// ── Questionnaires ─────────────────────────────────────────────────────────
// PHQ-9 and GAD-7. Published instruments, published cut-offs — nothing here is
// the app's opinion, and every result says so.
let _qInstruments = [];

async function loadQuestionnaires() {
  const listEl = document.getElementById('questionnaire-list');
  if (!listEl) return;
  const r = await fetch('/api/questionnaires', {credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!r) return;
  _qInstruments = r.instruments;
  listEl.innerHTML = `
    <div class="panel" style="padding:18px 20px;margin-bottom:20px">
      <div class="restore-note" style="margin-top:0;margin-bottom:12px">${escHtml(r.not_a_diagnosis)}</div>
      <div style="display:flex;gap:10px;flex-wrap:wrap">
        ${r.instruments.map(i => `<button class="btn-outline"
          data-ev-click="startQuestionnaire('${escHtml(i.key)}')">${escHtml(i.name)} — ${escHtml(i.about)}</button>`).join('')}
      </div>
    </div>`;
  loadQuestionnaireHistory();
}

function startQuestionnaire(key) {
  const inst = _qInstruments.find(i => i.key === key);
  const el = document.getElementById('questionnaire-form');
  if (!inst || !el) return;
  el.innerHTML = `
    <div class="panel" style="padding:18px 20px;margin-bottom:20px">
      <h2 class="panel-title" style="margin-bottom:4px">${escHtml(inst.name)}</h2>
      <p style="font-size:13px;color:var(--gray-400);margin-bottom:14px">
        ${t('Over the last 2 weeks, how often have you been bothered by any of the following?')}</p>
      ${inst.items.map((item, idx) => `
        <div class="form-group">
          <label class="form-label" style="font-weight:500">${idx + 1}. ${escHtml(item)}</label>
          <select class="form-input" id="q-${escHtml(inst.key)}-${idx}">
            <option value="">${t('Choose…')}</option>
            ${inst.choices.map(c => `<option value="${c.value}">${escHtml(c.label)}</option>`).join('')}
          </select>
        </div>`).join('')}
      <button class="btn-primary" data-ev-click="submitQuestionnaire('${escHtml(inst.key)}')">
        ${t('See my score')}</button>
    </div>`;
  el.scrollIntoView({behavior: 'smooth', block: 'start'});
}

async function submitQuestionnaire(key) {
  const inst = _qInstruments.find(i => i.key === key);
  if (!inst) return;
  const answers = inst.items.map((_, idx) => {
    const v = document.getElementById(`q-${key}-${idx}`)?.value;
    return v === '' || v === undefined ? null : Number(v);
  });
  if (answers.some(a => a === null)) {
    // Not scored with blanks treated as zero: that reads as "not at all" and
    // would quietly lower the result.
    showToast(t('Please answer every question.'), 'error');
    return;
  }
  const r = await fetch('/api/questionnaires/' + encodeURIComponent(key), {
    method: 'POST', credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'}, body: JSON.stringify({answers}),
  }).then(r => r.json()).catch(() => null);
  if (!r || !r.success) { showToast((r && r.error) || t('Could not score that'), 'error'); return; }

  const el = document.getElementById('questionnaire-form');
  // The crisis block comes FIRST and is not collapsible. A positive answer to
  // "thoughts of being better off dead" is not a footnote under a score.
  const risk = r.risk ? `
    <div class="rh-banner" role="alert" style="display:block">
      <b>${escHtml(r.risk.headline)}</b>
      <p style="margin:8px 0">${escHtml(r.risk.ask)}</p>
      <p style="margin:8px 0"><b>${escHtml(r.risk.urgent)}</b></p>
      ${r.risk.numbers.length ? `<div class="restore-list">${r.risk.numbers.map(n =>
        `<div class="restore-row"><span>${escHtml(n.label)}</span><b>${escHtml(n.number)}</b></div>`).join('')}</div>`
        : `<p style="margin:8px 0">${escHtml(r.risk.no_numbers_note || '')}</p>`}
    </div>` : '';
  el.innerHTML = `
    <div class="panel" style="padding:18px 20px;margin-bottom:20px">
      ${risk}
      <h2 class="panel-title" style="margin-bottom:4px">${escHtml(r.name)} · ${r.score}/${r.max}</h2>
      <p style="font-size:15px;margin-bottom:10px">${t('Band')}: <b>${escHtml(r.band)}</b></p>
      <div class="restore-note" style="margin-top:0">${escHtml(r.not_a_diagnosis)}</div>
      <div style="display:flex;gap:8px;margin-top:12px;flex-wrap:wrap">
        <button class="btn-outline" data-ev-click="window.print()">${t('Print for my doctor')}</button>
        <button class="btn-outline" data-ev-click="startQuestionnaire('${escHtml(key)}')">${t('Start again')}</button>
      </div>
    </div>`;
  el.scrollIntoView({behavior: 'smooth', block: 'start'});
  loadQuestionnaireHistory();
}

async function loadQuestionnaireHistory() {
  const el = document.getElementById('questionnaire-history');
  if (!el) return;
  const r = await fetch('/api/questionnaires/runs', {credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!r || !r.runs.length) { el.innerHTML = ''; return; }
  // Listed as dates and scores. No line drawn between them, and nothing said
  // about a direction — two scores a week apart are two days.
  el.innerHTML = `
    <div class="panel" style="padding:18px 20px">
      <h2 class="panel-title" style="margin-bottom:10px">${t('Past scores')}</h2>
      <div class="restore-list">${r.runs.map(run => `
        <div class="restore-row">
          <span><b>${escHtml(run.name)}</b> · ${escHtml(run.taken_on)}</span>
          <span>${run.score}/${run.max} · <span class="restore-removes">${escHtml(run.band || '')}</span></span>
        </div>`).join('')}</div>
      <div class="restore-note">${t('Each of these is one day. Arogo does not join them into a trend — a doctor reads them alongside everything else going on.')}</div>
    </div>`;
}

// ── Blood donations ────────────────────────────────────────────────────────
async function loadDonations() {
  const listEl = document.getElementById('donation-list');
  const eligEl = document.getElementById('donation-eligibility');
  if (!listEl) return;
  const [d, e] = await Promise.all([
    fetch('/api/donations', {credentials: 'same-origin'}).then(r => r.json()).catch(() => null),
    fetch('/api/donations/eligibility', {credentials: 'same-origin'}).then(r => r.json()).catch(() => null),
  ]);
  const sel = document.getElementById('donation-kind');
  if (sel && d && !sel.childElementCount) {
    sel.innerHTML = d.kinds.map(k => `<option value="${escHtml(k.key)}">${escHtml(k.label)}</option>`).join('');
  }
  if (eligEl && e) {
    eligEl.innerHTML = `
      <div class="panel" style="padding:18px 20px;margin-bottom:20px">
        <h2 class="panel-title" style="margin-bottom:10px">${t('Next eligible')}</h2>
        <div class="restore-list">${e.kinds.map(k => `
          <div class="restore-row"><span>${escHtml(k.label)}</span>
            <span>${k.eligible_from
              ? escHtml(k.eligible_from) + (k.days_to_go ? ' · ' + tformat('%1 days', k.days_to_go) : ' · ' + t('date passed'))
              : '<span class="restore-removes">' + t('no donation recorded') + '</span>'}</span></div>`).join('')}</div>
        <div class="restore-note">${escHtml(e.note)}</div>
      </div>`;
  }
  if (d) {
    listEl.innerHTML = d.donations.length
      ? `<div class="panel" style="padding:18px 20px"><div class="restore-list">${d.donations.map(x => `
          <div class="restore-row">
            <span><b>${escHtml(x.kind_label)}</b> · ${escHtml(x.donated_on)}
              ${x.place ? '<br><span class="restore-removes">' + escHtml(x.place) + '</span>' : ''}</span>
            <button class="btn-outline" style="font-size:12px"
                    data-ev-click="deleteDonation('${escHtml(x.id)}')">${t('Remove')}</button>
          </div>`).join('')}</div></div>`
      : `<div class="panel" style="padding:18px 20px"><div class="restore-note">${t('Nothing recorded yet.')}</div></div>`;
  }
}

async function saveDonation() {
  const body = {
    kind: document.getElementById('donation-kind')?.value || 'whole',
    donated_on: document.getElementById('donation-date')?.value || '',
    place: document.getElementById('donation-place')?.value || '',
  };
  const r = await fetch('/api/donations', {method: 'POST', credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'}, body: JSON.stringify(body)})
    .then(r => r.json()).catch(() => null);
  if (r && r.success) {
    const p = document.getElementById('donation-place'); if (p) p.value = '';
    showToast(t('✓ Donation recorded'), 'success');
    loadDonations();
  } else {
    showToast((r && r.error) || t('Could not save that'), 'error');
  }
}

function deleteDonation(id) {
  undoable(t('Removing this donation'), async () => {
    await fetch('/api/donations/' + encodeURIComponent(id),
                {method: 'DELETE', credentials: 'same-origin'}).catch(() => {});
    loadDonations();
  });
}

// ── Account activity ───────────────────────────────────────────────────────
// Where you're signed in, what changed, and whether your share links were
// opened. The device names are coarse on purpose — enough to recognise your own
// phone, not enough to be a location history.
function _agoText(iso) {
  if (!iso) return '';
  const secs = (Date.now() - new Date(iso).getTime()) / 1000;
  if (!isFinite(secs) || secs < 0) return String(iso).slice(0, 10);
  if (secs < 3600) return t('just now');
  if (secs < 86400) return tformat('%1 hours ago', Math.floor(secs / 3600));
  if (secs < 86400 * 30) return tformat('%1 days ago', Math.floor(secs / 86400));
  return String(iso).slice(0, 10);
}

// ── "What changed" on the medicines page ───────────────────────────────────
// The compact answer to the question an appointment opens with, where the
// medicines already are. The full version lives in the appointment pack; this
// is the glance.
async function loadMedChanges() {
  const el = document.getElementById('med-changes-card');
  if (!el) return;
  const r = await fetch('/api/medicines/changes', {credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  // Nothing changed is the common case and does not deserve a card.
  if (!r || !r.changes || !r.changes.length) { el.innerHTML = ''; return; }

  const anchor = r.anchor || {};
  const since = anchor.kind === 'appointment'
    ? tformat('since your visit on %1', anchor.date)
    : tformat('in the last %1 days', 90);
  const shown = r.changes.slice(0, 4);
  el.innerHTML = `<div class="panel" style="padding:14px 18px;margin-bottom:16px">
      <div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;align-items:baseline">
        <b style="font-size:14px">${tformat('%1 changes %2', r.changes.length, since)}</b>
        <button class="btn-outline" style="font-size:12px"
                data-ev-click="switchView('visitpack')">${t('Take this to my appointment')}</button>
      </div>
      <ul class="vp-list" style="margin-top:8px">${shown.map(c =>
        `<li>${escHtml(c.date)} — <b>${escHtml(c.name)}</b>: ${escHtml(c.label)}${
          c.detail ? ' <span class="vp-dim">' + escHtml(c.detail) + '</span>' : ''}</li>`).join('')}
      </ul>
      ${r.changes.length > shown.length
        ? `<div class="restore-note">${tformat('and %1 more',
            r.changes.length - shown.length)}</div>` : ''}
    </div>`;
  _a11yEnhance(el);
}

// "Last 1 days" and "1 falls" both read like a template that never got filled
// in, which is a bad look on a page someone is about to show a clinician. The
// singular form is a separate translatable string rather than a stripped "s",
// because plural rules are not English's to impose on every language.
function _nDays(n)      { return tformat(n === 1 ? 'Last %1 day' : 'Last %1 days', n); }
function _nDaysPlain(n) { return tformat(n === 1 ? '%1 day' : '%1 days', n); }

// ── Falls ───────────────────────────────────────────────────────────────────
// The app builds for elder care throughout — a care circle, dependents, a
// large-type mode — and had nowhere to write down the one event that matters
// most in that setting.
//
// The page shows counts and where they happened, and stops there. No risk
// score, no severity grade, no advice: those are clinical calls, and a number
// invented here would look exactly like a real assessment.

let _fallsMeta = null;

async function loadFalls() {
  const list = document.getElementById('falls-list');
  if (!list) return;
  if (!_fallsMeta) {
    _fallsMeta = await fetch('/api/falls/meta', {credentials: 'same-origin'})
      .then(r => r.json()).catch(() => ({places: [], times: []}));
  }
  const [d, s] = await Promise.all([
    fetch('/api/falls', {credentials: 'same-origin'}).then(r => r.json()).catch(() => null),
    fetch('/api/falls/summary', {credentials: 'same-origin'}).then(r => r.json()).catch(() => null),
  ]);
  if (!d) { list.innerHTML = `<div class="panel" style="padding:18px 20px">${t('Could not load your falls')}</div>`; return; }

  const sum = document.getElementById('falls-summary');
  if (sum) sum.innerHTML = _fallsSummaryHtml(s);

  if (!d.falls.length) {
    list.innerHTML = `<div class="panel" style="padding:22px 20px">
      <div class="restore-note" style="margin:0">${t(
        'Nothing recorded yet. Add a fall when it happens — the details fade fast, and this is the list a doctor asks for.')}</div></div>`;
    return;
  }
  list.innerHTML = `<div class="panel" style="padding:8px 20px">${d.falls.map(f => `
      <div class="restore-row" style="align-items:flex-start">
        <span><b>${escHtml(f.fell_on)}</b>${f.time_label ? ' · ' + escHtml(f.time_label) : ''}
          ${f.place_label ? '<br>' + escHtml(f.place_label) : ''}
          ${f.what_happened ? `<br><span class="vp-dim">${escHtml(f.what_happened)}</span>` : ''}
          ${f.injured ? `<br><span class="vp-dim">${t('Injured')}${f.injury ? ': ' + escHtml(f.injury) : ''}${
            f.saw_someone ? ' · ' + t('saw someone about it') : ''}</span>` : ''}
          ${f.got_up_alone === false ? `<br><span class="vp-dim">${t('needed help getting up')}</span>` : ''}
        </span>
        <button class="btn-outline" style="font-size:12px"
                data-ev-click="deleteFall('${escHtml(f.id)}')">${t('Remove')}</button>
      </div>`).join('')}</div>`;
  _a11yEnhance(list);
}

function _fallsSummaryHtml(s) {
  if (!s || !s.has_any) {
    return s ? `<div class="panel" style="padding:14px 20px">
        <div class="restore-note" style="margin:0">${escHtml(s.note || '')}</div></div>` : '';
  }
  const row = (label, value) =>
    `<div class="restore-row"><span>${escHtml(label)}</span><b>${escHtml(String(value))}</b></div>`;
  return `<div class="panel" style="padding:14px 20px;margin-bottom:16px">
      ${row(tformat('In the last %1', _nDaysPlain(s.days)),
            // "1 falls" reads like a placeholder on a page someone is about to
            // show a doctor.
            tformat(s.total === 1 ? '%1 fall' : '%1 falls', s.total))}
      ${s.injured ? row(t('With an injury'), s.injured) : ''}
      ${s.needed_help_up ? row(t('Needed help getting up'), s.needed_help_up) : ''}
      ${s.by_place.length > 1 ? `<div style="margin-top:10px">
        <div class="vp-dim" style="font-size:12px;margin-bottom:4px">${t('Where')}</div>
        ${s.by_place.map(p => `<div class="restore-row"><span>${escHtml(p.label)}</span><b>${p.count}</b></div>`).join('')}
      </div>` : ''}
      <div class="restore-note">${escHtml(s.not_a_score)}</div>
    </div>`;
}

function openFallForm() {
  const box = document.getElementById('fall-form');
  if (!box) return;
  const places = (_fallsMeta?.places || []).map(p =>
    `<option value="${escHtml(p.key)}">${escHtml(t(p.label))}</option>`).join('');
  const times = (_fallsMeta?.times || []).map(p =>
    `<option value="${escHtml(p.key)}">${escHtml(t(p.label))}</option>`).join('');
  box.innerHTML = `<div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <div style="display:grid;gap:12px">
        <div>
          <label class="form-label" for="fall-date">${t('When')}</label>
          <input type="date" class="form-input" id="fall-date" value="${localToday()}"
                 style="max-width:200px">
        </div>
        <div>
          <label class="form-label" for="fall-time">${t('Time of day')}</label>
          <select class="form-input" id="fall-time" style="max-width:220px">
            <option value="">${t('Not sure')}</option>${times}</select>
        </div>
        <div>
          <label class="form-label" for="fall-place">${t('Where')}</label>
          <select class="form-input" id="fall-place" style="max-width:260px">
            <option value="">${t('Not sure')}</option>${places}</select>
        </div>
        <div>
          <label class="form-label" for="fall-what">${t('What happened')}</label>
          <textarea class="form-input" id="fall-what" rows="2"
            placeholder="${t('In your own words — tripped, felt dizzy, slipped')}"></textarea>
        </div>
        <label style="display:flex;gap:8px;align-items:center;font-size:13.5px">
          <input type="checkbox" id="fall-injured"> ${t('I was hurt')}</label>
        <div>
          <label class="form-label" for="fall-injury">${t('Injury, if any')}</label>
          <input class="form-input" id="fall-injury" style="max-width:340px">
        </div>
        <label style="display:flex;gap:8px;align-items:center;font-size:13.5px">
          <input type="checkbox" id="fall-saw"> ${t('I saw a doctor or nurse about it')}</label>
        <div>
          <label class="form-label" for="fall-gotup">${t('Getting up')}</label>
          <select class="form-input" id="fall-gotup" style="max-width:260px">
            <option value="">${t('Not recorded')}</option>
            <option value="1">${t('I got up on my own')}</option>
            <option value="0">${t('I needed help')}</option>
          </select>
        </div>
      </div>
      <div class="form-actions" style="margin-top:16px">
        <button class="btn-primary" data-ev-click="saveFall()">${t('Save')}</button>
        <button class="btn-outline" data-ev-click="closeFallForm()">${t('Cancel')}</button>
      </div>
    </div>`;
  _a11yEnhance(box);
  document.getElementById('fall-date')?.focus();
}

function closeFallForm() {
  const box = document.getElementById('fall-form');
  if (box) box.innerHTML = '';
}

async function saveFall() {
  const v = id => document.getElementById(id)?.value || '';
  const gotUp = v('fall-gotup');
  const r = await fetch('/api/falls', {
    method: 'POST', credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({
      fell_on: v('fall-date'), time_of_day: v('fall-time'), place: v('fall-place'),
      what_happened: v('fall-what'),
      injured: document.getElementById('fall-injured')?.checked ? 1 : 0,
      injury: v('fall-injury'),
      saw_someone: document.getElementById('fall-saw')?.checked ? 1 : 0,
      // '' means not recorded, which is different from "no" — the API keeps
      // the distinction, so the UI must not flatten it here.
      got_up_alone: gotUp === '' ? null : gotUp,
    }),
  }).then(r => r.json()).catch(() => null);
  if (!r || !r.success) { showToast(t('Could not save that'), 'error'); return; }
  closeFallForm();
  showToast(t('✓ Recorded'), 'success');
  loadFalls();
}

function deleteFall(id) {
  undoable(t('Removing this fall…'), async () => {
    await fetch('/api/falls/' + encodeURIComponent(id),
                {method: 'DELETE', credentials: 'same-origin'});
    loadFalls();
  });
}

// ── Hearing ─────────────────────────────────────────────────────────────────
// Beside dental and vision, which already work this way: the app holds what a
// professional said, in their words, plus the upkeep that follows. It never
// reads an audiogram.

async function loadHearing() {
  const body = document.getElementById('hearing-body');
  if (!body) return;
  const [d, o] = await Promise.all([
    fetch('/api/hearing', {credentials: 'same-origin'}).then(r => r.json()).catch(() => null),
    fetch('/api/hearing/overview', {credentials: 'same-origin'}).then(r => r.json()).catch(() => null),
  ]);
  if (!d) { body.innerHTML = `<div class="panel" style="padding:18px 20px">${t('Could not load your hearing records')}</div>`; return; }
  if (!d.records.length) {
    body.innerHTML = `<div class="panel" style="padding:22px 20px">
      <div class="restore-note" style="margin:0">${t(
        'Nothing here yet. Add a hearing test when you have one, and your aids — the battery type and service date are exactly what nobody can find when they need it.')}</div></div>`;
    return;
  }
  const due = (o && o.due || []).filter(x => x.date);
  body.innerHTML = `
    ${due.length ? `<div class="panel" style="padding:14px 20px;margin-bottom:16px">
      <div class="vp-dim" style="font-size:12px;margin-bottom:6px">${t('Dates you set')}</div>
      ${due.map(x => `<div class="restore-row"><span>${escHtml(x.label)}</span>
        <b${x.overdue ? ' style="color:var(--warn,#8a6100)"' : ''}>${escHtml(x.date)}</b></div>`).join('')}
    </div>` : ''}
    <div class="panel" style="padding:8px 20px">${d.records.map(r => `
      <div class="restore-row" style="align-items:flex-start">
        <span><b>${escHtml(r.kind_label)}</b> · ${escHtml(r.record_date)}
          ${r.provider ? '<br>' + escHtml(r.provider) : ''}
          ${r.device ? `<br><span class="vp-dim">${escHtml(r.device)}${
            r.battery ? ' · ' + tformat('battery %1', escHtml(r.battery)) : ''}</span>` : ''}
          ${(r.left_ear || r.right_ear) ? `<br><span class="vp-dim">${
            [r.left_ear ? tformat('left: %1', escHtml(r.left_ear)) : '',
             r.right_ear ? tformat('right: %1', escHtml(r.right_ear)) : ''
            ].filter(Boolean).join(' · ')}</span>` : ''}
          ${r.finding ? `<br><span class="vp-dim">${escHtml(r.finding)}</span>` : ''}
          ${r.serviced_on ? `<br><span class="vp-dim">${tformat('serviced %1', escHtml(r.serviced_on))}</span>` : ''}
        </span>
        <button class="btn-outline" style="font-size:12px"
                data-ev-click="deleteHearing('${escHtml(r.id)}')">${t('Remove')}</button>
      </div>`).join('')}</div>
    <div class="panel" style="padding:14px 20px;margin-top:16px">
      <div class="restore-note" style="margin:0">${t(
        'What a test found is recorded here as the clinician reported it. Arogo does not read audiograms or judge how well you hear.')}</div>
    </div>`;
  _a11yEnhance(body);
}

function openHearingForm(kind) {
  const box = document.getElementById('hearing-form');
  if (!box) return;
  const isAid = kind === 'aid';
  box.innerHTML = `<div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <div style="display:grid;gap:12px">
        <div>
          <label class="form-label" for="hear-date">${isAid ? t('Fitted on') : t('Test date')}</label>
          <input type="date" class="form-input" id="hear-date" value="${localToday()}" style="max-width:200px">
        </div>
        <div>
          <label class="form-label" for="hear-provider">${t('Who')}</label>
          <input class="form-input" id="hear-provider" style="max-width:340px"
                 placeholder="${t('Clinic or audiologist')}">
        </div>
        ${isAid ? `
        <div>
          <label class="form-label" for="hear-device">${t('Device')}</label>
          <input class="form-input" id="hear-device" style="max-width:340px"
                 placeholder="${t('Make and model')}">
        </div>
        <div>
          <label class="form-label" for="hear-battery">${t('Battery')}</label>
          <input class="form-input" id="hear-battery" style="max-width:240px"
                 placeholder="${t('e.g. size 312, or rechargeable')}">
        </div>
        <div>
          <label class="form-label" for="hear-serviced">${t('Last serviced')}</label>
          <input type="date" class="form-input" id="hear-serviced" style="max-width:200px">
        </div>` : `
        <div>
          <label class="form-label" for="hear-left">${t('Left ear — what they said')}</label>
          <input class="form-input" id="hear-left" style="max-width:420px">
        </div>
        <div>
          <label class="form-label" for="hear-right">${t('Right ear — what they said')}</label>
          <input class="form-input" id="hear-right" style="max-width:420px">
        </div>
        <div>
          <label class="form-label" for="hear-finding">${t('What they told you')}</label>
          <textarea class="form-input" id="hear-finding" rows="2"
            placeholder="${t('In their words, as far as you remember')}"></textarea>
        </div>`}
        <div>
          <label class="form-label" for="hear-next">${t('Next check, if they gave you one')}</label>
          <input type="date" class="form-input" id="hear-next" style="max-width:200px">
        </div>
      </div>
      <div class="form-actions" style="margin-top:16px">
        <button class="btn-primary" data-ev-click="saveHearing('${escHtml(kind)}')">${t('Save')}</button>
        <button class="btn-outline" data-ev-click="closeHearingForm()">${t('Cancel')}</button>
      </div>
    </div>`;
  _a11yEnhance(box);
  document.getElementById('hear-date')?.focus();
}

function closeHearingForm() {
  const box = document.getElementById('hearing-form');
  if (box) box.innerHTML = '';
}

async function saveHearing(kind) {
  const v = id => document.getElementById(id)?.value || '';
  const r = await fetch('/api/hearing', {
    method: 'POST', credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({
      kind, record_date: v('hear-date'), provider: v('hear-provider'),
      device: v('hear-device'), battery: v('hear-battery'),
      serviced_on: v('hear-serviced'), left_ear: v('hear-left'),
      right_ear: v('hear-right'), finding: v('hear-finding'),
      next_check: v('hear-next'),
    }),
  }).then(r => r.json()).catch(() => null);
  if (!r || !r.success) { showToast(t('Could not save that'), 'error'); return; }
  closeHearingForm();
  showToast(t('✓ Saved'), 'success');
  loadHearing();
}

function deleteHearing(id) {
  undoable(t('Removing this record…'), async () => {
    await fetch('/api/hearing/' + encodeURIComponent(id),
                {method: 'DELETE', credentials: 'same-origin'});
    loadHearing();
  });
}

// ── Rehab exercises ─────────────────────────────────────────────────────────
// "These exercises, twice a day, for six weeks" — the instruction that follows
// most procedures and that nobody tracks.
//
// The app supplies no exercises and never says whether to push on or stop.
// Pain is recorded because it is the first thing a physiotherapist asks, and
// it is shown back as the user's own number.

async function loadRehab() {
  const el = document.getElementById('rehab-list');
  if (!el) return;
  const d = await fetch('/api/rehab', {credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!d) { el.innerHTML = `<div class="panel" style="padding:18px 20px">${t('Could not load your plans')}</div>`; return; }
  if (!d.plans.length) {
    el.innerHTML = `<div class="panel" style="padding:22px 20px">
      <div class="restore-note" style="margin:0">${t(
        'No plans yet. Add the exercises your physiotherapist gave you, how many times a day, and for how long — Arogo keeps the count, not the programme.')}</div></div>`;
    return;
  }
  el.innerHTML = d.plans.map(p => {
    const a = p.adherence;
    // No target and no verdict — the number and the window it covers.
    const adh = (a && a.pct !== null)
      ? `<div class="restore-row"><span>${_nDays(a.days)}</span>
           <b>${tformat('%1 of %2 sessions', a.done, a.scheduled)} · ${a.pct}%</b></div>`
      : `<div class="restore-note">${escHtml((a && a.note) || t('No sessions scheduled in this window yet.'))}</div>`;
    return `<div class="panel" style="padding:16px 20px;margin-bottom:14px">
      <div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;align-items:baseline">
        <div>
          <b style="font-size:15px">${escHtml(p.name)}</b>
          ${p.ended ? ` <span class="vp-dim">${t('finished')}</span>` : ''}
          <div class="vp-dim" style="font-size:12.5px">
            ${escHtml(tformat('%1 a day', p.times_per_day))}${
              p.reason ? ' · ' + escHtml(p.reason) : ''}${
              p.prescribed_by ? ' · ' + escHtml(p.prescribed_by) : ''}</div>
        </div>
        <div style="display:flex;gap:6px;flex-wrap:wrap">
          ${p.ended ? '' : `<button class="btn-primary" style="font-size:12px"
             data-ev-click="logRehabSession('${escHtml(p.id)}')">${t('Did it')}</button>`}
          <button class="btn-outline" style="font-size:12px"
                  data-ev-click="toggleRehabSessions('${escHtml(p.id)}')">${t('Sessions')}</button>
          <button class="btn-outline" style="font-size:12px"
                  data-ev-click="deleteRehabPlan('${escHtml(p.id)}')">${t('Remove')}</button>
        </div>
      </div>
      ${p.instructions ? `<div class="restore-note">${escHtml(p.instructions)}</div>` : ''}
      ${adh}
      <div id="rehab-pain-${escHtml(p.id)}"></div>
      <div id="rehab-sessions-${escHtml(p.id)}"></div>
    </div>`;
  }).join('');
  _a11yEnhance(el);
}

// The sessions behind the percentage. A number nobody can open is a number
// nobody can correct — and a mis-tapped "did it" would otherwise be permanent.
async function toggleRehabSessions(pid) {
  const box = document.getElementById('rehab-sessions-' + pid);
  if (!box) return;
  if (box.innerHTML) { box.innerHTML = ''; return; }
  box.innerHTML = `<div class="restore-note">${t('Loading…')}</div>`;
  const d = await fetch(`/api/rehab/${encodeURIComponent(pid)}/sessions`,
                        {credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!d || !d.sessions) { box.innerHTML = `<div class="restore-note">${t('Could not load the sessions')}</div>`; return; }
  if (!d.sessions.length) {
    box.innerHTML = `<div class="restore-note">${t('No sessions logged yet.')}</div>`;
    return;
  }
  // Pain numbers listed in date order, with no direction claimed. Two numbers a
  // fortnight apart are two moments, and "improving" is the sentence someone
  // uses to decide whether to keep going.
  box.innerHTML = `<div style="margin-top:12px;padding-top:12px;border-top:1px solid var(--gray-100)">
      ${d.sessions.map(s => `<div class="restore-row">
        <span>${escHtml(s.date_key)}${s.pain_after !== null && s.pain_after !== undefined
          ? ' · ' + tformat('pain %1/10', s.pain_after) : ''}${
          s.notes ? ' · ' + escHtml(s.notes) : ''}</span>
        <button class="btn-outline" style="font-size:12px"
                data-ev-click="deleteRehabSession('${escHtml(s.id)}','${escHtml(pid)}')">${t('Remove')}</button>
      </div>`).join('')}
      <div class="restore-note">${t('Pain is your own number on your own scale, shown as you entered it.')}</div>
    </div>`;
  _a11yEnhance(box);
}

async function deleteRehabSession(lid, pid) {
  const r = await fetch('/api/rehab/session/' + encodeURIComponent(lid),
                        {method: 'DELETE', credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!r || !r.success) { showToast(t('Could not remove that'), 'error'); return; }
  showToast(t('✓ Removed'), 'success');
  // The percentage changes when a session goes, so the whole card is redrawn.
  loadRehab();
}

// Asked after the session, not before: a pain field on the way in reads as a
// gate on whether you are allowed to do your exercises.
function logRehabSession(pid) {
  const box = document.getElementById('rehab-pain-' + pid);
  if (!box) return;
  box.innerHTML = `<div style="margin-top:12px;padding-top:12px;border-top:1px solid var(--gray-100)">
      <label class="form-label" for="rehab-pain-in-${escHtml(pid)}">${t('Pain afterwards, if you want to note it')}</label>
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">
        <input type="number" min="0" max="10" class="form-input" style="max-width:100px"
               id="rehab-pain-in-${escHtml(pid)}" placeholder="0–10"
               aria-label="${t('Pain afterwards, 0 to 10')}">
        <button class="btn-primary" data-ev-click="saveRehabSession('${escHtml(pid)}')">${t('Save')}</button>
        <button class="btn-outline" data-ev-click="saveRehabSession('${escHtml(pid)}',true)">${t('Skip the number')}</button>
      </div>
      <div class="restore-note">${t(
        'Your own scale, recorded as you typed it. Arogo never compares it to a target or tells you whether to carry on.')}</div>
    </div>`;
  _a11yEnhance(box);
  document.getElementById('rehab-pain-in-' + pid)?.focus();
}

async function saveRehabSession(pid, skipPain) {
  const raw = document.getElementById('rehab-pain-in-' + pid)?.value;
  const r = await fetch(`/api/rehab/${encodeURIComponent(pid)}/log`, {
    method: 'POST', credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({pain_after: skipPain ? null : (raw === '' ? null : raw)}),
  }).then(r => r.json()).catch(() => null);
  if (!r || !r.success) { showToast(t('Could not save that'), 'error'); return; }
  showToast(t('✓ Logged'), 'success');
  loadRehab();
}

function openRehabForm() {
  const box = document.getElementById('rehab-form');
  if (!box) return;
  box.innerHTML = `<div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <div style="display:grid;gap:12px">
        <div>
          <label class="form-label" for="rehab-name">${t('What are the exercises for')}</label>
          <input class="form-input" id="rehab-name" style="max-width:420px"
                 placeholder="${t('e.g. Knee exercises after surgery')}">
        </div>
        <div>
          <label class="form-label" for="rehab-by">${t('Who gave them to you')}</label>
          <input class="form-input" id="rehab-by" style="max-width:340px">
        </div>
        <div>
          <label class="form-label" for="rehab-per-day">${t('Times a day')}</label>
          <input type="number" min="1" max="12" class="form-input" id="rehab-per-day"
                 value="2" style="max-width:110px">
        </div>
        <div style="display:flex;gap:12px;flex-wrap:wrap">
          <div>
            <label class="form-label" for="rehab-from">${t('Starting')}</label>
            <input type="date" class="form-input" id="rehab-from" value="${localToday()}" style="max-width:200px">
          </div>
          <div>
            <label class="form-label" for="rehab-until">${t('Until, if you were told')}</label>
            <input type="date" class="form-input" id="rehab-until" style="max-width:200px">
          </div>
        </div>
        <div>
          <label class="form-label" for="rehab-instructions">${t('The exercises themselves')}</label>
          <textarea class="form-input" id="rehab-instructions" rows="4"
            placeholder="${t('Copy what you were given. Arogo does not suggest exercises — yours came from someone who examined you.')}"></textarea>
        </div>
      </div>
      <div class="form-actions" style="margin-top:16px">
        <button class="btn-primary" data-ev-click="saveRehabPlan()">${t('Save')}</button>
        <button class="btn-outline" data-ev-click="closeRehabForm()">${t('Cancel')}</button>
      </div>
    </div>`;
  _a11yEnhance(box);
  document.getElementById('rehab-name')?.focus();
}

function closeRehabForm() {
  const box = document.getElementById('rehab-form');
  if (box) box.innerHTML = '';
}

async function saveRehabPlan() {
  const v = id => document.getElementById(id)?.value || '';
  if (!v('rehab-name').trim()) { showToast(t('Give the plan a name'), 'info'); return; }
  const r = await fetch('/api/rehab', {
    method: 'POST', credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({
      name: v('rehab-name'), prescribed_by: v('rehab-by'),
      times_per_day: v('rehab-per-day'), started_on: v('rehab-from'),
      until_date: v('rehab-until'), instructions: v('rehab-instructions'),
    }),
  }).then(r => r.json()).catch(() => null);
  if (!r || !r.success) { showToast((r && r.error) || t('Could not save that'), 'error'); return; }
  closeRehabForm();
  showToast(t('✓ Saved'), 'success');
  loadRehab();
}

function deleteRehabPlan(pid) {
  undoable(t('Removing this plan…'), async () => {
    await fetch('/api/rehab/' + encodeURIComponent(pid),
                {method: 'DELETE', credentials: 'same-origin'});
    loadRehab();
  });
}

// ── Appointment pack ────────────────────────────────────────────────────────
// Every section here already existed on its own screen. What did not exist was
// the one page you can print and carry, which is why "has anything changed since
// we last saw you?" gets answered from memory in most appointments.
//
// The rendering rule throughout: an empty section says it is empty. Dropping it
// would let the page read as a complete picture of someone's health, and it is
// an index of what happens to be recorded in one app.

let _visitPack = null;

async function loadVisitPack() {
  const body = document.getElementById('visitpack-body');
  if (!body) return;
  const sel = document.getElementById('vp-appointment');

  if (sel && !sel.dataset.filled) {
    const list = await fetch('/api/visit-pack/appointments', {credentials: 'same-origin'})
      .then(r => r.json()).catch(() => null);
    const appts = (list && list.appointments) || [];
    sel.innerHTML = appts.map(a =>
      `<option value="${escHtml(a.id)}">${escHtml(a.date)}${a.time ? ' ' + escHtml(a.time) : ''} — ${
        escHtml(a.title)}${a.upcoming ? '' : ' (' + t('past') + ')'}</option>`).join('')
      // Still useful with nothing booked: the same page over the last 90 days.
      + `<option value="">${t('No particular visit — the last 90 days')}</option>`;
    sel.dataset.filled = '1';
  }

  const chosen = sel ? sel.value : '';
  const url = chosen ? '/api/visit-pack?appointment=' + encodeURIComponent(chosen)
                     : '/api/visit-pack?since=';
  const r = await fetch(url, {credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!r || !r.success) {
    body.innerHTML = `<div class="panel" style="padding:18px 20px">${
      t('Could not build the pack')}</div>`;
    return;
  }
  _visitPack = r.pack;
  body.innerHTML = renderVisitPack(r.pack);
  _a11yEnhance(body);
}

// The window line. People read a printed page as "everything", so the range it
// actually covers is stated at the top rather than implied.
function _vpWindowLine(w) {
  const a = w.anchor || {};
  if (a.kind === 'appointment')
    return tformat('Changes since your visit on %1%2', a.date,
                   a.title ? ' — ' + a.title : '');
  if (a.kind === 'chosen_dates')
    return tformat('From %1 to %2', w.since, w.until);
  return tformat('No earlier appointment recorded, so this covers the last %1 days (from %2)',
                 w.window_days, w.since);
}

function _vpSection(title, inner, emptyText) {
  return `<div class="panel vp-section" style="padding:18px 20px;margin-bottom:16px">
      <h2 class="panel-title" style="margin-bottom:10px">${escHtml(title)}</h2>
      ${inner || `<div class="restore-note">${escHtml(emptyText)}</div>`}
    </div>`;
}

function renderVisitPack(p) {
  const a = p.appointment;
  const head = `<div class="panel" style="padding:18px 20px;margin-bottom:16px">
      <div style="font-size:16px;font-weight:600">${
        a ? escHtml(a.title) : t('The last 90 days')}</div>
      ${a ? `<div style="font-size:13px;color:var(--gray-400);margin-top:2px">${
        escHtml(a.date)}${a.time ? ' · ' + escHtml(a.time) : ''}${
        a.location ? ' · ' + escHtml(a.location) : ''}${
        p.provider ? ' · ' + escHtml(p.provider.name) : ''}</div>` : ''}
      <div style="font-size:13px;color:var(--gray-400);margin-top:6px">${
        escHtml(_vpWindowLine(p.window))}</div>
    </div>`;

  // Allergies lead. On a page a clinician may only skim, the section where an
  // omission is dangerous rather than untidy goes first.
  const allergies = _vpSection(t('Allergies'),
    p.allergies.length ? `<ul class="vp-list">${p.allergies.map(x =>
      `<li><b>${escHtml(x.allergen)}</b>${x.reaction ? ' — ' + escHtml(x.reaction) : ''}${
        x.severity ? ` <span class="vp-dim">(${escHtml(x.severity)})</span>` : ''}</li>`).join('')}</ul>` : '',
    t('No allergies recorded in Arogo. That is not the same as none — check before assuming.'));

  const meds = _vpSection(tformat('Medicines (%1)', p.medicines.length),
    p.medicines.length ? `<ul class="vp-list">${p.medicines.map(m =>
      `<li><b>${escHtml(m.name)}</b>${m.dose ? ' ' + escHtml(m.dose) : ''}${
        m.frequency ? ` <span class="vp-dim">${escHtml(m.frequency)}</span>` : ''}${
        m.times.length ? ` <span class="vp-dim">${escHtml(m.times.join(', '))}</span>` : ''}${
        m.with_food ? ` <span class="vp-dim">${t('with food')}</span>` : ''}${
        // The whole phrase, not t('for') + the value: Hindi puts the
        // postposition AFTER the noun, so a bare "for" prefix produced
        // "किसलिए cholesterol" — the interrogative "what for?" followed by a
        // word. Word order has to live inside the translatable string.
        m.purpose ? `<br><span class="vp-dim">${tformat('for %1', escHtml(m.purpose))}</span>` : ''}</li>`).join('')}</ul>` : '',
    t('No medicines are marked active in Arogo.'));

  const ch = p.changes.changes;
  const changes = _vpSection(t('What changed'),
    ch.length ? `<ul class="vp-list">${ch.map(c =>
      `<li>${escHtml(c.date)} — <b>${escHtml(c.name)}</b>: ${escHtml(c.label)}${
        c.detail ? ' <span class="vp-dim">' + escHtml(c.detail) + '</span>' : ''}</li>`).join('')}</ul>
      <div class="restore-note">${escHtml(p.changes.not_captured)}</div>` : '',
    t('No medicine changes are recorded in this period.'));

  const conditions = p.conditions
    ? _vpSection(t('Conditions'), `<div style="font-size:13.5px;line-height:1.7">${
        escHtml(p.conditions)}</div>`, '')
    : '';

  const labs = _vpSection(t('Lab results'),
    p.labs.items.length ? `<table class="vp-table"><thead><tr>
        <th>${t('Date')}</th><th>${t('Test')}</th><th>${t('Result')}</th></tr></thead>
      <tbody>${p.labs.items.map(l => `<tr><td>${escHtml(l.date)}</td>
        <td>${escHtml(l.name)}</td>
        <td>${escHtml(String(l.value))}${l.unit ? ' ' + escHtml(l.unit) : ''}</td></tr>`).join('')}
      </tbody></table>${p.labs.truncated
        ? `<div class="restore-note">${tformat('Showing the newest %1 of %2.',
            p.labs.items.length, p.labs.total)}</div>` : ''}` : '',
    t('No lab results recorded in this period.'));

  const sym = _vpSection(t('Symptoms'),
    p.symptoms.items.length ? `<ul class="vp-list">${p.symptoms.items.map(s =>
      `<li><b>${escHtml(s.name)}</b> — ${tformat('%1 times', s.count)}, ${
        s.first === s.last ? escHtml(s.first) : tformat('%1 to %2', s.first, s.last)}${
        s.worst !== null && s.worst !== undefined
          ? ', ' + tformat('worst %1/10', s.worst) : ''}${
        s.notes.length ? `<br><span class="vp-dim">${escHtml(s.notes.join(' · '))}</span>` : ''}</li>`).join('')}</ul>
      <div class="restore-note">${t(
        'Severity is what the person logging it chose at the time, on a 1–10 scale of their own. It is not a measurement.')}</div>` : '',
    t('No symptoms logged in this period.'));

  const vitals = _vpSection(t('Recent readings'),
    p.vitals.length ? `<ul class="vp-list">${p.vitals.map(v =>
      `<li><b>${escHtml(_vpVitalLabel(v.type))}</b> — ${
        v.readings.map(rd => `${escHtml(_vpVitalText(v.type, rd))} <span class="vp-dim">${
          escHtml(rd.date)}</span>`).join(' · ')}</li>`).join('')}</ul>` : '',
    t('No readings logged in this period.'));

  const qs = p.questions.for_this_visit.concat(p.questions.unassigned);
  const questions = _vpSection(t('Questions to ask'),
    qs.length ? `<ul class="vp-list vp-checklist">${qs.map(q =>
      `<li>☐ ${escHtml(q.question)}</li>`).join('')}</ul>` : '',
    t('No questions written down yet. Anything you add on the Upcoming page appears here.'));

  return head + allergies + meds + changes + conditions + labs + sym + vitals + questions
    + `<div class="panel" style="padding:16px 20px">
        <div class="restore-note" style="margin:0">${escHtml(p.not_captured)}</div>
        <div class="restore-note">${t(
          'Your uploaded documents are not listed here — print the index from Medical records if the doctor needs those too.')}</div>
      </div>`;
}

// Plain names, deliberately not the app's own label maps: those carry emoji for
// the dashboard, and an emoji on a page a clinician reads is noise. An unknown
// type falls back to its own key rather than being dropped.
const _VP_VITAL_LABEL = {
  blood_pressure: 'Blood pressure', blood_sugar: 'Blood sugar',
  heart_rate: 'Heart rate', weight: 'Weight', spo2: 'Oxygen saturation',
  temperature: 'Temperature',
};

function _vpVitalLabel(type) {
  const known = _VP_VITAL_LABEL[type];
  if (known) return t(known);
  return String(type || '').replace(/_/g, ' ');
}

// Readings are stored canonically and converted at the display layer, so this
// goes through the same converter every other screen uses rather than printing
// the raw stored number with a label that might not match it.
function _vpVitalText(type, rd) {
  try {
    const v1 = vitalToDisplay(type, rd.value1);
    const unit = vitalUnitLabel(type) || rd.unit || '';
    if (rd.value2 !== null && rd.value2 !== undefined)
      return `${v1}/${vitalToDisplay(type, rd.value2)} ${unit}`.trim();
    return `${v1} ${unit}`.trim();
  } catch (e) {
    return `${rd.value1}${rd.value2 !== null && rd.value2 !== undefined ? '/' + rd.value2 : ''} ${rd.unit || ''}`.trim();
  }
}

function printVisitPackPage() {
  if (!_visitPack) { showToast(t('Nothing to print yet'), 'info'); return; }
  const w = window.open('', '_blank');
  if (!w) { showToast(t('Allow pop-ups to print'), 'error'); return; }
  const who = (_currentUser?.name || _currentUser?.email || '');
  const a = _visitPack.appointment;
  w.document.write(`<!doctype html><html><head><meta charset="utf-8">
    <title>${escHtml(t('Appointment pack'))}</title><style>
      body{font-family:-apple-system,Segoe UI,Roboto,sans-serif;color:#222;margin:28px;font-size:12.5px;line-height:1.55}
      h1{font-size:18px;margin:0 0 2px} h2{font-size:13px;margin:16px 0 6px;
        text-transform:uppercase;letter-spacing:.04em;color:#444;border-bottom:1px solid #ddd;padding-bottom:3px}
      .sub{color:#666;font-size:11.5px;margin-bottom:4px}
      ul{margin:0;padding-left:18px} li{margin-bottom:3px}
      table{border-collapse:collapse;width:100%;margin-top:4px}
      th,td{border:1px solid #ddd;padding:4px 7px;text-align:left}
      th{background:#f2f2f2;font-size:10.5px;text-transform:uppercase}
      .vp-dim{color:#666} .restore-note{color:#777;font-size:11px;margin-top:5px}
      .panel{page-break-inside:avoid} .panel-title{font-size:13px;margin:16px 0 6px;
        text-transform:uppercase;letter-spacing:.04em;color:#444;border-bottom:1px solid #ddd;padding-bottom:3px}
      @page{margin:14mm}
    </style></head><body>
    <h1>${escHtml(t('Appointment pack'))}</h1>
    <div class="sub">${escHtml(who)}${a ? ' · ' + escHtml(a.title) + ' · ' + escHtml(a.date) : ''}</div>
    <div class="sub">${escHtml(t('Printed'))} ${new Date().toLocaleDateString()}</div>
    ${renderVisitPack(_visitPack)}
    </body></html>`);
  w.document.close(); w.focus(); setTimeout(() => w.print(), 400);
}

// ── Screen lock ─────────────────────────────────────────────────────────────
//
// The lock itself lives on the server: a locked session gets 423 from every
// endpoint bar a short allow-list, so this code cannot be the security. What it
// is responsible for is (a) noticing idleness precisely, which only the page can
// do, and (b) showing the lock screen the moment anything comes back 423 —
// including a request the user never made, like a background refresh.
//
// That second part matters. If the client only ever locked on its own timer, a
// tab restored from the background, a second tab, or a device whose timer never
// ran would sit showing a full medical history that the server would refuse to
// refresh. Watching for 423 means the UI can never be more open than the server.

let _lockState = null;
let _idleTimer = null;
let _lockShown = false;

async function loadLock() {
  const el = document.getElementById('lock-panel');
  const r = await fetch('/api/lock', {credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!r) { if (el) el.innerHTML = `<div class="restore-row">${t('Could not check the screen lock')}</div>`; return; }
  _lockState = r;
  if (r.locked) { showLockScreen(); return; }
  _armIdleTimer();
  if (el) { el.innerHTML = _lockPanelHtml(r); _a11yEnhance(el); }
}

function _lockPanelHtml(r) {
  if (!r.has_pin) {
    return `<div class="restore-note" style="margin-bottom:12px">${t(
      'The screen lock is off. Anyone who picks up this device and opens Arogo sees everything in it.')}</div>
      <button class="btn-primary" data-ev-click="openLockSetup()">${t('Set a PIN')}</button>`;
  }
  const choices = (r.idle_choices || []).map(m =>
    `<option value="${m}"${m === r.idle_minutes ? ' selected' : ''}>${
      m === 0 ? t('Never') : tformat('After %1 minutes', m)}</option>`).join('');
  return `<div class="restore-row"><span>${t('Screen lock')}</span><b>${t('On')}</b></div>
    <div style="margin-top:12px">
      <label class="form-label" for="lock-idle">${t('Lock when idle')}</label>
      <select class="form-input" id="lock-idle" style="max-width:240px"
              data-ev-change="saveLockIdle(this.value)">${choices}</select>
    </div>
    <label style="display:flex;gap:9px;align-items:flex-start;font-size:13.5px;margin-top:14px">
      <input type="checkbox" id="lock-emerg"${r.emergency_while_locked ? ' checked' : ''}
             data-ev-change="saveLockEmergency(this.checked)">
      <span>${t('Show my emergency card on the lock screen')}<br>
        <span style="color:var(--gray-400)">${t(
          'Your allergies, conditions and emergency contacts, readable without the PIN. That is what an emergency card is for — but it does mean anyone holding this device can read it.')}</span></span>
    </label>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:14px">
      <button class="btn-outline" data-ev-click="lockNow()">${t('Lock now')}</button>
      <button class="btn-outline" data-ev-click="openLockSetup()">${t('Change PIN')}</button>
      <button class="btn-outline" data-ev-click="openLockRemove()">${t('Turn off')}</button>
    </div>
    <div id="lock-setup"></div>`;
}

function openLockSetup() {
  const box = document.getElementById('lock-setup') || document.getElementById('lock-panel');
  if (!box) return;
  const html = `<div style="margin-top:14px;padding-top:14px;border-top:1px solid var(--gray-100)">
      <div>
        <label class="form-label" for="lock-new-pin">${t('New PIN (4–8 digits)')}</label>
        <input class="form-input" id="lock-new-pin" type="password" inputmode="numeric"
               maxlength="8" style="max-width:180px" autocomplete="off">
      </div>
      <div style="margin-top:10px">
        <label class="form-label" for="lock-pw">${t('Your account password')}</label>
        <input class="form-input" id="lock-pw" type="password" style="max-width:260px"
               autocomplete="current-password">
      </div>
      <div class="restore-note">${t(
        'Your password is asked for so that someone holding this device unlocked cannot set a PIN of their own and lock you out.')}</div>
      <div class="form-actions" style="margin-top:12px">
        <button class="btn-primary" data-ev-click="saveLockPin()">${t('Save')}</button>
        <button class="btn-outline" data-ev-click="loadLock()">${t('Cancel')}</button>
      </div>
    </div>`;
  if (box.id === 'lock-setup') box.innerHTML = html; else box.innerHTML += html;
  _a11yEnhance(box);
  document.getElementById('lock-new-pin')?.focus();
}

async function saveLockPin() {
  const pin = document.getElementById('lock-new-pin')?.value || '';
  const password = document.getElementById('lock-pw')?.value || '';
  const r = await fetch('/api/lock/pin', {
    method: 'POST', credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({pin, password}),
  }).then(r => r.json()).catch(() => null);
  if (!r || !r.success) { showToast((r && r.error) || t('Could not set the PIN'), 'error'); return; }
  showToast(t('✓ Screen lock is on'), 'success');
  loadLock();
}

function openLockRemove() {
  const box = document.getElementById('lock-setup');
  if (!box) return;
  box.innerHTML = `<div style="margin-top:14px;padding-top:14px;border-top:1px solid var(--gray-100)">
      <p style="font-size:13.5px;margin:0 0 8px">${t(
        'Turning the screen lock off needs your password.')}</p>
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">
        <input class="form-input" type="password" id="lock-off-pw" style="max-width:240px"
               autocomplete="current-password" aria-label="${t('Password')}">
        <button class="btn-primary" data-ev-click="removeLockPin()">${t('Turn off')}</button>
        <button class="btn-outline" data-ev-click="loadLock()">${t('Cancel')}</button>
      </div></div>`;
  _a11yEnhance(box);
  document.getElementById('lock-off-pw')?.focus();
}

async function removeLockPin() {
  const password = document.getElementById('lock-off-pw')?.value || '';
  const r = await fetch('/api/lock/pin', {
    method: 'DELETE', credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({password}),
  }).then(r => r.json()).catch(() => null);
  if (!r || !r.success) { showToast((r && r.error) || t('That did not work'), 'error'); return; }
  showToast(t('Screen lock is off'), 'success');
  loadLock();
}

async function saveLockIdle(minutes) {
  await fetch('/api/lock/settings', {
    method: 'POST', credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({idle_minutes: minutes}),
  }).catch(() => {});
  if (_lockState) _lockState.idle_minutes = Number(minutes);
  _armIdleTimer();
  showToast(t('✓ Saved'), 'success');
}

async function saveLockEmergency(on) {
  await fetch('/api/lock/settings', {
    method: 'POST', credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({emergency_while_locked: on ? 1 : 0}),
  }).catch(() => {});
  if (_lockState) _lockState.emergency_while_locked = !!on;
  showToast(t('✓ Saved'), 'success');
}

async function lockNow() {
  const r = await fetch('/api/lock/now', {method: 'POST', credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!r || !r.success) { showToast((r && r.error) || t('Could not lock'), 'error'); return; }
  showLockScreen();
}

// ── Idle ──
// The page can see real activity; the server only sees requests. So the timer
// lives here, and the server independently refuses anything from a session that
// has not been seen for longer than the same window. Neither alone is enough:
// a closed tab never fires its timer, and a server that only counted requests
// would think a user reading one screen for ten minutes had gone away.
function _armIdleTimer() {
  clearTimeout(_idleTimer);
  const mins = _lockState && _lockState.has_pin ? _lockState.idle_minutes : 0;
  if (!mins) return;
  _idleTimer = setTimeout(() => {
    fetch('/api/lock/now', {method: 'POST', credentials: 'same-origin'})
      .then(() => showLockScreen()).catch(() => showLockScreen());
  }, mins * 60 * 1000);
}

['click', 'keydown', 'touchstart', 'scroll'].forEach(ev =>
  document.addEventListener(ev, () => { if (!_lockShown) _armIdleTimer(); },
                            {passive: true, capture: true}));

function showLockScreen() {
  const el = document.getElementById('lock-screen');
  if (!el) return;
  _lockShown = true;
  clearTimeout(_idleTimer);
  el.style.display = 'flex';
  const err = document.getElementById('lock-error');
  if (err) err.textContent = '';
  const emg = document.getElementById('lock-emergency');
  if (emg) emg.innerHTML = '';
  const btn = document.getElementById('lock-emergency-btn');
  if (btn) btn.style.display = (_lockState && _lockState.emergency_while_locked !== false)
    ? '' : 'none';
  const pin = document.getElementById('lock-pin');
  if (pin) { pin.value = ''; pin.type = 'password'; setTimeout(() => pin.focus(), 80); }
}

function hideLockScreen() {
  const el = document.getElementById('lock-screen');
  if (el) el.style.display = 'none';
  const pin = document.getElementById('lock-pin');
  if (pin) pin.value = '';           // never leave it sitting in the DOM
  _lockShown = false;
  _armIdleTimer();
}

let _unlockWithPassword = false;

function showUnlockPassword() {
  _unlockWithPassword = true;
  const pin = document.getElementById('lock-pin');
  if (pin) { pin.value = ''; pin.maxLength = 200; pin.setAttribute('inputmode', 'text');
             pin.setAttribute('aria-label', t('Password')); pin.focus(); }
  const sub = document.querySelector('#lock-screen .lock-sub');
  if (sub) sub.textContent = t('Enter your account password.');
}

async function submitUnlock() {
  const val = document.getElementById('lock-pin')?.value || '';
  const err = document.getElementById('lock-error');
  if (!val) { if (err) err.textContent = t('Enter your PIN'); return; }
  const body = _unlockWithPassword ? {password: val} : {pin: val};
  const r = await fetch('/api/lock/unlock', {
    method: 'POST', credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'}, body: JSON.stringify(body),
  }).then(r => r.json()).catch(() => null);
  if (!r || !r.success) {
    // Say how many tries are left. Silently counting down to a lockout is how
    // someone ends up locked out of their own medicines without warning.
    if (err) err.textContent = (r && r.tries_left !== undefined)
      ? tformat('%1 — %2 tries left', (r.error || t('That PIN is not right')), r.tries_left)
      : ((r && r.error) || t('That did not work'));
    const pin = document.getElementById('lock-pin');
    if (pin) { pin.value = ''; pin.focus(); }
    return;
  }
  _unlockWithPassword = false;
  hideLockScreen();
  // The screens behind the lock were rendered before it, and anything they
  // tried to refresh while locked came back 423.
  try { switchView(_activeViewName() || 'dashboard'); } catch (e) {}
  loadLock();
}

async function showLockEmergency() {
  const box = document.getElementById('lock-emergency');
  if (!box) return;
  box.innerHTML = `<div class="restore-note">${t('Loading…')}</div>`;
  const d = await fetch('/api/health-id', {credentials: 'same-origin'})
    .then(r => r.ok ? r.json() : null).catch(() => null);
  if (!d) {
    box.innerHTML = `<div class="restore-note">${t(
      'The emergency card is not available on this locked device.')}</div>`;
    return;
  }
  const line = (label, value) => value
    ? `<div class="restore-row"><span>${escHtml(label)}</span><b>${escHtml(value)}</b></div>` : '';
  const meds = (d.active_medicines || []).map(m => m.name).filter(Boolean);
  box.innerHTML = `
    ${line(t('Name'), (d.identity || {}).name)}
    ${line(t('Blood type'), d.blood_type)}
    ${line(t('Allergies'), d.allergies || (d.allergy_list || []).map(a => a.allergen).join(', '))}
    ${line(t('Conditions'), d.conditions)}
    ${meds.length ? `<div class="restore-row"><span>${t('Medicines')}</span>
       <b>${escHtml(meds.join(', '))}</b></div>` : ''}
    ${(d.contacts || []).map(c => line(c.name || t('Emergency contact'), c.phone)).join('')}
    <div class="restore-note">${t('Shown without unlocking, because that is what an emergency card is for.')}</div>`;
  _a11yEnhance(box);
}

// Anything coming back 423 means the server considers this device locked, even
// if this tab never noticed. The UI must never be more open than the server.
//
// Wrapped once around fetch rather than added to each of the several hundred
// call sites — partly because that is the only version that stays true, and
// partly because the cases that matter are the requests nobody wrote by hand: a
// background refresh, a second tab, a page restored from the phone's app
// switcher hours later.
let _lockFetchWrapped = false;

function _watchForLockedResponses() {
  if (_lockFetchWrapped || typeof fetch !== 'function') return;
  const inner = fetch;
  // A pass-through: the response object is returned untouched, so every caller
  // behaves exactly as before. Only the side effect is new.
  window.fetch = function (...args) {
    return inner.apply(this, args).then(res => {
      try {
        if (res && res.status === 423 && !_lockShown) _onLockedResponse();
      } catch (e) {}
      return res;
    });
  };
  _lockFetchWrapped = true;
}

function _onLockedResponse() {
  _lockShown = true;                 // stop a burst of 423s stacking up
  fetch('/api/lock', {credentials: 'same-origin'}).then(r => r.json())
    .then(s => { _lockState = s; _lockShown = false; showLockScreen(); })
    .catch(() => { _lockShown = false; showLockScreen(); });
}

// ── Two-factor sign-in ──────────────────────────────────────────────────────
// The API for this shipped complete and tested, and then sat unreachable: there
// was no screen, so nobody could turn it on. Everything here is that screen.
//
// The flow is deliberately slow in two places. Enrolment is not finished until a
// code from the authenticator actually verifies, because the failure everyone
// hits is a phone with a wrong clock — better to find that out now than at the
// next sign-in. And the recovery codes must be acknowledged before the panel
// moves on, because they are shown exactly once and a lost phone is an ordinary
// event, not an edge case.

let _2faSetup = null;      // the in-progress enrolment, never persisted

async function load2fa() {
  const el = document.getElementById('twofa-panel');
  if (!el) return;
  const r = await fetch('/api/2fa', {credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!r) { el.innerHTML = `<div class="restore-row">${t('Could not check your two-factor settings')}</div>`; return; }
  el.innerHTML = r.enabled ? _2faOnHtml(r) : _2faOffHtml();
  _a11yEnhance(el);
}

function _2faOffHtml() {
  return `<div class="restore-note" style="margin-bottom:12px">${t(
    'Two-factor sign-in is off. Your password alone opens the account.')}</div>
    <button class="btn-primary" data-ev-click="start2fa()">${t('Turn on two-factor sign-in')}</button>`;
}

function _2faOnHtml(r) {
  // The count matters more than the fact. Someone down to their last code needs
  // to act, and "on" alone would never tell them.
  const left = r.recovery_codes_left;
  const low = left <= 2;
  return `<div class="restore-row"><span><b>${t('On')}</b> · ${
      low ? `<span style="color:var(--danger,#b3261e)">${tformat('%1 recovery codes left', left)}</span>`
          : tformat('%1 recovery codes left', left)}</span></div>
    ${low ? `<div class="restore-note">${t(
      'Recovery codes are how you get in if you lose your phone. Make a new set while you still can.')}</div>` : ''}
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px">
      <button class="btn-outline" data-ev-click="ask2faPassword('recovery')">${t('New recovery codes')}</button>
      <button class="btn-outline" data-ev-click="ask2faPassword('disable')">${t('Turn off')}</button>
    </div>
    <div id="twofa-confirm"></div>`;
}

async function start2fa() {
  const el = document.getElementById('twofa-panel');
  const r = await fetch('/api/2fa/setup', {method: 'POST', credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!r || !r.success) { showToast((r && r.error) || t('Could not start setup'), 'error'); return; }
  _2faSetup = r;
  const qr = r.qr && r.qr.available
    ? `<div style="max-width:190px;margin:0 0 12px">${r.qr.svg}</div>`
    // No QR library on this server. Typing the key in by hand is the documented
    // fallback in every authenticator app, so say that plainly rather than
    // leaving a blank space where a code should be.
    : `<div class="restore-note" style="margin-bottom:12px">${t(
        'Add it by hand in your authenticator app using the key below.')}</div>`;
  el.innerHTML = `
    <ol style="font-size:13.5px;line-height:1.9;padding-left:20px;margin:0 0 14px">
      <li>${t('Open an authenticator app — Google Authenticator, Aegis, 1Password and others all work.')}</li>
      <li>${t('Scan this code, or enter the key by hand.')}</li>
      <li>${t('Type the 6-digit code it shows, to prove it works.')}</li>
    </ol>
    ${qr}
    <div style="font-size:12px;color:var(--gray-400);margin-bottom:4px">${t('Setup key')}</div>
    <div style="font-family:'JetBrains Mono',monospace;font-size:14px;letter-spacing:.08em;
                word-break:break-all;margin-bottom:14px">${escHtml(r.secret)}</div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">
      <input class="form-input" id="twofa-code" inputmode="numeric" autocomplete="one-time-code"
             maxlength="6" style="max-width:130px" placeholder="000000"
             aria-label="${t('6-digit code from your authenticator app')}">
      <button class="btn-primary" data-ev-click="confirm2fa()">${t('Turn it on')}</button>
      <button class="btn-outline" data-ev-click="load2fa()">${t('Cancel')}</button>
    </div>
    <div class="restore-note" style="margin-top:12px">${t(
      'Nothing changes about how you sign in until this code checks out.')}</div>`;
  _a11yEnhance(el);
  document.getElementById('twofa-code')?.focus();
}

async function confirm2fa() {
  const code = (document.getElementById('twofa-code')?.value || '').trim();
  if (!code) { showToast(t('Enter the 6-digit code'), 'info'); return; }
  const r = await fetch('/api/2fa/confirm', {
    method: 'POST', credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'}, body: JSON.stringify({code}),
  }).then(r => r.json()).catch(() => null);
  if (!r || !r.success) {
    showToast((r && r.error) || t('That code did not match'), 'error');
    return;
  }
  _2faSetup = null;
  _show2faRecoveryCodes(r.recovery_codes, t('Two-factor sign-in is on.'));
}

// Shown once, on enrolment and on regeneration. The acknowledge step is the
// point: a user who clicks past this screen has no second way in.
function _show2faRecoveryCodes(codes, headline) {
  const el = document.getElementById('twofa-panel');
  if (!el) return;
  el.innerHTML = `
    <div class="restore-row" style="margin-bottom:10px"><b>${escHtml(headline)}</b></div>
    <p style="font-size:13.5px;line-height:1.7;margin:0 0 12px">${t(
      'Save these recovery codes somewhere other than your phone. Each one signs you in once if you lose the phone, and this is the only time they are shown.')}</p>
    <div id="twofa-codes" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));
                gap:8px;font-family:'JetBrains Mono',monospace;font-size:14px;margin-bottom:14px">
      ${codes.map(c => `<div>${escHtml(c)}</div>`).join('')}</div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px">
      <button class="btn-outline" data-ev-click="copy2faCodes()">${t('Copy')}</button>
      <button class="btn-outline" data-ev-click="print2faCodes()">${t('Print')}</button>
    </div>
    <label style="display:flex;gap:8px;align-items:flex-start;font-size:13.5px;margin-bottom:12px">
      <input type="checkbox" id="twofa-ack" data-ev-change="_2faAckToggle(this.checked)">
      <span>${t('I have saved these codes')}</span></label>
    <button class="btn-primary" id="twofa-done" disabled
            data-ev-click="load2fa()">${t('Done')}</button>`;
  _a11yEnhance(el);
}

function _2faAckToggle(on) {
  const b = document.getElementById('twofa-done');
  if (b) b.disabled = !on;
}

function _2faCodeText() {
  return Array.from(document.querySelectorAll('#twofa-codes div'))
    .map(d => d.textContent.trim()).join('\n');
}

async function copy2faCodes() {
  try {
    await navigator.clipboard.writeText(_2faCodeText());
    showToast(t('✓ Copied'), 'success');
  } catch (e) { showToast(t('Could not copy — select the codes and copy them by hand'), 'warn'); }
}

function print2faCodes() {
  const w = window.open('', '_blank');
  if (!w) { showToast(t('Allow pop-ups to print'), 'error'); return; }
  // The account is named but never the password or the setup key — a printout
  // that walks off a desk should not be enough on its own.
  w.document.write(`<!doctype html><html><head><meta charset="utf-8">
    <title>Arogo recovery codes</title>
    <style>body{font-family:-apple-system,Segoe UI,Roboto,sans-serif;margin:40px}
      h1{font-size:18px} li{font-family:monospace;font-size:15px;line-height:2}
      p{font-size:12px;color:#666;max-width:38em}</style></head><body>
    <h1>Arogo — recovery codes</h1>
    <p>${escHtml(_currentUser?.email || '')}</p>
    <ol>${_2faCodeText().split('\n').map(c => `<li>${escHtml(c)}</li>`).join('')}</ol>
    <p>Each code signs you in once if you cannot reach your authenticator app.
       Keep this somewhere safe and away from your phone.</p>
    </body></html>`);
  w.document.close(); w.focus(); setTimeout(() => w.print(), 300);
}

// Both destructive-ish actions need the password. An inline field rather than a
// browser prompt() — prompts can't be styled, translated or read properly by a
// screen reader, and this app renders its own confirmations everywhere else.
function ask2faPassword(action) {
  const box = document.getElementById('twofa-confirm');
  if (!box) return;
  const label = action === 'disable'
    ? t('Turning off two-factor sign-in needs your password.')
    : t('Making new recovery codes needs your password. The old ones stop working.');
  box.innerHTML = `<div style="margin-top:14px;padding-top:14px;border-top:1px solid var(--gray-100)">
      <p style="font-size:13.5px;margin:0 0 8px">${escHtml(label)}</p>
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">
        <input class="form-input" type="password" id="twofa-pw" style="max-width:220px"
               autocomplete="current-password" aria-label="${t('Password')}">
        <button class="btn-primary" data-ev-click="submit2faPassword('${escHtml(action)}')">${t('Confirm')}</button>
        <button class="btn-outline" data-ev-click="load2fa()">${t('Cancel')}</button>
      </div></div>`;
  _a11yEnhance(box);
  document.getElementById('twofa-pw')?.focus();
}

async function submit2faPassword(action) {
  const pw = document.getElementById('twofa-pw')?.value || '';
  if (!pw) { showToast(t('Enter your password'), 'info'); return; }
  const url = action === 'disable' ? '/api/2fa/disable' : '/api/2fa/recovery-codes';
  const r = await fetch(url, {
    method: 'POST', credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'}, body: JSON.stringify({password: pw}),
  }).then(r => r.json()).catch(() => null);
  if (!r || !r.success) { showToast((r && r.error) || t('That did not work'), 'error'); return; }
  if (action === 'disable') {
    showToast(t('Two-factor sign-in is off'), 'success');
    load2fa();
  } else {
    _show2faRecoveryCodes(r.recovery_codes, t('New recovery codes.'));
  }
}

async function loadAccountActivity() {
  loadLock();
  load2fa();
  const [sess, shares, log] = await Promise.all([
    fetch('/api/account/sessions', {credentials: 'same-origin'}).then(r => r.json()).catch(() => null),
    fetch('/api/account/shares', {credentials: 'same-origin'}).then(r => r.json()).catch(() => null),
    fetch('/api/account/activity', {credentials: 'same-origin'}).then(r => r.json()).catch(() => null),
  ]);

  const sEl = document.getElementById('session-list');
  if (sEl && sess) {
    sEl.innerHTML = `<div class="restore-list">${sess.sessions.map(s => `
      <div class="restore-row">
        <span><b>${escHtml(s.device)}</b>${s.current ? ' · ' + t('this device') : ''}<br>
          <span class="restore-removes">${tformat('last used %1', escHtml(_agoText(s.last_seen)))}</span></span>
        ${s.current ? '' : `<button class="btn-outline" style="font-size:12px"
           data-ev-click="revokeSession('${escHtml(s.id)}')">${t('Sign out')}</button>`}
      </div>`).join('')}</div>`;
  }

  const rEl = document.getElementById('share-receipts');
  if (rEl && shares) {
    rEl.innerHTML = shares.shares.length
      ? `<div class="restore-list">${shares.shares.map(s => `
          <div class="restore-row">
            <span><b>${escHtml(s.label)}</b><br>
              <span class="restore-removes">${escHtml(String(s.scope || ''))} · ${
                t('created')} ${escHtml(_agoText(s.created_at))}${
                s.revoked ? ' · ' + t('revoked') : ''}</span></span>
            <span>${s.views ? tformat('%1 opens', s.views) : t('not opened yet')}</span>
          </div>`).join('')}</div>`
      : `<div class="restore-note">${t('No share links yet.')}</div>`;
  }

  const lEl = document.getElementById('activity-log');
  if (lEl && log) {
    lEl.innerHTML = log.events.length
      ? `<div class="restore-list">${log.events.map(e => `
          <div class="restore-row">
            <span>${escHtml(e.label)}${e.detail ? ' · <span class="restore-removes">' +
              escHtml(e.detail) + '</span>' : ''}</span>
            <span class="restore-removes">${escHtml(_agoText(e.at))}</span>
          </div>`).join('')}</div>`
      : `<div class="restore-note">${t('Nothing recorded yet.')}</div>`;
  }
}

function revokeSession(id) {
  undoable(t('Signing that device out'), async () => {
    await fetch('/api/account/sessions/' + encodeURIComponent(id),
                {method: 'DELETE', credentials: 'same-origin'}).catch(() => {});
    loadAccountActivity();
  });
}

function revokeAllSessions() {
  // Names what survives, because "sign out everywhere" reads as including you.
  undoable(t('Signing out every other device — this one stays signed in'), async () => {
    const r = await fetch('/api/account/sessions/revoke-all',
      {method: 'POST', credentials: 'same-origin'}).then(r => r.json()).catch(() => null);
    if (r && r.success) showToast(tformat('Signed out %1 devices', r.signed_out), 'success');
    loadAccountActivity();
  });
}

// ── Trips & time zones ─────────────────────────────────────────────────────
// A dose is a wall-clock time, and "now" comes from one place. A trip changes
// that place, so reminders and the day follow the user — and the app says so
// rather than silently retiming anything.
async function loadTrips() {
  const list = document.getElementById('trip-list');
  if (!list) return;
  const r = await fetch('/api/trips', {credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!r) return;

  const dl = document.getElementById('trip-tz-list');
  if (dl && !dl.childElementCount) {
    dl.innerHTML = (r.timezones || []).map(z => `<option value="${escHtml(z)}">`).join('');
  }
  list.innerHTML = r.trips.length
    ? `<div class="restore-list">${r.trips.map(tr => {
        const when = tr.active ? t('on now') : tr.upcoming ? t('upcoming') : t('past');
        return `<div class="restore-row">
          <span><b>${escHtml(tr.label || tr.timezone)}</b><br>
            <span class="restore-removes">${escHtml(tr.timezone)} · ${escHtml(tr.start_date)} → ${escHtml(tr.end_date)} · ${escHtml(when)}</span></span>
          <button class="btn-outline" style="font-size:12px"
                  data-ev-click="deleteTrip('${escHtml(tr.id)}')">${t('Remove')}</button>
        </div>`;
      }).join('')}</div>`
    : `<div class="restore-note">${t('No trips yet.')}</div>`;
  loadTripClock();
}

async function loadTripClock() {
  const el = document.getElementById('trip-clock');
  if (!el) return;
  const c = await fetch('/api/trips/clock', {credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!c || !c.has_trip) { el.innerHTML = ''; return; }
  const hrs = (c.shift_minutes / 60);
  const dir = c.shift_minutes === 0 ? t('the same time as home')
            : tformat('%1 hours %2 home', Math.abs(hrs).toFixed(hrs % 1 ? 1 : 0),
                      c.shift_minutes > 0 ? t('ahead of') : t('behind'));
  // Both columns, no recommendation. Which one to follow is a question for
  // whoever prescribed the medicine — for insulin or an anticoagulant it is a
  // consequential one, and the app has no business answering it.
  const rows = (c.doses || []).map(d => `
    <div class="restore-row"><span>${escHtml(d.medicine)}</span>
      <span>${escHtml(d.home_time)} ${t('at home')} <b>→ ${escHtml(d.same_moment_local)}${
        d.day_shift ? ' (' + (d.day_shift > 0 ? '+1d' : '−1d') + ')' : ''}</b></span></div>`).join('');
  el.innerHTML = `
    <div class="restore-warn" style="background:var(--teal-50,#EAF6F2);border-color:#CBE5DC;color:#2f5d4e">
      ✈️ ${tformat('While you are in %1, Arogo is on %2 — %3. Until %4.',
                    escHtml(c.label || c.trip_timezone), escHtml(c.trip_timezone),
                    dir, escHtml(c.ends_on))}
    </div>
    ${rows ? `<div class="restore-list">${rows}</div>
      <div class="restore-note">${t('These are the same moments shown in both clocks. Whether to move a dose to local time is a question for whoever prescribed it — Arogo does not decide that for you.')}</div>` : ''}`;
}

async function saveTrip() {
  const body = {
    label: document.getElementById('trip-label')?.value || '',
    timezone: document.getElementById('trip-tz')?.value || '',
    start_date: document.getElementById('trip-tz-start')?.value || '',
    end_date: document.getElementById('trip-tz-end')?.value || '',
  };
  const r = await fetch('/api/trips', {method: 'POST', credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'}, body: JSON.stringify(body)})
    .then(r => r.json()).catch(() => null);
  if (r && r.success) {
    ['trip-label', 'trip-tz'].forEach(id => { const e = document.getElementById(id); if (e) e.value = ''; });
    showToast(t('✓ Trip added'), 'success');
    loadTrips();
  } else {
    showToast((r && r.error) || t('Could not add that trip'), 'error');
  }
}

function deleteTrip(id) {
  undoable(t('Removing this trip'), async () => {
    await fetch('/api/trips/' + encodeURIComponent(id),
                {method: 'DELETE', credentials: 'same-origin'}).catch(() => {});
    loadTrips();
  });
}

// ── Illness episodes ───────────────────────────────────────────────────────
async function loadEpisodes() {
  const el = document.getElementById('episode-list');
  if (!el) return;
  const r = await fetch('/api/episodes', {credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!r) return;
  if (!r.episodes.length) {
    el.innerHTML = `<div class="panel" style="padding:18px 20px"><div class="restore-note">${
      t('No episodes yet. Start one when you come down with something — you can end it when you feel better.')}</div></div>`;
    return;
  }
  el.innerHTML = r.episodes.map(e => `
    <div class="panel" style="padding:16px 20px;margin-bottom:12px">
      <div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;align-items:flex-start">
        <div><b>${escHtml(e.name)}</b><br>
          <span class="restore-removes">${escHtml(e.started_on)}${
            e.ended_on ? ' → ' + escHtml(e.ended_on) : ' · ' + t('ongoing')
          }${e.days ? ' · ' + tformat('%1 days', e.days) : ''}</span></div>
        <div style="display:flex;gap:6px;flex-wrap:wrap">
          ${e.ongoing ? `<button class="btn-outline" style="font-size:12px"
             data-ev-click="endEpisode('${escHtml(e.id)}')">${t('Mark better')}</button>` : ''}
          <button class="btn-outline" style="font-size:12px"
                  data-ev-click="showEpisodeSummary('${escHtml(e.id)}')">${t('Summary')}</button>
          <button class="btn-outline" style="font-size:12px"
                  data-ev-click="deleteEpisode('${escHtml(e.id)}')">${t('Remove')}</button>
        </div>
      </div>
      <div id="ep-sum-${escHtml(e.id)}"></div>
    </div>`).join('');
}

async function showEpisodeSummary(id) {
  const box = document.getElementById('ep-sum-' + id);
  if (!box) return;
  if (box.innerHTML) { box.innerHTML = ''; return; }      // toggle
  const s = await fetch(`/api/episodes/${encodeURIComponent(id)}/summary`,
                        {credentials: 'same-origin'}).then(r => r.json()).catch(() => null);
  if (!s) { box.innerHTML = `<div class="restore-note">${t('Could not read that')}</div>`; return; }
  const sym = (s.symptoms || []).map(x =>
    `<div class="restore-row"><span>${escHtml(x.name)}</span>
       <span class="restore-removes">${x.worst ? x.worst + '/10 ' + t('worst') + ' · ' : ''}${
         escHtml(x.first)}${x.first !== x.last ? ' → ' + escHtml(x.last) : ''}</span></div>`).join('');
  const temp = s.peak_temperature_c === null || s.peak_temperature_c === undefined
    ? '' : `<div class="restore-row"><span>${t('Highest temperature')}</span><b>${
        escHtml(fmtTemp ? fmtTemp(s.peak_temperature_c) : s.peak_temperature_c + '°C')}</b></div>`;
  box.innerHTML = `
    <div class="restore-list" style="margin-top:10px">
      ${temp}
      ${(s.medicines_taken || []).length ? `<div class="restore-row"><span>${t('Medicines taken')}</span>
        <span class="restore-removes">${escHtml((s.medicines_taken || []).join(', '))}</span></div>` : ''}
      ${sym}
    </div>
    <div class="restore-note">${tformat('%1 days long · logged on %2 of them.', s.days, s.days_logged)}
      ${t('A day with nothing written down is just that — it does not mean nothing happened.')}</div>`;
}

async function saveEpisode() {
  const body = {
    name: document.getElementById('episode-name')?.value || '',
    started_on: document.getElementById('episode-start')?.value || '',
  };
  const r = await fetch('/api/episodes', {method: 'POST', credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'}, body: JSON.stringify(body)})
    .then(r => r.json()).catch(() => null);
  if (r && r.success) {
    const e = document.getElementById('episode-name'); if (e) e.value = '';
    showToast(t('✓ Episode started'), 'success');
    loadEpisodes();
  } else {
    showToast((r && r.error) || t('Could not start that'), 'error');
  }
}

async function endEpisode(id) {
  await fetch(`/api/episodes/${encodeURIComponent(id)}/end`,
    {method: 'POST', credentials: 'same-origin',
     headers: {'Content-Type': 'application/json'}, body: '{}'}).catch(() => {});
  loadEpisodes();
}

function deleteEpisode(id) {
  // Worth spelling out: people hesitate to delete anything in a health app, and
  // the honest reassurance is that only the grouping goes.
  undoable(t('Removing this episode — your symptoms and readings stay'), async () => {
    await fetch('/api/episodes/' + encodeURIComponent(id),
                {method: 'DELETE', credentials: 'same-origin'}).catch(() => {});
    loadEpisodes();
  });
}

// ── Short courses ──────────────────────────────────────────────────────────
async function loadCourses() {
  const el = document.getElementById('course-list');
  if (!el) return;
  const r = await fetch('/api/courses', {credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!r || !r.courses.length) { el.innerHTML = ''; return; }
  el.innerHTML = `
    <div class="panel" style="padding:18px 20px;margin-bottom:20px">
      <h2 class="panel-title" style="margin-bottom:10px">📅 ${t('Courses')}</h2>
      <div class="restore-list">${r.courses.map(c => {
        const prog = c.doses_scheduled
          ? tformat('%1 of %2 doses logged', c.doses_taken, c.doses_scheduled) : '';
        // Stated, never advised. Whether an unfinished course matters is a
        // question for whoever prescribed it.
        const state = c.finished
          ? (c.stopped_early ? t('ended — fewer doses logged than scheduled') : t('finished'))
          : tformat('%1 days to go', c.days_left);
        return `<div class="restore-row">
          <span><b>${escHtml(c.name)}</b><br>
            <span class="restore-removes">${escHtml(c.start_date)} → ${escHtml(c.end_date)} · ${escHtml(state)}</span></span>
          <span>${escHtml(prog)}</span></div>`;
      }).join('')}</div>
    </div>`;
}

// ── "You're offline — this is an old copy" ─────────────────────────────────
// The service worker can answer a handful of reads from cache when there's no
// connection. That is only safe if the screen says so: a dose list is worth
// looking at precisely because it is today's, and yesterday's shown silently is
// worse than an empty page.
//
// The banner is driven by a header the worker stamps on anything it serves from
// cache, so it can never appear when the data really did come from the server.
let _offlineSince = null;

function noteResponseFreshness(res) {
  if (!res || !res.headers) return res;
  if (res.headers.get('X-Arogo-Offline') === '1') {
    _offlineSince = res.headers.get('X-Arogo-Cached-At') || _offlineSince;
    _renderOfflineBanner();
  } else if (_offlineSince) {
    _offlineSince = null;                       // a live answer clears it
    _renderOfflineBanner();
  }
  return res;
}

function _renderOfflineBanner() {
  let el = document.getElementById('offline-data-banner');
  if (!_offlineSince) { if (el) el.remove(); return; }
  if (!el) {
    el = document.createElement('div');
    el.id = 'offline-data-banner';
    el.className = 'offline-data-banner';
    el.setAttribute('role', 'status');
    document.body.appendChild(el);
  }
  // Names the moment, not a vague "offline". "As of 09:14 this morning" is what
  // lets someone decide whether to trust what they're looking at.
  const when = _agoText(_offlineSince);
  el.textContent = tformat("📴 You're offline — showing a copy saved %1", when);
}

// ── Bulk selection ─────────────────────────────────────────────────────────
// Acting on one row at a time is fine until it isn't. Restoring twenty things
// after a mistaken delete — the exact case the trash exists for — is where
// one-at-a-time becomes the reason the safety net doesn't get used.
//
// Deliberately generic and opt-in: a list adds a checkbox per row and calls
// bulkBar() to render its actions. Nothing here knows what a trash item or a
// record is, so the next list to want it doesn't need new machinery.
const _bulk = {};                       // scope → Set of selected ids

function bulkToggle(scope, id, on) {
  const set = _bulk[scope] || (_bulk[scope] = new Set());
  if (on) set.add(id); else set.delete(id);
  _bulkRefresh(scope);
}

function bulkSelected(scope) {
  return [...(_bulk[scope] || [])];
}

function bulkClear(scope) {
  _bulk[scope] = new Set();
  document.querySelectorAll(`[data-bulk-scope="${scope}"]`).forEach(cb => { cb.checked = false; });
  _bulkRefresh(scope);
}

function bulkToggleAll(scope, on) {
  const set = _bulk[scope] || (_bulk[scope] = new Set());
  document.querySelectorAll(`[data-bulk-scope="${scope}"]`).forEach(cb => {
    cb.checked = !!on;
    if (on) set.add(cb.dataset.bulkId); else set.delete(cb.dataset.bulkId);
  });
  _bulkRefresh(scope);
}

function _bulkRefresh(scope) {
  const bar = document.getElementById('bulk-bar-' + scope);
  if (!bar) return;
  const n = (_bulk[scope] || new Set()).size;
  bar.style.display = n ? 'flex' : 'none';
  const count = document.getElementById('bulk-count-' + scope);
  if (count) count.textContent = tformat('%1 selected', n);
}

// The checkbox a row renders. `id` is the thing the action will act on.
function bulkCheckbox(scope, id) {
  return `<input type="checkbox" class="bulk-cb" data-bulk-scope="${escHtml(scope)}"
                 data-bulk-id="${escHtml(id)}" aria-label="${t('Select')}"
                 data-ev-change="bulkToggle('${escHtml(scope)}','${escHtml(id)}',this.checked)">`;
}

// The action bar. Hidden until something is picked, so it never adds clutter to
// a list nobody is selecting from.
function bulkBar(scope, actions) {
  return `<div class="bulk-bar" id="bulk-bar-${escHtml(scope)}" style="display:none">
      <span id="bulk-count-${escHtml(scope)}" class="bulk-count"></span>
      <span style="flex:1"></span>
      ${actions.map(a => `<button class="btn-outline" style="font-size:12px"
          data-ev-click="${a.handler}">${escHtml(a.label)}</button>`).join('')}
      <button class="btn-outline" style="font-size:12px"
              data-ev-click="bulkClear('${escHtml(scope)}')">${t('Clear')}</button>
    </div>`;
}

// Run one request per selected id, then report what actually happened. The
// count comes from the responses, not from how many were ticked — claiming
// "20 restored" when three failed is the kind of lie this app avoids.
async function bulkRun(scope, fn, verb) {
  const ids = bulkSelected(scope);
  if (!ids.length) return;
  let ok = 0, failed = 0;
  for (const id of ids) {
    try { (await fn(id)) ? ok++ : failed++; } catch (e) { failed++; }
  }
  bulkClear(scope);
  if (failed) showToast(tformat('%1 %2, %3 could not be', ok, verb, failed), 'warn');
  else showToast(tformat('✓ %1 %2', ok, verb), 'success');
}

// ── Trash ──────────────────────────────────────────────────────────────────
// Deleting a health record used to be permanent. Some of it can't be recreated,
// so a delete now moves the row aside for thirty days.
let _trashTimer = null;

async function loadTrash() {
  const el = document.getElementById('trash-list');
  if (!el) return;
  const q = (document.getElementById('trash-search')?.value || '').trim();
  clearTimeout(_trashTimer);
  _trashTimer = setTimeout(async () => {
    const r = await fetch('/api/trash?q=' + encodeURIComponent(q), {credentials: 'same-origin'})
      .then(r => r.json()).catch(() => null);
    if (!r) { el.innerHTML = `<div class="restore-row">${t('Could not read your trash')}</div>`; return; }
    if (!r.items.length) {
      el.innerHTML = `<div class="restore-note">${q
        ? tformat('Nothing in your trash matches "%1".', escHtml(q))
        : tformat('Your trash is empty. Anything you delete stays here for %1 days.', r.retention_days)}</div>`;
      return;
    }
    // Restoring twenty things one at a time after a mistaken bulk delete is
    // exactly the friction that stops people trusting the safety net.
    el.innerHTML = `
      <label class="bulk-all"><input type="checkbox"
        data-ev-change="bulkToggleAll('trash',this.checked)"> ${t('Select all')}</label>
      ${bulkBar('trash', [
        {label: t('Restore selected'), handler: 'bulkRestoreTrash()'},
        {label: t('Delete selected'), handler: 'bulkPurgeTrash()'},
      ])}
      <div class="restore-list">${r.items.map(i => {
      // Say how long is left, not just that it's here — the number is the whole
      // point, and "2 days left" is what makes someone act now.
      const left = i.days_left === null ? ''
        : (i.days_left <= 0 ? t('goes today')
                            : tformat('%1 days left', i.days_left));
      return `<div class="restore-row">
        <span style="display:flex;gap:10px;align-items:flex-start">
          ${bulkCheckbox('trash', i.id)}
          <span><b>${escHtml(i.label)}</b><br>
            <span class="restore-removes">${escHtml(i.kind)} · ${escHtml(left)}</span></span></span>
        <span style="display:flex;gap:6px;align-items:flex-start">
          ${i.restorable ? `<button class="btn-outline" style="font-size:12px"
             data-ev-click="restoreTrashItem('${escHtml(i.id)}')">${t('Restore')}</button>` : ''}
          <button class="btn-outline" style="font-size:12px"
                  data-ev-click="purgeTrashItem('${escHtml(i.id)}')">${t('Delete now')}</button>
        </span></div>`;
    }).join('')}</div>
    <div class="restore-note">${tformat('Anything here is deleted for good after %1 days.', r.retention_days)}</div>`;
    _bulkRefresh('trash');
  }, 180);
}

async function restoreTrashItem(id) {
  const r = await fetch(`/api/trash/${encodeURIComponent(id)}/restore`,
                        {method: 'POST', credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (r && r.ok) {
    // Name what came back and where it went — a silent "done" leaves the user
    // hunting for it.
    showToast(tformat('✓ %1 restored', r.label || r.kind || t('Item')), 'success');
    loadTrash();
  } else {
    showToast((r && r.error) || t('Could not restore that'), 'error');
  }
}

function purgeTrashItem(id) {
  undoable(t('Deleting this for good'), async () => {
    const r = await fetch('/api/trash/' + encodeURIComponent(id),
                          {method: 'DELETE', credentials: 'same-origin'})
      .then(r => r.json()).catch(() => null);
    if (r && r.success) loadTrash();
    else showToast(t('Could not delete that'), 'error');
  });
}

async function bulkRestoreTrash() {
  // Restoring is not destructive, so it runs straight away — the undoable bar
  // is for the things you can't take back.
  await bulkRun('trash', async id => {
    const r = await fetch(`/api/trash/${encodeURIComponent(id)}/restore`,
      {method: 'POST', credentials: 'same-origin'}).then(r => r.json()).catch(() => null);
    return !!(r && r.ok);
  }, t('restored'));
  loadTrash();
}

function bulkPurgeTrash() {
  const n = bulkSelected('trash').length;
  if (!n) return;
  undoable(tformat('Deleting %1 items for good', n), async () => {
    await bulkRun('trash', async id => {
      const r = await fetch('/api/trash/' + encodeURIComponent(id),
        {method: 'DELETE', credentials: 'same-origin'}).then(r => r.json()).catch(() => null);
      return !!(r && r.success);
    }, t('deleted'));
    loadTrash();
  });
}

function emptyTrash() {
  undoable(t('Emptying the trash — this cannot be undone'), async () => {
    const r = await fetch('/api/trash', {method: 'DELETE', credentials: 'same-origin'})
      .then(r => r.json()).catch(() => null);
    if (r && r.success) {
      showToast(tformat('Removed %1 items for good', r.removed), 'success');
      loadTrash();
    } else {
      showToast(t('Could not empty the trash'), 'error');
    }
  });
}

// ── Storage ────────────────────────────────────────────────────────────────
// Uploads live on an SD card with a hard limit and nobody watching it. When it
// fills, SQLite writes start failing — which in this app means a logged dose
// quietly not saving, with the person holding the pill none the wiser.
function fmtBytes(n) {
  if (n === null || n === undefined) return '—';       // unknown, not zero
  const u = ['B', 'KB', 'MB', 'GB', 'TB'];
  let i = 0, v = Number(n) || 0;
  while (v >= 1024 && i < u.length - 1) { v /= 1024; i++; }
  return `${v >= 10 || i === 0 ? Math.round(v) : v.toFixed(1)} ${u[i]}`;
}

// ── Backups ─────────────────────────────────────────────────────────────────
// Nightly backups have been running and verifying themselves with nowhere to
// say so. The whole value of a backup system is knowing where you stand before
// you need it, so this leads with the verdict — covered or not — and only then
// with the detail.
async function loadBackups() {
  const el = document.getElementById('backup-status');
  if (!el) return;
  const s = await fetch('/api/backups', {credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!s) {
    el.innerHTML = `<div class="restore-row">${t('Could not check your backups')}</div>`;
    return;
  }
  const run = `<button class="btn-outline" style="margin-top:12px"
      data-ev-click="runBackupNow()" id="backup-run-btn">${t('Back up now')}</button>`;

  if (!s.has_any) {
    el.innerHTML = `<div class="restore-row"><span>⚠️ <b>${t('No backups yet')}</b></span></div>
      <div class="restore-note">${escHtml(s.note || '')}</div>${run}`;
    _a11yEnhance(el);
    return;
  }

  const n = s.newest;
  const ok = s.verified && s.verified.ok;
  // "Verified" and "recent" are separate claims and the panel makes both, because
  // a fresh file that will not open and a readable file from last month fail in
  // completely different ways and need different actions.
  const verdict = !ok
    ? `<span style="color:var(--danger,#b3261e)">⚠️ <b>${t('The newest backup could not be read')}</b></span>`
    : s.stale
      ? `<span style="color:var(--warn,#8a6100)">⚠️ <b>${t('Your backup is out of date')}</b></span>`
      : `<span>✓ <b>${t('Backed up and verified')}</b></span>`;

  const age = n.age_hours < 1 ? t('less than an hour ago')
            : n.age_hours < 48 ? tformat('%1 hours ago', Math.round(n.age_hours))
            : tformat('%1 days ago', Math.round(n.age_hours / 24));

  const row = (label, value) =>
    `<div class="restore-row"><span>${escHtml(label)}</span><b>${escHtml(value)}</b></div>`;

  el.innerHTML = `
    <div class="restore-row">${verdict}</div>
    ${row(t('Last taken'), age)}
    ${row(t('Size'), fmtBytes(n.bytes))}
    ${row(t('Copies kept'), tformat('%1 of %2', s.count, s.keep))}
    ${row(t('Space they use'), fmtBytes(s.total_bytes))}
    ${!ok && s.verified && s.verified.error
      ? `<div class="restore-note">${escHtml(s.verified.error)}</div>` : ''}
    ${s.stale && ok
      ? `<div class="restore-note">${tformat(
          'Anything logged since then is not in a backup yet. Backups are called stale after %1 hours.',
          s.stale_after_hours)}</div>` : ''}
    ${_offsiteLine(s.offsite)}
    ${run}`;
  _a11yEnhance(el);
}

// The half of the story the on-disk backups cannot tell. Both the database and
// its backups sit on the same SD card, so "backed up and verified" is true and
// says nothing about the failure that is actually likely: the card dying, or
// the box being lost. This states the gap and dates it.
function _offsiteLine(o) {
  if (!o) return '';
  const download = `<button class="btn-outline" style="font-size:12px;margin-top:8px"
      data-ev-click="downloadBackup()">${t('Download a copy')}</button>`;
  if (!o.has_any) {
    return `<div class="restore-note">${escHtml(o.note || '')}</div>${download}`;
  }
  if (o.age_days === null) {
    return `<div class="restore-note">${escHtml(o.note || '')}</div>${download}`;
  }
  const when = o.age_days <= 0 ? t('today')
             : o.age_days === 1 ? t('yesterday')
             : tformat('%1 days ago', o.age_days);
  return `<div class="restore-row"><span>${t('Last copy taken off this server')}</span>
      <b${o.stale ? ' style="color:var(--warn,#8a6100)"' : ''}>${escHtml(when)}</b></div>
    ${o.stale ? `<div class="restore-note">${tformat(
      'Backups here live on the same card as your data, so they survive a mistake but not a lost or failed device. A copy older than %1 days is worth replacing.',
      o.stale_after_days)}</div>${download}` : ''}`;
}

async function runBackupNow() {
  const btn = document.getElementById('backup-run-btn');
  if (btn) { btn.disabled = true; btn.textContent = t('Backing up…'); }
  const r = await fetch('/api/backups/run', {method: 'POST', credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  // A backup that was taken but failed verification is not a success, and the
  // toast must not say it was.
  if (r && r.ok) showToast(t('✓ Backed up and verified'), 'success');
  else showToast(_backupFailureText(r), 'error');
  loadBackups();
}

// The API reports why in a slug. Each one means something specific and
// actionable, so translate it rather than printing "verify_failed" at someone.
function _backupFailureText(r) {
  const reason = r && r.reason;
  if (reason === 'postgres_needs_pg_dump')
    return t('This server uses PostgreSQL, which needs pg_dump to back up. Run scripts/backup.py instead.');
  if (reason === 'verify_failed')
    return t('The copy was made but would not open, so it was thrown away rather than left looking healthy.');
  if (reason === 'copy_failed')
    return t('The copy could not be written — the disk may be full.');
  if (reason === 'no_database_file')
    return t('There is no database file on this server to copy.');
  return (r && r.error) || t('The backup did not complete');
}

// ── Referential drift ───────────────────────────────────────────────────────
// Rows whose parent was destroyed for good. They can never be shown anywhere
// and they used to count toward adherence, so the panel says what they are and
// offers to clear them — but only appears when there is something to say.
async function loadIntegrity() {
  const el = document.getElementById('integrity-report');
  if (!el) return;
  const r = await fetch('/api/storage/integrity', {credentials: 'same-origin'})
    .then(r => r.json()).catch(() => null);
  if (!r || !r.total) { el.innerHTML = ''; return; }   // nothing to say, say nothing
  el.innerHTML = `<div style="margin-top:14px;padding-top:14px;border-top:1px solid var(--gray-100)">
      <div class="restore-row"><span>${t('Left over from deleted records')}</span>
        <b>${tformat(r.total === 1 ? '%1 row' : '%1 rows', r.total)}</b></div>
      ${r.orphans.map(o => `<div class="restore-row">
        <span class="vp-dim">${escHtml(o.child.replace(/_/g, ' '))}</span>
        <span class="vp-dim">${o.count}</span></div>`).join('')}
      <div class="restore-note">${escHtml(r.note)}</div>
      <button class="btn-outline" style="margin-top:10px"
              data-ev-click="repairIntegrity()">${t('Clear them')}</button>
    </div>`;
  _a11yEnhance(el);
}

function repairIntegrity() {
  // Undoable like every other delete in the app — although by construction
  // these rows reference nothing that still exists, so there is nothing the
  // user can lose by clearing them.
  undoable(t('Clearing leftover rows…'), async () => {
    const r = await fetch('/api/storage/integrity',
                          {method: 'POST', credentials: 'same-origin'})
      .then(r => r.json()).catch(() => null);
    if (r && r.success) showToast(tformat('✓ Cleared %1 rows', r.removed), 'success');
    else showToast(t('Could not clear those'), 'error');
    loadIntegrity();
  });
}

// ── Server setup ────────────────────────────────────────────────────────────
// Renders db/readiness.py. Deliberately shows the working items too, not only
// the problems: "email is not set up" means one thing on a page that also says
// what IS working, and something much more alarming on a page that only ever
// lists faults. A green line is information.

const _READY_ICON = {ok: '✓', degraded: '!', off: '○'};

async function loadReadiness() {
  const el = document.getElementById('readiness-report');
  if (!el) return;
  const r = await coalescedGet('/api/server/readiness').catch(() => null);
  if (!r) { el.innerHTML = `<div class="restore-row">${t('Could not read the server setup')}</div>`; return; }

  // Core problems first and stated plainly. Someone skimming should not have to
  // work out that "session secret" is more urgent than "WhatsApp".
  const head = r.core_problems.length
    ? `<div class="rd-alert">${escHtml(tformat(
         r.core_problems.length === 1
           ? '%1 thing here puts your data at risk.'
           : '%1 things here put your data at risk.', r.core_problems.length))}</div>`
    : '';

  const rows = r.items.map(i => {
    // The cost and fix are only shown for things that are not working. On a
    // healthy line they would be a wall of text about a problem nobody has.
    const explain = i.status === 'ok' ? '' : `
      <div class="rd-cost">${escHtml(t(i.cost))}</div>
      <div class="rd-fix"><code>${escHtml(t(i.fix))}</code></div>`;
    return `<div class="rd-item rd-${i.status}">
      <div class="rd-line">
        <span class="rd-dot" aria-hidden="true">${_READY_ICON[i.status] || '·'}</span>
        <span class="rd-name">${escHtml(t(i.name))}</span>
        <span class="rd-detail">${escHtml(_readyDetail(i.detail))}</span>
        <span class="rd-status">${escHtml(t(_readyWord(i.status)))}</span>
      </div>${explain}</div>`;
  }).join('');

  el.innerHTML = head + `<div class="rd-list">${rows}</div>`;
  _a11yEnhance(el);
}

// The server sends {text, args} — an English template plus its values — rather
// than a finished sentence, so the sentence can be translated here and the
// values stay values. A hostname or a byte count is not translatable text.
function _readyDetail(d) {
  if (!d) return '';
  if (typeof d === 'string') return d;              // raw data, as sent
  return tformat.apply(null, [d.text].concat(d.args || []));
}

// Words, not colours. The status has to survive being read aloud, printed in
// black and white, or looked at by someone who cannot tell the dot's colour.
function _readyWord(status) {
  return status === 'ok' ? 'working'
       : status === 'degraded' ? 'needs attention'
       : 'not set up';
}

async function loadStorage() {
  const el = document.getElementById('storage-report');
  if (!el) return;
  const s = await coalescedGet('/api/storage').catch(() => null);
  if (!s) { el.innerHTML = `<div class="restore-row">${t('Could not read storage')}</div>`; return; }

  const row = (label, value, extra) =>
    `<div class="restore-row"><span>${escHtml(label)}</span>
       <span>${extra || ''}<b>${escHtml(value)}</b></span></div>`;

  let html = '';
  if (s.low_space) {
    html += `<div class="rh-banner" role="status" style="margin-bottom:12px">
      <span aria-hidden="true">⚠️</span>
      <div class="rh-body"><b>${t('This server is nearly out of space')}</b><br>
        ${tformat('%1 free. Below this, Arogo may stop being able to save what you log.',
                  fmtBytes(s.disk.free_bytes))}</div></div>`;
  }
  html += '<div class="restore-list">';
  html += row(t('Your files'), fmtBytes(s.mine.bytes),
              `<span class="restore-removes">${tformat('%1 files', s.mine.files)}</span>`);
  html += row(t('All uploads on this server'), fmtBytes(s.uploads.bytes),
              `<span class="restore-removes">${tformat('%1 files', s.uploads.files)}</span>`);
  if (s.database_bytes !== null) html += row(t('Database'), fmtBytes(s.database_bytes));
  html += row(t('Free space'), fmtBytes(s.disk.free_bytes));
  html += '</div>';

  // A file no row points at. Never removed automatically: the app can no longer
  // say whose it was or what it showed, so that call belongs to whoever owns
  // the machine.
  if (s.orphans.count) {
    html += `<div class="restore-note">
      ${tformat('%1 files (%2) are no longer linked to any record — left over from deleted accounts or restores.',
                s.orphans.count, fmtBytes(s.orphans.bytes))}
      <button class="btn-outline" style="font-size:12px;margin-left:8px"
              data-ev-click="cleanOrphans()">${t('Delete them')}</button></div>`;
  }
  // A record promising a document that isn't there. Not a space problem — the
  // page will offer a file that won't open.
  if (s.missing && s.missing.length) {
    html += `<div class="restore-note">${tformat(
      '%1 records point at a file that is no longer on the server.', s.missing.length)}</div>`;
  }
  el.innerHTML = html;
}

function cleanOrphans() {
  // undoable(), like every other destructive action here — a window to change
  // your mind rather than a modal to click through. Nothing is sent until the
  // bar times out, so Undo genuinely leaves the files in place.
  undoable(t('Deleting files that no longer belong to any record'), async () => {
    const r = await fetch('/api/storage/orphans', {method: 'DELETE', credentials: 'same-origin'})
      .then(r => r.json()).catch(() => null);
    if (r && r.success) {
      showToast(tformat('✓ Removed %1 files', r.removed), 'success');
      loadStorage();
    } else {
      showToast(t('Could not remove those files'), 'error');
    }
  });
}

// ── "Reminders aren't being sent" ───────────────────────────────────────────
// The chain that delivers a dose reminder — push configured on the server, the
// scheduler alive, this device subscribed — fails silently at every link. The
// app looks completely normal and the person finds out by missing medication,
// which is precisely the thing they installed it to avoid.
//
// Shown only to someone actually relying on reminders (the server decides), and
// dismissible for the session but not for good: if reminders really are down,
// quietly forgetting about it is the failure we are trying to prevent.
async function loadReminderHealth() {
  const el = document.getElementById('reminder-health-banner');
  if (!el) return;
  const h = await coalescedGet('/api/reminders/health').catch(() => null);
  if (!h || h.ok || !h.problems || !h.problems.length
      || sessionStorage.getItem('me_rh_dismissed') === '1') {
    el.style.display = 'none';
    return;
  }
  // State the fact and, where the user can actually do something, the step.
  // Nothing here claims a dose was missed — the app has no idea whether the
  // medicine was taken, and saying so would be inventing a fact about them.
  const rows = h.problems.map(p => `
    <div style="margin-bottom:6px">
      <b>${escHtml(t(p.title))}</b><br>
      <span style="opacity:.9">${escHtml(p.detail)}</span>
    </div>`).join('');
  const fixable = h.problems.some(p => p.actionable_by_user);
  el.innerHTML = `
    <div class="rh-banner" role="status">
      <span class="rh-icon" aria-hidden="true">🔕</span>
      <div class="rh-body">${rows}</div>
      <div class="rh-actions">
        ${fixable ? `<button class="btn-outline"
            data-ev-click="switchView('notifications')">${t('Notifications')}</button>` : ''}
        <button class="btn-outline"
                data-ev-click="dismissReminderHealth()">${t('Dismiss')}</button>
      </div>
    </div>`;
  el.style.display = 'block';
}

function dismissReminderHealth() {
  // Session-scoped on purpose. It comes back next time the app opens while the
  // problem is still there.
  sessionStorage.setItem('me_rh_dismissed', '1');
  const el = document.getElementById('reminder-health-banner');
  if (el) el.style.display = 'none';
}

async function loadDashboardTodos() {
  const r = await fetch('/api/todos?status=pending').then(r => r.json()).catch(() => null);
  const el = document.getElementById('dash-todos-list');
  if (!el) return 0;
  // Tasks live on the dashboard: the panel is always shown so the inline
  // quick-add is always available. The full Tasks screen ("Manage →") keeps
  // the depth — priorities, due dates, reminders, tags, completed history.
  const panel = document.getElementById('dash-tasks-panel');
  if (panel) panel.style.display = '';
  const agenda = document.getElementById('dash-agenda-grid');
  if (agenda) agenda.style.display = '';
  const allPending = r?.todos || [];
  const todos = allPending.slice(0, 5);
  if (todos.length === 0) {
    el.innerHTML = '<div class="dash-todo-empty">Nothing pending — add a task above.</div>';
    return 0;
  }
  const today = localToday();
  const PRI = { high:'🔴', medium:'🟡', low:'🟢' };
  el.innerHTML = todos.map(t => {
    const isOverdue = t.due_date && t.due_date < today;
    const dueStr = t.due_date === today ? 'Today' : t.due_date ? t.due_date.slice(5) : '';
    return `<div class="dash-todo-row" data-ev-click="switchView('todos')">
      <div class="dash-todo-check" data-ev-click="event.stopPropagation();dashToggleTodo('${t.id}')"></div>
      <div class="dash-todo-title">${escHtml(t.title)}</div>
      <span class="dash-todo-pri">${PRI[t.priority]||'🟡'}</span>
      ${dueStr ? `<span class="dash-todo-due ${isOverdue?'overdue':''}">${dueStr}</span>` : ''}
    </div>`;
  }).join('');
  if (allPending.length > 5) {
    el.innerHTML += `<div style="text-align:center;padding:6px 0">
      <a href="#" data-ev-click="switchView('todos');return false" style="font-size:12px;color:var(--teal-600)">+${allPending.length-5} more tasks →</a>
    </div>`;
  }
  return allPending.length;
}

async function dashToggleTodo(id) {
  await fetch(`/api/todos/${id}/toggle`, {method:'POST'});
  loadDashboardTodos();
  loadTodos();
}

// Add a task inline from the dashboard (the Tasks screen's most-common action,
// on home). Defaults to medium priority / no due date; use "Manage →" for those.
async function dashAddTodo() {
  const inp = document.getElementById('dash-todo-input');
  const title = (inp?.value || '').trim();
  if (!title) return;
  inp.value = '';
  await fetch('/api/todos', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title, priority: 'medium' })
  }).catch(() => {});
  loadDashboardTodos();
  try { loadTodos(); } catch (e) {}
}
function dashAddTodoKey(e) { if (e.key === 'Enter') { e.preventDefault(); dashAddTodo(); } }

// Sidebar user info from profile
async function updateSidebarUser() {
  const r = await coalescedGet('/api/food/profile').catch(() => null);
  if (!r?.profile) return;
  const p = r.profile;
  const name  = p.name || 'User';
  const initials = name.split(' ').map(w=>w[0]?.toUpperCase()||'').join('').slice(0,2) || 'U';
  setText('sidebar-name',   name);
  setText('sidebar-avatar', initials);
  const goal = { lose_fast:'Losing weight', lose:'Losing weight', maintain:'Maintaining', gain:'Building muscle', gain_fast:'Building muscle' };
  setText('sidebar-role', goal[p.goal] || 'Health Profile');
}

// Patch loadDashboard to include new panels
const _dashBase = loadDashboard;
loadDashboard = async function() {
  await _dashBase.apply(this, arguments);
  loadDashboardTodos();
};

