const EXPORT_SECTIONS = [
  { key:'food_logs',          icon:'🍽️', name:'Food Logs',         desc:'Meals, calories, macros' },
  { key:'fitness_activities', icon:'🏃', name:'Workouts',           desc:'Activities, duration, calories' },
  { key:'sleep_logs',         icon:'🌙', name:'Sleep Logs',         desc:'Bedtime, duration, quality' },
  { key:'symptoms',           icon:'🩺', name:'Symptoms',           desc:'Logged symptoms & severity' },
  { key:'vitals',             icon:'❤️', name:'Vitals',             desc:'BP, blood sugar, heart rate' },
  { key:'thoughts',           icon:'💭', name:'Thoughts',           desc:'Daily journal entries' },
  { key:'todos',              icon:'✅', name:'Tasks',              desc:'To-do list items' },
  { key:'body_metrics',       icon:'⚖️', name:'Body Metrics',       desc:'Weight, BMI, body fat' },
  { key:'hydration_logs',     icon:'💧', name:'Hydration',          desc:'Daily water intake logs' },
  { key:'habits',             icon:'⭐', name:'Habits & Logs',      desc:'Habits + completion history' },
  { key:'medicines',          icon:'💊', name:'Medicines',          desc:'Medication list' },
];

let _exportFmt      = 'json';
let _exportSelected = new Set(EXPORT_SECTIONS.map(s => s.key));
let _exportCounts   = {};

async function initExportView() {
  // Set default dates
  const today = new Date().toISOString().slice(0,10);
  const yearAgo = new Date(Date.now() - 365*86400000).toISOString().slice(0,10);
  const fromEl = document.getElementById('export-from-date');
  const toEl   = document.getElementById('export-to-date');
  if (fromEl && !fromEl.value) fromEl.value = yearAgo;
  if (toEl && !toEl.value)     toEl.value   = today;

  renderExportSections();
  await loadExportCounts();
  loadScopedExportCats();
  try { loadReadiness(); } catch (e) {}
  try { loadStorage(); } catch (e) {}
  try { loadIntegrity(); } catch (e) {}
  try { loadBackups(); } catch (e) {}
}

async function loadExportCounts() {
  const from = document.getElementById('export-from-date')?.value || '2000-01-01';
  const to   = document.getElementById('export-to-date')?.value   || new Date().toISOString().slice(0,10);
  const r = await fetch(`/api/export/counts?from=${from}&to=${to}`).then(r=>r.json()).catch(()=>({}));
  _exportCounts = r;
  renderExportSections();
  updateExportEstimate();
}

function renderExportSections() {
  const el = document.getElementById('export-sections-grid');
  if (!el) return;
  el.innerHTML = EXPORT_SECTIONS.map(s => {
    const selected = _exportSelected.has(s.key);
    const count = _exportCounts[s.key];
    const countStr = count != null ? `${count} record${count!==1?'s':''}` : '—';
    return `<div class="export-section-card ${selected?'selected':''}" data-ev-click="toggleExportSection('${s.key}')">
      <div class="export-section-check"></div>
      <div class="export-section-icon">${s.icon}</div>
      <div class="export-section-info">
        <div class="export-section-name">${s.name}</div>
        <div class="export-section-count">${countStr}</div>
      </div>
    </div>`;
  }).join('');
}

function toggleExportSection(key) {
  if (_exportSelected.has(key)) _exportSelected.delete(key);
  else _exportSelected.add(key);
  renderExportSections();
  updateExportEstimate();
}

function setAllExportSections(val) {
  if (val) EXPORT_SECTIONS.forEach(s => _exportSelected.add(s.key));
  else _exportSelected.clear();
  renderExportSections();
  updateExportEstimate();
}

function updateExportEstimate() {
  const el = document.getElementById('export-size-estimate');
  if (!el) return;
  const total = [..._exportSelected].reduce((sum, k) => sum + (_exportCounts[k]||0), 0);
  el.textContent = total > 0 ? `~${total} records selected` : 'Nothing selected';
  // Update button text
  const btn = document.getElementById('export-download-btn');
  const fmtLabel = _exportFmt.toUpperCase();
  if (btn) btn.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg> Download ${fmtLabel} (${total} records)`;
}

function setExportFmt(fmt) {
  _exportFmt = fmt;
  document.querySelectorAll('.export-fmt-btn').forEach(b => b.classList.toggle('active', b.dataset.fmt === fmt));
  updateExportEstimate();
}

function setExportPreset(days) {
  const today = new Date().toISOString().slice(0,10);
  const fromEl = document.getElementById('export-from-date');
  const toEl   = document.getElementById('export-to-date');
  if (!fromEl || !toEl) return;
  toEl.value = today;
  if (days === 0) {
    fromEl.value = '2000-01-01';
  } else {
    fromEl.value = new Date(Date.now() - days*86400000).toISOString().slice(0,10);
  }
  loadExportCounts();
}

// ── Passphrase-protected exports ────────────────────────────────────────────
//
// The scope here is deliberate and worth stating, because "encryption" invites
// a bigger claim than this delivers.
//
// The database sitting on the Pi is NOT what this protects. Encrypting it in
// the application would put the key on the same SD card as the data, which
// stops nobody who is holding the card; that threat is a full-disk-encryption
// problem for the operating system, and pretending otherwise would be worse
// than leaving it plain, because it would feel solved.
//
// What this protects is the copy that LEAVES. An export is a complete medical
// history in one file, and it goes to a Downloads folder, an email, a cloud
// sync, a USB stick handed to someone. That file is genuinely ours to protect
// and it has been plaintext until now.
//
// The passphrase never reaches the server. Derivation and encryption happen in
// the browser with WebCrypto, so what the server hands over is the plain export
// and what lands on disk is ciphertext — the server never holds the key and
// cannot be made to give it up.
//
// The format is written to be openable WITHOUT Arogo. An encrypted export that
// only the app that wrote it can read is a worse export than no export: the
// point of taking your data out is that it is yours. The header names its own
// parameters, and scripts/decrypt_export.py opens it with nothing but a
// passphrase.

const AROGO_ENC_MAGIC = 'AROGO-ENC1';
// OWASP's floor for PBKDF2-HMAC-SHA256. It costs about a second on a phone,
// which is the intended trade: the file may sit in a cloud backup for years.
const AROGO_KDF_ITERATIONS = 600000;

function _cryptoObj() {
  const c = (typeof crypto !== 'undefined' && crypto) ||
            (typeof window !== 'undefined' && window.crypto) || null;
  return (c && c.subtle) ? c : null;
}

function arogoCryptoAvailable() { return !!_cryptoObj(); }

function _b64FromBytes(bytes) {
  let s = '';
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}

function _bytesFromB64(b64) {
  const s = atob(b64);
  const out = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
  return out;
}

async function _deriveKey(passphrase, salt, iterations) {
  const c = _cryptoObj();
  const base = await c.subtle.importKey(
    'raw', new TextEncoder().encode(passphrase), 'PBKDF2', false, ['deriveKey']);
  return c.subtle.deriveKey(
    {name: 'PBKDF2', salt, iterations, hash: 'SHA-256'},
    base, {name: 'AES-GCM', length: 256}, false, ['encrypt', 'decrypt']);
}

async function arogoEncrypt(plaintext, passphrase) {
  const c = _cryptoObj();
  if (!c) throw new Error('no-webcrypto');
  if (!passphrase) throw new Error('no-passphrase');
  const salt = c.getRandomValues(new Uint8Array(16));
  const iv   = c.getRandomValues(new Uint8Array(12));
  const key  = await _deriveKey(passphrase, salt, AROGO_KDF_ITERATIONS);
  const ct   = new Uint8Array(await c.subtle.encrypt(
    {name: 'AES-GCM', iv}, key, new TextEncoder().encode(plaintext)));
  // Self-describing: everything needed to decrypt is in the header except the
  // passphrase, and the note tells a future reader where to look.
  const header = {
    kdf: 'PBKDF2-SHA256', iterations: AROGO_KDF_ITERATIONS,
    salt: _b64FromBytes(salt), cipher: 'AES-256-GCM', iv: _b64FromBytes(iv),
    note: 'Arogo encrypted export. Decrypt with scripts/decrypt_export.py or '
        + 'any PBKDF2-SHA256 + AES-256-GCM tool using the parameters above.',
  };
  return `${AROGO_ENC_MAGIC}\n${JSON.stringify(header)}\n${_b64FromBytes(ct)}\n`;
}

function isArogoEncrypted(text) {
  return typeof text === 'string' && text.slice(0, AROGO_ENC_MAGIC.length) === AROGO_ENC_MAGIC;
}

async function arogoDecrypt(blob, passphrase) {
  const c = _cryptoObj();
  if (!c) throw new Error('no-webcrypto');
  const lines = String(blob).split('\n');
  if (lines[0].trim() !== AROGO_ENC_MAGIC) throw new Error('not-encrypted');
  let header;
  try { header = JSON.parse(lines[1]); }
  catch (e) { throw new Error('bad-header'); }
  // Refuse anything whose parameters this build does not implement, rather than
  // guessing. A wrong guess here fails as "wrong passphrase", which would send
  // someone hunting for a typo in a passphrase that was always correct.
  if (header.kdf !== 'PBKDF2-SHA256' || header.cipher !== 'AES-256-GCM')
    throw new Error('unsupported-format');
  const key = await _deriveKey(passphrase, _bytesFromB64(header.salt),
                               header.iterations || AROGO_KDF_ITERATIONS);
  const ct  = _bytesFromB64(lines.slice(2).join('').trim());
  let plain;
  try {
    plain = await c.subtle.decrypt(
      {name: 'AES-GCM', iv: _bytesFromB64(header.iv)}, key, ct);
  } catch (e) {
    // AES-GCM is authenticated, so this covers a wrong passphrase AND a file
    // that was altered in transit. Both mean "do not trust this".
    throw new Error('wrong-passphrase-or-damaged');
  }
  return new TextDecoder().decode(plain);
}

async function doExport() {
  if (_exportSelected.size === 0) { showToast('Select at least one section', 'error'); return; }
  const from = document.getElementById('export-from-date')?.value || '2000-01-01';
  const to   = document.getElementById('export-to-date')?.value   || new Date().toISOString().slice(0,10);
  const sections = [..._exportSelected].join(',');
  const url = `/api/export?format=${_exportFmt}&sections=${sections}&from=${from}&to=${to}`;

  const pass = _exportPassphraseOrNull();
  if (pass === false) return;                       // asked for, and not usable

  if (!pass) {
    // Unprotected: let the browser stream it straight to disk as before.
    const a = document.createElement('a');
    a.href = url; a.download = '';
    document.body.appendChild(a); a.click();
    document.body.removeChild(a);
    showToast(tformat('Downloading %1 export…', _exportFmt.toUpperCase()), 'success');
    return;
  }
  showToast(t('Encrypting…'), 'info');
  try {
    const text = await fetch(url, {credentials: 'same-origin'}).then(r => {
      if (!r.ok) throw new Error('export-failed');
      return r.text();
    });
    const armoured = await arogoEncrypt(text, pass);
    const stamp = new Date().toISOString().slice(0, 10);
    downloadBlob(armoured, `arogo-export-${stamp}.${_exportFmt}.arogo-enc`,
                 'application/octet-stream');
    // Said plainly, because there is no recovery path and no reset link. The
    // server does not have this passphrase and cannot be asked for it.
    showToast(t('✓ Downloaded, encrypted. Nobody can open it without that passphrase — not even Arogo.'), 'success');
  } catch (e) {
    showToast(t('The export could not be encrypted. Nothing was downloaded.'), 'error');
  }
}

function downloadBlob(text, filename, type) {
  const url = URL.createObjectURL(new Blob([text], {type: type || 'text/plain'}));
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 30000);
}

function toggleExportPassphrase(on) {
  const box = document.getElementById('export-passphrase-row');
  if (box) box.style.display = on ? '' : 'none';
}

// A passphrase prompt of the app's own, rather than the browser's. prompt() is
// unstyleable, untranslatable, and blocks the whole page — and this app renders
// every other confirmation itself.
let _passphraseResolve = null;
let _passphraseReturnFocus = null;

function askExportPassphrase() {
  const overlay = document.getElementById('passphrase-overlay');
  if (!overlay) return Promise.resolve(null);
  // Focus, the Tab trap, Escape and focus restore all come from the shared
  // modal machinery now (see _watchModalVisibility). Escape clicks this
  // dialog's own ×, which is wired to cancelPassphrase, so the promise still
  // resolves rather than being left hanging.
  _passphraseReturnFocus = document.activeElement;
  overlay.style.display = 'flex';
  const input = document.getElementById('passphrase-input');
  if (input) { input.value = ''; setTimeout(() => input.focus(), 50); }
  return new Promise(resolve => { _passphraseResolve = resolve; });
}

function submitPassphrase() {
  const v = document.getElementById('passphrase-input')?.value || '';
  closePassphrasePrompt();
  if (_passphraseResolve) { _passphraseResolve(v); _passphraseResolve = null; }
}

function cancelPassphrase() {
  closePassphrasePrompt();
  // null, not '' — an empty passphrase is a thing someone can type, and
  // cancelling is not that.
  if (_passphraseResolve) { _passphraseResolve(null); _passphraseResolve = null; }
}

function closePassphrasePrompt() {
  const overlay = document.getElementById('passphrase-overlay');
  if (overlay) overlay.style.display = 'none';
  const input = document.getElementById('passphrase-input');
  if (input) input.value = '';        // don't leave it sitting in the DOM
  try { _passphraseReturnFocus && _passphraseReturnFocus.focus(); } catch (e) {}
  _passphraseReturnFocus = null;
}

// ── Complete data export + account deletion (DPDP/GDPR) ─────────────────────
async function downloadAllData() {
  // This is the largest and most sensitive file the app produces — everything,
  // in one document — so it honours the same passphrase checkbox as the scoped
  // export above it. Protecting the small export and not this one would be
  // exactly backwards.
  const pass = _exportPassphraseOrNull();
  if (pass === false) return;                       // asked for, and not usable
  showToast(t('Preparing your data…'), 'info');
  try {
    const r = await fetch('/api/account/export', {credentials: 'same-origin'});
    if (!r.ok) throw new Error('export failed');
    const text = await r.text();
    if (pass) {
      downloadBlob(await arogoEncrypt(text, pass), 'arogo-my-data.json.arogo-enc',
                   'application/octet-stream');
      showToast(t('✓ Downloaded, encrypted. Nobody can open it without that passphrase — not even Arogo.'), 'success');
    } else {
      downloadBlob(text, 'arogo-my-data.json', 'application/json');
      showToast(t('✓ Downloaded all your data'), 'success');
    }
  } catch { showToast(t('Could not prepare your data — try again'), 'error'); }
}

// Category 2 — scoped export: pick categories, download only those.
async function loadScopedExportCats() {
  const el = document.getElementById('scoped-export-cats');
  if (!el) return;
  const d = await fetch('/api/export/categories', {credentials:'same-origin'})
    .then(r => r.ok ? r.json() : {categories:[]}).catch(() => ({categories:[]}));
  el.innerHTML = (d.categories || []).map(c =>
    `<label class="scoped-cat"><input type="checkbox" class="scoped-ck" value="${escHtml(c.key)}"> <span>${escHtml(t(c.label))}</span></label>`).join('');
}

async function downloadScopedData() {
  const cats = [...document.querySelectorAll('#scoped-export-cats .scoped-ck:checked')].map(ck => ck.value);
  if (!cats.length) { showToast('Pick at least one category', 'error'); return; }
  showToast('Preparing your data…', 'info');
  try {
    const r = await fetch('/api/export/scoped', {method:'POST', headers:{'Content-Type':'application/json'},
      credentials:'same-origin', body: JSON.stringify({categories: cats})});
    if (!r.ok) throw new Error('export failed');
    const blob = await r.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'arogo-selected-data.json';
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast('✓ Downloaded selected data', 'success');
  } catch { showToast('Could not prepare your data — try again', 'error'); }
}

// ── Backup & restore (self-hosting data safety) ─────────────────────────────
// The confirmation screen used to be built here from a hardcoded list of 22
// table names. A restore touches every table the file mentions, so the other 44
// — labs, allergies, procedures, insurance, notes, the cycle diary — were
// replaced without ever appearing on the screen the user agreed to. The preview
// now comes from the server, which is the only side that knows the real list.
let _restoreData = null;

async function downloadBackup() {
  // This file is the most complete one the app produces — every table this user
  // owns — and it was the one download path left unencrypted while the scoped
  // export and the "download everything" button both honoured the passphrase
  // box. Protecting the two smaller files and not this one was backwards.
  const pass = _exportPassphraseOrNull();
  if (pass === false) return;                       // asked for, and not usable
  try {
    const r = await fetch('/api/backup', {credentials: 'same-origin'});
    if (!r.ok) throw new Error('backup failed');
    const cd = r.headers.get('Content-Disposition') || '';
    const m = cd.match(/filename="([^"]+)"/);
    const name = m ? m[1] : 'arogo-backup.json';
    const text = await r.text();
    if (pass) {
      downloadBlob(await arogoEncrypt(text, pass), name + '.arogo-enc',
                   'application/octet-stream');
      showToast(t('✓ Downloaded, encrypted. Nobody can open it without that passphrase — not even Arogo.'), 'success');
    } else {
      downloadBlob(text, name, 'application/json');
      showToast(t('✓ Backup downloaded'), 'success');
    }
    // The backup panel shows how long since the last copy left this machine.
    try { loadBackups(); } catch (e) {}
  } catch { showToast(t('Could not build the backup — try again'), 'error'); }
}

// Shared by all three download paths so they cannot drift again.
//   null  → the user did not ask for a passphrase; download in the clear
//   false → they did, but it cannot be honoured; the caller must stop
//   string → use it
function _exportPassphraseOrNull() {
  if (!document.getElementById('export-encrypt')?.checked) return null;
  const pass = document.getElementById('export-passphrase')?.value || '';
  if (!arogoCryptoAvailable()) {
    showToast(t('This browser cannot encrypt the file. Untick the passphrase box to download it unprotected.'), 'error');
    return false;
  }
  if (pass.length < 8) {
    showToast(t('Use a passphrase of at least 8 characters — this is the only thing protecting the file.'), 'error');
    return false;
  }
  return pass;
}

// Read a picked file and get usable JSON out of it, decrypting first when the
// file says it is encrypted. Shared by restore and by the check-only path so
// the two can never disagree about what "this file opens" means.
// Resolves to null when the user cancels or the file cannot be read; the reason
// has already been shown by then.
function _readBackupFile(file) {
  return new Promise(resolve => {
    const reader = new FileReader();
    reader.onerror = () => {
      showToast(t('That file could not be read'), 'error');
      resolve(null);
    };
    reader.onload = async () => {
      let text = reader.result;
      // Recognised by its own header, so the user never has to remember which
      // kind of file they picked.
      if (isArogoEncrypted(text)) {
        const pass = await askExportPassphrase();
        if (pass === null) { resolve(null); return; }          // cancelled
        try {
          text = await arogoDecrypt(text, pass);
        } catch (e) {
          showToast(e.message === 'unsupported-format'
            ? t('This file was written by a newer version of Arogo and cannot be opened here.')
            // AES-GCM cannot tell a wrong passphrase from a damaged file, and
            // claiming to know which would send someone hunting for a typo in a
            // passphrase that was right all along.
            : t('That passphrase did not open the file. Either it is wrong, or the file was damaged.'),
            'error');
          resolve(null); return;
        }
      }
      try { resolve(JSON.parse(text)); }
      catch { showToast(t("That file isn't valid JSON"), 'error'); resolve(null); }
    };
    reader.readAsText(file);
  });
}

async function onRestoreFile(input) {
  const f = input.files && input.files[0];
  input.value = '';                    // allow re-selecting the same file later
  if (!f) return;
  const data = await _readBackupFile(f);
  if (!data) return;
  _restoreData = data;
  const el = document.getElementById('restore-preview');
  if (el) { el.style.display = 'block'; el.innerHTML =
    `<div class="restore-row">${t('Checking the file…')}</div>`; }
  // Ask the server what this would actually do — it knows every table the
  // restore touches, and how many of your rows each one would remove.
  const p = await fetch('/api/import/preview', {
    method: 'POST', credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'}, body: JSON.stringify(data),
  }).then(r => r.json()).catch(() => null);
  renderRestorePreview(p);
}

// Check-only. Same read, same decrypt, same server-side preview — and then
// deliberately NOT the restore button.
//
// This exists because of the specific way a backup fails people: it sits
// untouched for a year, and the moment it is needed is the moment nobody can
// afford to find out the passphrase was wrong or the file was truncated. The
// only way to know a backup works is to open it, and there has to be a way to
// do that which cannot accidentally overwrite the data you still have.
async function onCheckBackupFile(input) {
  const f = input.files && input.files[0];
  input.value = '';
  if (!f) return;
  const el = document.getElementById('restore-preview');
  if (el) { el.style.display = 'block'; el.innerHTML =
    `<div class="restore-row">${t('Opening the file…')}</div>`; }
  const data = await _readBackupFile(f);
  if (!data) {
    // The specific reason was already shown. What matters here is the verdict.
    if (el) el.innerHTML = `<div class="restore-warn"><div class="restore-row"><b>${
      t('This file did not open. Do not rely on it as a backup.')}</b></div></div>`;
    return;
  }
  // _restoreData is deliberately NOT set: nothing about checking a file should
  // leave the app one click away from replacing everything with it.
  _restoreData = null;
  const p = await fetch('/api/import/preview', {
    method: 'POST', credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'}, body: JSON.stringify(data),
  }).then(r => r.json()).catch(() => null);
  renderBackupCheck(p, f.name);
}

function renderBackupCheck(p, filename) {
  const el = document.getElementById('restore-preview');
  if (!el) return;
  el.style.display = 'block';
  if (!p || !p.ok) {
    el.innerHTML = `<div class="restore-warn"><div class="restore-row"><b>${
      t('This file opened, but there are no health records in it.')}</b></div>
      <div class="restore-note">${escHtml((p && p.error) || '')}</div></div>`;
    return;
  }
  const rows = (p.tables || []).filter(e => e.incoming > 0);
  const total = (p.totals && p.totals.incoming) || 0;
  const unreadable = (p.totals && p.totals.unreadable) || 0;
  // A file that opens but carries nothing is not a working backup, and saying
  // "✓ opens" over an empty list would be the most misleading possible verdict.
  if (!total) {
    el.innerHTML = `<div class="restore-warn"><div class="restore-row"><b>${
      t('This file opens, but there is nothing in it to restore.')}</b></div>
      <div class="restore-note">${escHtml(filename)}</div></div>`;
    return;
  }
  el.innerHTML = `
    <div class="restore-row"><span>✓ <b>${t('This file opens, and your records are in it')}</b></span></div>
    <div class="restore-note">${escHtml(filename)}</div>
    <div class="restore-list">${rows.map(e =>
      `<div class="restore-row"><span>${escHtml(e.label)}</span><b>${_nRows(e.incoming)}</b></div>`).join('')}</div>
    <div class="restore-row"><span>${t('Total')}</span><b>${_nRows(total)}</b></div>
    ${unreadable ? `<div class="restore-note">${tformat(
      '%1 rows in the file could not be read and would be skipped by a restore.',
      unreadable)}</div>` : ''}
    <div class="restore-note">${t(
      'Nothing was changed. This only opened the file and counted what is inside — checking a backup should never be able to overwrite the data you still have.')}</div>`;
  _a11yEnhance(el);
}

// "1 record" not "1 records" — a count the user is about to act on shouldn't
// read like a placeholder.
function _nRecords(n) { return tformat(n === 1 ? '%1 record' : '%1 records', n); }
function _nRows(n)    { return tformat(n === 1 ? '%1 row' : '%1 rows', n); }

function _restoreRow(e) {
  // Both numbers, each labelled, because a restore is a replace and the layout
  // alone doesn't say which figure is which.
  const parts = [`<b>${tformat('%1 in', e.incoming)}</b>`];
  if (e.current)    parts.unshift(`<span class="restore-removes">${tformat('%1 removed', e.current)}</span>`);
  if (e.unreadable) parts.unshift(`<span class="restore-removes">${tformat('%1 unreadable', e.unreadable)}</span>`);
  return `<div class="restore-row"><span>${escHtml(e.label)}</span>
            <span>${parts.join(' · ')}</span></div>`;
}

function renderRestorePreview(p) {
  const el = document.getElementById('restore-preview');
  if (!el) return;
  el.style.display = 'block';
  if (!p || !p.ok) {
    el.innerHTML = `<div class="restore-warn">${escHtml((p && p.error) ||
      t('No restorable health records were found in that file.'))}</div>`;
    _restoreData = null;
    return;
  }
  const T = p.totals || {};
  let html = '';

  // The quiet data-loss case, stated first and plainly: the file lists these
  // areas with nothing in them, so a restore empties what you have now.
  if (p.emptying && p.emptying.length) {
    html += `<div class="restore-warn">🚨 <b>${t('This backup would empty these areas')}</b> —
      ${t('it lists them with no records, so what you have now is removed and nothing is put back:')}
      <div class="restore-list" style="margin-top:8px">${
        p.emptying.map(e => `<div class="restore-row"><span>${escHtml(e.label)}</span>
          <b>${tformat('%1 removed', e.current)}</b></div>`).join('')}</div></div>`;
  }

  html += `<div class="restore-warn">⚠️ ${t('This <b>replaces</b> your current data in every area listed below — your existing records there are removed first. This cannot be undone, so download a backup now if you are unsure.')}</div>`;

  if (p.tables && p.tables.length) {
    html += `<div class="restore-list">${p.tables.map(_restoreRow).join('')}</div>
      <div class="restore-note">${tformat('%1 to restore, replacing %2 of yours.',
        _nRecords(T.incoming || 0), _nRecords(T.deleting || 0))}</div>`;
  } else {
    html += `<div class="restore-warn">${t('No restorable health records were found in that file.')}</div>`;
    _restoreData = null;
    el.innerHTML = html;
    return;
  }

  if (T.unreadable) {
    html += `<div class="restore-note">${tformat('%1 in the file could not be read and will be skipped.', _nRows(T.unreadable))}</div>`;
  }
  if (p.untouched && p.untouched.length) {
    html += `<details class="restore-details"><summary>${
      tformat('%1 areas are not in this file and will be left alone', p.untouched.length)
      }</summary><div class="restore-list">${p.untouched.map(e =>
        `<div class="restore-row"><span>${escHtml(e.label)}</span><b>${
          tformat('%1 kept', e.current)}</b></div>`).join('')}</div></details>`;
  }
  if (p.not_restored && p.not_restored.length) {
    html += `<details class="restore-details"><summary>${
      t('Some things in this file are deliberately not restored')
      }</summary>${p.not_restored.map(e =>
        `<div class="restore-note"><b>${escHtml(e.label)}</b> — ${escHtml(e.reason)}</div>`).join('')}</details>`;
  }
  html += `<button class="btn-primary" style="margin-top:12px" data-ev-click="confirmRestore()">${
    t('Replace my data with this backup')}</button>`;
  el.innerHTML = html;
}

async function confirmRestore() {
  if (!_restoreData) return;
  showToast(t('Restoring…'), 'info');
  const r = await fetch('/api/import', {
    method: 'POST', credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify(_restoreData),
  }).then(r => r.json()).catch(() => null);
  if (r && r.success) {
    _restoreData = null;
    // Never report a clean restore when rows were dropped — "✓ Restored 3,100"
    // while 900 silently failed tells someone their history is back when it
    // isn't, and they'd have no reason to check.
    if (r.skipped_total) {
      showToast(tformat('Restored %1 records — %2 could not be read and were skipped',
                        r.total, r.skipped_total), 'warn');
    } else {
      showToast(tformat('✓ Restored %1 records — reloading', r.total), 'success');
    }
    setTimeout(() => location.reload(), r.skipped_total ? 3500 : 1000);
  } else {
    showToast((r && r.error) || t('Restore failed'), 'error');
  }
}

function openDeleteAccount() {
  const panel = document.getElementById('delete-account-panel');
  if (!panel) return;
  // Reveal a password confirm inline — deletion is irreversible, so require the
  // password and an explicit second click.
  panel.innerHTML = `
    <h2 class="panel-title" style="margin-bottom:6px;color:#B91C1C">Delete my account</h2>
    <p style="font-size:13px;color:var(--gray-400);margin-bottom:12px">
      This permanently erases your account and every record. Enter your password to confirm.</p>
    <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">
      <input type="password" class="form-input" id="delete-account-pw" placeholder="Your password"
             aria-label="Confirm password" style="max-width:220px" autocomplete="current-password">
      <button class="btn-outline" data-ev-click="resetDeleteAccount()">${t('Cancel')}</button>
      <button class="btn-outline" style="color:#fff;background:#B91C1C;border-color:#B91C1C"
              data-ev-click="confirmDeleteAccount()">${t('Permanently delete')}</button>
    </div>`;
}

function resetDeleteAccount() {
  const panel = document.getElementById('delete-account-panel');
  if (!panel) return;
  panel.innerHTML = `
    <h2 class="panel-title" style="margin-bottom:4px;color:#B91C1C">Delete my account</h2>
    <p style="font-size:13px;color:var(--gray-400);margin-bottom:12px">
      Permanently deletes your account and <b>all</b> your data — medicines, logs,
      family links, everything. This cannot be undone. Consider downloading your data first.</p>
    <button class="btn-outline" style="color:#B91C1C;border-color:#e7a3a3"
            data-ev-click="openDeleteAccount()">Delete account…</button>`;
}

async function confirmDeleteAccount() {
  const pw = document.getElementById('delete-account-pw')?.value || '';
  if (!pw) { showToast('Enter your password to confirm', 'error'); return; }
  const r = await fetch('/api/account', {
    method: 'DELETE', headers: {'Content-Type': 'application/json'},
    credentials: 'same-origin', body: JSON.stringify({password: pw}),
  });
  const d = await r.json().catch(() => ({}));
  if (!r.ok) { showToast(d.error || 'Could not delete account', 'error'); return; }
  // Account and session are gone — send them back to the sign-in screen.
  showToast('Your account and data have been deleted', 'success');
  setTimeout(() => { window.location.href = '/'; }, 1200);
}

// ════════════════════════════════════════════════════════════════
// DAILY CHECK-IN
// Shown once per day on first dashboard open.
// Writes to: /api/thoughts (mood), /api/sleep, /api/symptoms,
//            /api/hydration  — all existing endpoints.
// Completion stored in localStorage so it shows once per day.
// ════════════════════════════════════════════════════════════════

const CI_STEPS  = ['mood', 'sleep', 'symptoms', 'water'];
let   ciStep    = 0;
const ciSel     = { mood: null, sleep: null, symptoms: [], water: null };

// Emoji come from MOOD_EMOJI, not a second hardcoded copy — the two drifted
// (the check-in showed 😕 for `sad` where the journal showed 😞, for the same
// stored value).
const CI_MOODS = [
  { label: 'Rough', mood: 'terrible' },
  { label: 'Low',   mood: 'sad'      },
  { label: 'Okay',  mood: 'neutral'  },
  { label: 'Good',  mood: 'happy'    },
  { label: 'Great', mood: 'excited'  },
].map(m => ({ ...m, emoji: MOOD_EMOJI[m.mood] }));
const CI_SLEEP = [
  { label: 'Under 5h', sub: 'Very short',    dur: 4,   quality: 1 },
  { label: '5 – 6h',   sub: 'A bit short',   dur: 5.5, quality: 2 },
  { label: '6 – 7h',   sub: 'Nearly enough', dur: 6.5, quality: 3 },
  { label: '7 – 9h',   sub: 'Just right',    dur: 8,   quality: 5 },
  { label: '9h+',      sub: 'Long sleep',    dur: 9.5, quality: 3 },
  { label: 'No sleep', sub: '—',             dur: 0,   quality: 1 },
];
const CI_SYMPTOMS = [
  'Headache', 'Fatigue', 'Nausea', 'Back pain',
  'Anxiety',  'Sore throat', 'Stomach ache', 'Dizziness',
  'Fever', 'Cold / runny nose',
];
const CI_WATER = [
  { label: '250ml', ml: 250  },
  { label: '500ml', ml: 500  },
  { label: '750ml', ml: 750  },
  { label: '1L+',   ml: 1000 },
];

// ── Trigger: call from loadDashboard ─────────────────────────────
async function initDailyCheckin() {
  const today     = localToday();
  const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];
  const key       = `medeasy_checkin_${today}`;
  if (localStorage.getItem(key)) return;  // already done today

  // Check what's already been logged so we don't ask twice
  const [sleepLogs, thoughts, hydration] = await Promise.all([
    fetch('/api/sleep?days=2').then(r => r.json()).catch(() => []),
    fetch(`/api/thoughts/${today}`).then(r => r.json()).catch(() => []),
    coalescedGet(`/api/hydration/${today}`, {cache: 'no-store'}).catch(() => null),
  ]);

  // Sleep: skip if logged for today or yesterday
  const hasSleep = Array.isArray(sleepLogs) &&
    sleepLogs.some(s => s.date_key === today || s.date_key === yesterday);

  // Mood: skip if thought/mood logged today
  const hasMood = Array.isArray(thoughts) && thoughts.length > 0;

  // Hydration: skip if already has meaningful water logged
  const hasHydration = hydration && (hydration.total_ml || 0) >= 250;

  // Build the steps to show — skip already-logged ones
  const stepsToShow = [];
  if (!hasMood)      stepsToShow.push('mood');
  if (!hasSleep)     stepsToShow.push('sleep');
                     stepsToShow.push('symptoms');  // always ask about symptoms
  if (!hasHydration) stepsToShow.push('water');

  // If everything is already logged, just mark done and skip
  if (stepsToShow.length <= 1 && stepsToShow[0] === 'symptoms') {
    localStorage.setItem(key, '1');
    return;
  }

  // Respect a "not now" snooze for today
  if (localStorage.getItem(`medeasy_checkin_snooze_${today}`)) return;

  // Show only the relevant steps
  window._ciStepsToShow = stepsToShow;

  // Surface an inline, dismissible nudge instead of interrupting with a modal
  // over the dashboard's next-action hero — the user chooses when to start.
  const prompt = document.getElementById('dash-checkin-prompt');
  if (!prompt) return;
  const labels = { mood:'mood', sleep:'sleep', symptoms:'symptoms', water:'water' };
  // Translated here rather than in the map: the map's values are also the step
  // keys' English names, and translating at the definition would freeze them to
  // whatever language was active when the file loaded.
  const parts  = stepsToShow.map(s => labels[s]).filter(Boolean).map(t);
  prompt.innerHTML = `
    <div class="checkin-prompt-icon">☀️</div>
    <div class="checkin-prompt-body">
      <div class="checkin-prompt-title">${t('Daily check-in')}</div>
      <div class="checkin-prompt-sub">${tformat('A quick 30 seconds — %1.', parts.join(', '))}</div>
    </div>
    <button class="checkin-prompt-start" data-ev-click="startDailyCheckin()">${t('Start')}</button>
    <button class="checkin-prompt-dismiss" data-ev-click="dismissCheckinPrompt()" title="${escHtml(t('Not now'))}" aria-label="${escHtml(t('Dismiss'))}">✕</button>`;
  prompt.style.display = 'flex';
}

function startDailyCheckin() {
  const prompt = document.getElementById('dash-checkin-prompt');
  if (prompt) prompt.style.display = 'none';
  ciStep = 0;
  ciSel.mood = null; ciSel.sleep = null; ciSel.symptoms = []; ciSel.water = null; ciSel.note = '';
  renderCheckin();
  document.getElementById('checkin-overlay').style.display = 'flex';
}

function dismissCheckinPrompt() {
  const prompt = document.getElementById('dash-checkin-prompt');
  if (prompt) prompt.style.display = 'none';
  // Snooze for the rest of today only — it returns tomorrow
  localStorage.setItem(`medeasy_checkin_snooze_${localToday()}`, '1');
}

function closeCheckin() {
  document.getElementById('checkin-overlay').style.display = 'none';
}

// ── Renderer ──────────────────────────────────────────────────────
function renderCheckin() {
  // Use only the steps that haven't been logged yet
  const steps = window._ciStepsToShow || CI_STEPS;
  const currentStepName = steps[ciStep];
  const totalSteps = steps.length;

  // Dots
  const dotsEl = document.getElementById('checkin-dots');
  if (dotsEl) {
    dotsEl.innerHTML = steps.map((_, i) => {
      let cls = 'ci-dot';
      if (i < ciStep)        cls += ' done';
      else if (i === ciStep) cls += ' active';
      return `<div class="${cls}"></div>`;
    }).join('');
  }

  // Progress bar
  const prog = document.getElementById('checkin-progress');
  if (prog) prog.style.width = ((ciStep + 1) / totalSteps * 100) + '%';

  const body   = document.getElementById('checkin-body');
  const footer = document.getElementById('checkin-footer');
  if (!body || !footer) return;

  const stepNum = ciStep + 1;
  // The whole label is one translatable phrase, not "Step" + numbers + a name
  // glued together — a language that counts differently ("4 में से 1") cannot
  // be built out of English fragments joined in English order.
  const stepLabel = name => tformat('Step %1 of %2 · %3', stepNum, totalSteps, name);

  // ── Step: Mood ──────────────────────────────────────────────
  if (currentStepName === 'mood') {
    body.innerHTML = `
      <div class="ci-step-label">${stepLabel(t('How you feel'))}</div>
      <div class="ci-question">${t('Good morning! How are you feeling?')}</div>
      <div class="ci-mood-grid">
        ${CI_MOODS.map((m, i) => `
          <button class="ci-mood-btn${ciSel.mood === i ? ' active' : ''}"
                  data-ev-click="ciPickMood(${i})">
            <span class="ci-mood-emoji">${m.emoji}</span>
            <span class="ci-mood-label">${t(m.label)}</span>
          </button>`).join('')}
      </div>
      ${ciSel.mood !== null ? `
        <textarea class="ci-note" rows="2" maxlength="500"
                  placeholder="${escHtml(t('Anything on your mind? Adds a note to your journal (optional)…'))}"
                  data-ev-input="ciSetNote(this.value)">${escHtml(ciSel.note || '')}</textarea>` : ''}`;
    footer.innerHTML = `
      <button class="ci-btn-primary" data-ev-click="ciNext()"
              ${ciSel.mood === null ? 'disabled' : ''}>${t('Continue')}</button>`;
  }

  // ── Step: Sleep ─────────────────────────────────────────────
  else if (currentStepName === 'sleep') {
    body.innerHTML = `
      <div class="ci-step-label">${stepLabel(t('Sleep'))}</div>
      <div class="ci-question">${t('How much did you sleep last night?')}</div>
      <div class="ci-sleep-grid">
        ${CI_SLEEP.map((s, i) => `
          <button class="ci-sleep-btn${ciSel.sleep === i ? ' active' : ''}"
                  data-ev-click="ciPickSleep(${i})">
            <div class="ci-sleep-dur">${t(s.label)}</div>
            <div class="ci-sleep-qual">${t(s.sub)}</div>
          </button>`).join('')}
      </div>`;
    footer.innerHTML = `
      <button class="ci-btn-secondary" data-ev-click="ciBack()">${t('Back')}</button>
      <button class="ci-btn-primary" data-ev-click="ciNext()"
              ${ciSel.sleep === null ? 'disabled' : ''}>${t('Continue')}</button>`;
  }

  // ── Step: Symptoms ──────────────────────────────────────────
  else if (currentStepName === 'symptoms') {
    body.innerHTML = `
      <div class="ci-step-label">${stepLabel(t('Symptoms'))}</div>
      <div class="ci-question">${t('Any symptoms today?')}</div>
      <div class="ci-sym-list">
        <button class="ci-none-btn${ciSel.symptoms.length === 0 ? ' active' : ''}"
                data-ev-click="ciClearSymptoms()">${t('None, feeling fine')}</button>
        ${CI_SYMPTOMS.map(s => `
          <button class="ci-sym-btn${ciSel.symptoms.includes(s) ? ' active' : ''}"
                  data-ev-click="ciToggleSymptom('${s}')">${t(s)}</button>`).join('')}
      </div>`;
    const isFirst = ciStep === 0;
    footer.innerHTML = `
      ${!isFirst ? `<button class="ci-btn-secondary" data-ev-click="ciBack()">${t('Back')}</button>` : ''}
      <button class="ci-btn-primary" data-ev-click="ciNext()">${t('Continue')}</button>`;
  }

  // ── Step: Hydration ─────────────────────────────────────────
  else if (currentStepName === 'water') {
    body.innerHTML = `
      <div class="ci-step-label">${stepLabel(t('Hydration'))}</div>
      <div class="ci-question">${t('How much have you had to drink so far?')}</div>
      <div class="ci-water-grid">
        ${CI_WATER.map((w, i) => `
          <button class="ci-water-btn${ciSel.water === i ? ' active' : ''}"
                  data-ev-click="ciPickWater(${i})">
            <div>${w.label}</div>
          </button>`).join('')}
      </div>`;
    footer.innerHTML = `
      <button class="ci-btn-secondary" data-ev-click="ciBack()">${t('Back')}</button>
      <button class="ci-btn-primary" data-ev-click="ciSubmit()">${t('Done')}</button>`;
  }
}

// ── Interaction handlers ──────────────────────────────────────────
function ciPickMood(i) {
  ciSel.mood = i;
  renderCheckin();
}
function ciSetNote(v) {
  // Store only — no re-render, so the textarea keeps focus while typing
  ciSel.note = v;
}
function ciPickSleep(i) {
  ciSel.sleep = i;
  renderCheckin();
}
function ciToggleSymptom(s) {
  const idx = ciSel.symptoms.indexOf(s);
  if (idx >= 0) ciSel.symptoms.splice(idx, 1);
  else          ciSel.symptoms.push(s);
  renderCheckin();
}
function ciClearSymptoms() {
  ciSel.symptoms = [];
  renderCheckin();
}
function ciPickWater(i) {
  ciSel.water = i;
  renderCheckin();
}
function ciNext() {
  const steps = window._ciStepsToShow || CI_STEPS;
  ciStep++;
  // If we've gone past the last step, submit
  if (ciStep >= steps.length) {
    ciSubmit();
  } else {
    renderCheckin();
  }
}
function ciBack() {
  if (ciStep > 0) { ciStep--; renderCheckin(); }
}

// ── Submit: save to all relevant APIs ────────────────────────────
async function ciSubmit() {
  const today     = localToday();
  const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];
  const saves     = [];

  // 1. Mood → save as a journal thought. If the user wrote a reflection note,
  //    that becomes the journal entry (the check-in doubles as the journal).
  if (ciSel.mood !== null) {
    const m    = CI_MOODS[ciSel.mood];
    const note = (ciSel.note || '').trim();
    const content = note
      ? `${note}\n\n(Check-in: feeling ${m.label.toLowerCase()})`
      : `Daily check-in: feeling ${m.label.toLowerCase()}.`;
    saves.push(fetch('/api/thoughts', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ content, mood: m.mood, date_key: today })
    }).catch(() => {}));
  }

  // 2. Sleep → derive bedtime/wake from duration
  if (ciSel.sleep !== null) {
    const s   = CI_SLEEP[ciSel.sleep];
    const dur = s.dur;
    if (dur > 0) {
      // Assume woke up now, went to bed dur hours ago
      const now      = new Date();
      const wake     = now.toISOString().slice(0, 16);
      const bedDate  = new Date(now - dur * 3600000);
      const bedtime  = bedDate.toISOString().slice(0, 16);
      saves.push(fetch('/api/sleep', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          bedtime, wake_time: wake,
          quality:  s.quality,
          notes:    'Logged via daily check-in',
          date_key: yesterday,   // sleep was last night
        })
      }).catch(() => {}));
    }
  }

  // 3. Symptoms
  ciSel.symptoms.forEach(sym => {
    saves.push(fetch('/api/symptoms', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name:        sym,
        severity:    5,
        date_key:    today,
        time_of_day: 'morning',
        notes:       'Logged via daily check-in',
      })
    }).catch(() => {}));
  });

  // 4. Hydration
  if (ciSel.water !== null) {
    const w = CI_WATER[ciSel.water];
    saves.push(fetch('/api/hydration', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ amount_ml: w.ml, drink_type: 'water', date_key: today })
    }).catch(() => {}));
  }

  await Promise.all(saves);

  // Mark today's check-in done
  localStorage.setItem(`medeasy_checkin_${today}`, '1');

  // Show thank-you summary, then auto-close after 2.5s
  ciShowSummary();

  // Refresh dashboard strip so hydration shows updated
  loadWellnessStrip();
}

// ── Summary screen ────────────────────────────────────────────────
function ciShowSummary() {
  const body   = document.getElementById('checkin-body');
  const footer = document.getElementById('checkin-footer');
  const prog   = document.getElementById('checkin-progress');
  const dots   = document.getElementById('checkin-dots');
  if (prog) prog.style.width = '100%';
  if (dots) dots.innerHTML = CI_STEPS.map(() => '<div class="ci-dot done"></div>').join('');

  const moodObj  = ciSel.mood  !== null ? CI_MOODS[ciSel.mood]  : null;
  const sleepObj = ciSel.sleep !== null ? CI_SLEEP[ciSel.sleep] : null;
  const waterObj = ciSel.water !== null ? CI_WATER[ciSel.water] : null;
  const symText  = ciSel.symptoms.length
    ? ciSel.symptoms.slice(0, 2).map(t).join(', ') + (ciSel.symptoms.length > 2 ? ` +${ciSel.symptoms.length - 2}` : '')
    : t('None');

  body.innerHTML = `
    <div class="ci-step-label" style="color:var(--teal-600)">${t('All done')}</div>
    <div class="ci-question" style="font-size:17px;margin-bottom:18px">${t('Good start to the day!')}</div>
    <div class="ci-summary-grid">
      <div class="ci-sum-card">
        <div class="ci-sum-val">${moodObj ? moodObj.emoji + ' ' + t(moodObj.label) : '—'}</div>
        <div class="ci-sum-lab">${t('Mood')}</div>
      </div>
      <div class="ci-sum-card">
        <div class="ci-sum-val">${sleepObj ? t(sleepObj.label) : '—'}</div>
        <div class="ci-sum-lab">${t('Sleep')}</div>
      </div>
      <div class="ci-sum-card">
        <div class="ci-sum-val" style="font-size:13px">${symText}</div>
        <div class="ci-sum-lab">${t('Symptoms')}</div>
      </div>
      <div class="ci-sum-card">
        <div class="ci-sum-val">${waterObj ? t(waterObj.label) : '—'}</div>
        <div class="ci-sum-lab">${t('Hydration')}</div>
      </div>
    </div>`;

  footer.innerHTML = `
    <button class="ci-btn-primary" data-ev-click="closeCheckin()">${t('Go to dashboard')}</button>`;

  setTimeout(closeCheckin, 3000);
}


// ════════════════════════════════════════════════════════════════
// VITAL TRENDS — 30-day charts using Chart.js
// ════════════════════════════════════════════════════════════════

const VITAL_META = {
  blood_pressure: {
    label: 'Blood pressure',
    unit:  'mmHg',
    color: { sys: '#4F8D74', dia: '#5DCAA5' },
    refLines: [
      { value: 120, label: 'Sys goal', color: '#4F8D74', dash: [4,3] },
      { value: 80,  label: 'Dia goal', color: '#5DCAA5', dash: [4,3] },
      { value: 140, label: 'Sys high', color: '#EF4444', dash: [6,3] },
    ],
    yMin: 40, yMax: 180,
    twoValues: true,
  },
  heart_rate: {
    label: 'Heart rate',
    unit:  'bpm',
    color: { main: '#E85D24' },
    refLines: [
      { value: 60,  label: 'Low',    color: '#3B82F6', dash: [4,3] },
      { value: 100, label: 'High',   color: '#EF4444', dash: [4,3] },
    ],
    yMin: 40, yMax: 160,
    twoValues: false,
  },
  blood_sugar: {
    label: 'Blood sugar',
    unit:  'mg/dL',
    color: { main: '#BA7517' },
    refLines: [
      { value: 70,  label: 'Low',    color: '#3B82F6', dash: [4,3] },
      { value: 99,  label: 'Normal', color: '#22C55E', dash: [4,3] },
      { value: 125, label: 'Pre-diabetic', color: '#F59E0B', dash: [4,3] },
    ],
    yMin: 50, yMax: 200,
    twoValues: false,
  },
  spo2: {
    label: 'SpO\u2082',
    unit:  '%',
    color: { main: '#5E8299' },
    refLines: [
      { value: 95, label: 'Min normal', color: '#EF4444', dash: [4,3] },
    ],
    yMin: 85, yMax: 102,
    twoValues: false,
  },
  temperature: {
    label: 'Temperature',
    unit:  '\u00b0C',
    color: { main: '#D85A30' },
    refLines: [
      { value: 37.2, label: 'Fever threshold', color: '#EF4444', dash: [4,3] },
    ],
    yMin: 35, yMax: 40,
    twoValues: false,
  },
};

// Chart.js instance cache so we can destroy before re-render
const _vitalCharts = {};

let _vitalTrendDays = 30;

async function loadVitalTrends(days) {
  if (days) _vitalTrendDays = days;
  const d = _vitalTrendDays;

  const section = document.getElementById('bv-trend-section');
  if (!section) return;

  section.innerHTML = '<div style="color:var(--gray-400);font-size:13px;padding:20px 0;text-align:center">Loading trend charts…</div>';

  if (!window.Chart) {
    await new Promise((res, rej) => {
      const s = document.createElement('script');
      s.src = 'https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js';
      s.onload = res; s.onerror = rej;
      document.head.appendChild(s);
    });
  }

  const data = await fetch(`/api/vitals/trend?days=${d}`, { cache: 'no-store' })
    .then(r => r.json()).catch(() => null);

  if (!data) {
    section.innerHTML = '<div style="color:var(--gray-400);font-size:13px;padding:20px 0;text-align:center">Could not load trend data</div>';
    return;
  }

  const groups  = data.groups || {};
  const hasData = Object.keys(groups).some(k => groups[k].length > 0);

  const toggleHTML = `
    <div class="trend-toggle">
      <button class="trend-toggle-btn${d===7?' active':''}"  data-ev-click="loadVitalTrends(7)">${t('Weekly')}</button>
      <button class="trend-toggle-btn${d===30?' active':''}" data-ev-click="loadVitalTrends(30)">${t('Monthly')}</button>
      <button class="trend-toggle-btn${d===90?' active':''}" data-ev-click="loadVitalTrends(90)">3 months</button>
    </div>`;

  if (!hasData) {
    section.innerHTML = `
      <div class="panel" style="padding:20px 22px">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px">
          <span style="font-size:14px;font-weight:600;color:var(--gray-700)">Vital trends</span>
          ${toggleHTML}
        </div>
        <div style="text-align:center;padding:20px 0">
          <div style="font-size:14px;font-weight:600;color:var(--gray-700);margin-bottom:6px">No vitals logged yet</div>
          <div style="font-size:13px;color:var(--gray-400)">Log your first vital above — charts appear once you have data.</div>
        </div>
      </div>`;
    return;
  }

  const CHART_ORDER = ['blood_pressure','heart_rate','blood_sugar','spo2','temperature'];
  const chartsHTML  = CHART_ORDER
    .filter(t => groups[t] && groups[t].length >= 1)
    .map(t => {
      const meta    = VITAL_META[t];
      const entries = groups[t];
      const latest  = entries[entries.length - 1];
      const latestVal = latest.value2
        ? `${latest.value1}/${latest.value2}`
        : latest.value1;
      const periodLabel = d === 7 ? 'this week' : d === 30 ? 'this month' : 'last 3 months';
      return `
        <div class="panel" style="padding:16px 20px 20px">
          <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:4px">
            <h2 class="panel-title">${meta.label}</h2>
            <span class="panel-badge">${latestVal} ${meta.unit}</span>
          </div>
          <div style="font-size:11.5px;color:var(--gray-400);margin-bottom:12px">
            ${entries.length} reading${entries.length !== 1 ? 's' : ''} ${periodLabel}
          </div>
          <div style="position:relative;height:160px">
            <canvas id="vchart-${t}"></canvas>
          </div>
          <div id="vref-${t}" style="display:flex;flex-wrap:wrap;gap:12px;margin-top:10px;font-size:11px;color:var(--gray-500)"></div>
        </div>`;
    }).join('');

  section.innerHTML = `
    <div style="display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:12px">
      <span style="font-size:13px;font-weight:600;color:var(--gray-700)">Vital trends</span>
      ${toggleHTML}
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:18px">${chartsHTML}</div>`;

  requestAnimationFrame(() => {
    CHART_ORDER.filter(t => groups[t] && groups[t].length >= 1).forEach(t => {
      renderVitalChart(t, groups[t], VITAL_META[t]);
    });
  });
}

// Re-express a vital's chart config in the user's unit. The stored values are
// canonical, so the axis bounds, reference lines and unit label must all be
// converted together — converting only the label is how a chart ends up
// contradicting its own data.
function _metaInUserUnit(type, meta) {
  const conv = type === 'blood_sugar' && _userUnits.glucose === 'mmol' ? (v => mgdlToMmol(v))
             : type === 'weight' && _userUnits.weight === 'lb' ? (v => kgToLb(v))
             : null;
  if (!conv) return meta;
  return Object.assign({}, meta, {
    unit: vitalUnitLabel(type),
    yMin: Math.floor(conv(meta.yMin)),
    yMax: Math.ceil(conv(meta.yMax)),
    refLines: (meta.refLines || []).map(r => Object.assign({}, r, { value: conv(r.value) })),
  });
}

function renderVitalChart(type, entries, meta) {
  const canvas = document.getElementById('vchart-' + type);
  if (!canvas) return;
  meta = _metaInUserUnit(type, meta);
  // Convert the series to match the (now converted) axis.
  if (type === 'blood_sugar' && _userUnits.glucose === 'mmol') {
    entries = entries.map(e => Object.assign({}, e, {
      value1: e.value1 != null ? mgdlToMmol(e.value1) : e.value1,
    }));
  }

  // Destroy previous instance if exists
  if (_vitalCharts[type]) {
    _vitalCharts[type].destroy();
    delete _vitalCharts[type];
  }

  const labels = entries.map(e => {
    const d = new Date(e.date);
    return (d.getMonth() + 1) + '/' + d.getDate();
  });

  const isDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
  const gridColor  = isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)';
  const tickColor  = isDark ? '#888780'                : '#888780';

  // Build datasets
  const datasets = [];
  if (meta.twoValues) {
    // Blood pressure: two lines
    datasets.push({
      label:           'Systolic',
      data:            entries.map(e => e.value1),
      borderColor:     meta.color.sys,
      backgroundColor: meta.color.sys + '20',
      borderWidth:     2,
      pointRadius:     entries.length > 15 ? 2 : 3.5,
      pointHoverRadius:5,
      tension:         0.35,
      fill:            false,
    });
    datasets.push({
      label:           'Diastolic',
      data:            entries.map(e => e.value2),
      borderColor:     meta.color.dia,
      backgroundColor: meta.color.dia + '20',
      borderWidth:     2,
      pointRadius:     entries.length > 15 ? 2 : 3.5,
      pointHoverRadius:5,
      tension:         0.35,
      fill:            false,
    });
  } else {
    datasets.push({
      label:           meta.label,
      data:            entries.map(e => e.value1),
      borderColor:     meta.color.main,
      backgroundColor: meta.color.main + '18',
      borderWidth:     2,
      pointRadius:     entries.length > 15 ? 2 : 3.5,
      pointHoverRadius:5,
      tension:         0.35,
      fill:            true,
    });
  }

  // Reference line annotations as extra datasets (dashed)
  meta.refLines.forEach(ref => {
    datasets.push({
      label:       ref.label,
      data:        entries.map(() => ref.value),
      borderColor: ref.color,
      borderWidth: 1,
      borderDash:  ref.dash,
      pointRadius: 0,
      pointHoverRadius: 0,
      fill:        false,
    });
  });

  _vitalCharts[type] = new window.Chart(canvas, {
    type: 'line',
    data: { labels, datasets },
    options: {
      responsive:          true,
      maintainAspectRatio: false,
      interaction:         { mode: 'index', intersect: false },
      plugins: {
        legend: {
          display:  meta.twoValues || meta.refLines.length > 0,
          position: 'bottom',
          labels:   { boxWidth: 10, boxHeight: 2, font: { size: 11 }, color: tickColor, padding: 10 },
        },
        tooltip: {
          callbacks: {
            label: ctx => {
              if (ctx.dataset.pointRadius === 0) return null; // skip ref lines in tooltip
              if (ctx.parsed.y == null) return 'Not logged';
              return ' ' + ctx.dataset.label + ': ' + ctx.parsed.y + ' ' + meta.unit;
            },
          },
        },
      },
      scales: {
        x: {
          grid:   { color: gridColor },
          ticks:  { color: tickColor, font: { size: 10 }, maxTicksLimit: 8 },
          border: { display: false },
        },
        y: {
          min:    meta.yMin,
          max:    meta.yMax,
          grid:   { color: gridColor },
          ticks:  { color: tickColor, font: { size: 10 }, maxTicksLimit: 5 },
          border: { display: false },
        },
      },
    },
  });

  // Render ref line legend
  const refLegend = document.getElementById('vref-' + type);
  if (refLegend && meta.refLines.length) {
    refLegend.innerHTML = meta.refLines.map(r =>
      `<span style="display:flex;align-items:center;gap:4px">
         <span style="width:18px;height:2px;background:${r.color};display:inline-block;border-radius:1px"></span>
         ${r.label}
       </span>`
    ).join('');
  }
}

// After saving a vital, reload both the list AND the trend chart
const _origSaveVitalFromView = saveVitalFromView;
saveVitalFromView = async function() {
  await _origSaveVitalFromView.apply(this, arguments);
  setTimeout(loadVitalTrends, 400);  // preserves _vitalTrendDays
};


// ════════════════════════════════════════════════════════════════
// SYMPTOM PATTERN DETECTOR
// ════════════════════════════════════════════════════════════════

// ── Symptom ↔ medicine timeline (coincidence in time, not cause) ──
async function loadSymptomTimeline() {
  const panel = document.getElementById('symptom-timeline-panel');
  if (!panel) return;
  const d = await fetch('/api/symptoms/timeline?days=90', {cache:'no-store'})
    .then(r => r.json()).catch(() => null);
  panel.innerHTML = d ? renderSymptomTimeline(d) : '';
}

function renderSymptomTimeline(d) {
  const esc = escHtml;
  if (!d.has_data) return '';                      // nothing to correlate yet
  const from = new Date(d.range.from + 'T12:00:00').getTime();
  const to   = new Date(d.range.to   + 'T12:00:00').getTime();
  const span = Math.max(1, to - from);
  const pct  = iso => {
    const t = new Date(iso + 'T12:00:00').getTime();
    return Math.min(100, Math.max(0, ((t - from) / span) * 100));
  };
  const sevColor = s => s>=8?'#EF4444':s>=5?'#F59E0B':'#22C55E';
  const fmt = iso => { try { return new Date(iso+'T12:00:00').toLocaleDateString(_locale(),{month:'short',day:'numeric'}); } catch(e){ return iso; } };

  const started = d.meds.filter(m => m.started_in_window);
  const ongoing = d.meds.filter(m => !m.started_in_window);

  // Medicine-start flags along the top of the band. Stagger them into three
  // tiers so flags that start on the same or nearby days don't overlap into an
  // unreadable pile (a doctor often starts several meds at once).
  const medFlags = started.map((m, i) => `
    <div class="stl-med" style="left:${pct(m.start_date)}%" title="${esc(m.name)} started ${esc(fmt(m.start_date))}${m.purpose ? ' · '+esc(m.purpose) : ''}">
      <div class="stl-med-line"></div>
      <div class="stl-med-flag" style="top:${(i % 3) * 22}px">${esc(m.icon)} ${esc(m.name)}</div>
    </div>`).join('');

  // Real change events (stopped / deleted) as distinct flags near the axis.
  const changeFlags = (d.changes || []).map((c, i) => `
    <div class="stl-med stl-med--stop" style="left:${pct(c.date)}%" title="${esc(c.name)} ${esc(c.kind)} ${esc(fmt(c.date))}">
      <div class="stl-med-line stl-med-line--stop"></div>
      <div class="stl-med-flag stl-med-flag--stop" style="top:${(i % 2) * 22}px">⏹ ${esc(c.name)}</div>
    </div>`).join('');

  // Symptom dots on the baseline, coloured by severity.
  const symDots = d.symptoms.map(s => `
    <div class="stl-sym" style="left:${pct(s.date)}%;background:${sevColor(s.severity||0)}"
         title="${esc(s.name)} · ${s.severity||'?'}/10 · ${esc(fmt(s.date))}"></div>`).join('');

  const ongoingChips = ongoing.length
    ? `<div class="stl-ongoing">Already taking: ${ongoing.map(m => `<span class="stl-chip">${esc(m.icon)} ${esc(m.name)}</span>`).join('')}</div>`
    : '';

  return `<div class="panel">
    <div class="panel-header">
      <h2 class="panel-title">🕗 Symptoms &amp; medicine changes</h2>
      <span class="panel-badge">Last ${d.range.days} days</span>
    </div>
    <div style="padding:14px 16px">
      ${ongoingChips}
      <div class="stl-band">
        ${medFlags}
        ${changeFlags}
        <div class="stl-axis"></div>
        <div class="stl-dots">${symDots}</div>
      </div>
      <div class="stl-axis-labels"><span>${esc(fmt(d.range.from))}</span><span>Today</span></div>
      <p class="stl-caveat">Dots are symptoms (colour = severity); flags mark when a medicine started.
        This only shows what lined up <em>in time</em> — it isn't proof one caused the other.
        If something looks connected, it's worth a word with your doctor.</p>
    </div>
  </div>`;
}

// Cross-factor correlations: honest "pattern, not proven cause" cards linking a
// symptom to short sleep, a medicine's start, or the menstrual cycle.
function renderSymptomCorrelations(corr) {
  if (!corr || !Array.isArray(corr.findings) || !corr.findings.length) return '';
  const card = (icon, text) =>
    `<div class="spp-corr-card"><span class="spp-corr-icon">${icon}</span><span>${text}</span></div>`;
  const cards = corr.findings.map(f => {
    if (f.type === 'sleep') {
      return card('😴', tformat('On days you logged <b>%1</b>, you’d slept about <b>%2 h</b> — vs %3 h on other days.',
        escHtml(f.symptom), f.symptom_avg, f.other_avg));
    }
    if (f.type === 'med_start') {
      return card('💊', tformat('<b>%1</b> first appeared %2 after you started <b>%3</b> — worth mentioning to your doctor.',
        escHtml(f.symptom), f.days_after === 0 ? t('the same day') : tformat('%1 days', f.days_after), escHtml(f.medicine)));
    }
    if (f.type === 'cycle') {
      const phase = f.phase === 'period' ? t('during your period') : t('in the days before your period');
      return card('🩸', tformat('<b>%1</b> mostly showed up %2 (%3 of %4 times).',
        escHtml(f.symptom), phase, f.count, f.total));
    }
    return '';
  }).join('');
  return `<div class="panel spp-corr" style="padding:16px 20px;margin-top:18px">
      <div class="panel-header" style="margin-bottom:6px">
        <h2 class="panel-title">${t('Patterns worth noticing')}</h2>
        <span class="panel-badge">${tformat('%1 days', corr.days)}</span>
      </div>
      <p class="spp-corr-note">${t('These are patterns in your own logs, not proven causes.')}</p>
      ${cards}
    </div>`;
}

// Symptom before/after a medicine change — an observation, never a cause.
async function loadSymptomMedEffect() {
  const el = document.getElementById('symptom-med-effect-panel');
  if (!el) return;
  const d = await fetch('/api/symptoms/med-effect', { cache: 'no-store' }).then(r => r.json()).catch(() => null);
  if (!d || !d.has_data) { el.innerHTML = ''; return; }
  const DIR = {
    improved:     { icon: '📉', color: '#22C55E', word: 'less often' },
    worse:        { icon: '📈', color: '#EF4444', word: 'more often' },
    little_change:{ icon: '→',  color: 'var(--gray-400)', word: 'about the same' },
  };
  const rows = d.findings.map(f => {
    const m = DIR[f.direction] || DIR.little_change;
    const verb = f.event === 'started' ? t('Since starting %1') : t('Since stopping %1');
    const sev = (f.before_severity && f.after_severity)
      ? ` · ${tformat('severity %1 → %2', f.before_severity, f.after_severity)}` : '';
    return `<div class="sme-row">
      <span class="sme-icon" style="color:${m.color}">${m.icon}</span>
      <div class="sme-body">
        <div class="sme-lead">${tformat(verb, escHtml(f.medicine))}, <b>${escHtml(f.symptom)}</b> ${t(m.word)}</div>
        <div class="sme-detail">${tformat('%1/wk → %2/wk', f.before_per_week, f.after_per_week)}${sev}</div>
      </div>
    </div>`;
  }).join('');
  el.innerHTML = `<div class="panel" style="padding:16px 18px;margin-top:16px">
      <div class="panel-header" style="padding:0 0 6px"><h2 class="panel-title">💊 ${t('Symptoms around a medicine change')}</h2></div>
      ${rows}
      <div class="sme-disc">${escHtml(d.note)}</div>
    </div>`;
}

async function loadSymptomPatterns() {
  loadSymptomMedEffect();
  const panel = document.getElementById('symptom-patterns-panel');
  if (!panel) return;

  const [data, corr] = await Promise.all([
    fetch('/api/symptoms/patterns?days=30', {cache:'no-store'}).then(r => r.json()).catch(() => null),
    fetch('/api/symptoms/correlations?days=60', {cache:'no-store'}).then(r => r.json()).catch(() => null),
  ]);

  if (!data || data.total_logs === 0) {
    panel.innerHTML = '';
    return;
  }

  const { symptoms, alerts, co_occur, heatmap } = data;
  if (!symptoms.length) { panel.innerHTML = ''; return; }

  // 'insufficient' (too few loggings to judge) shows no arrow at all — a blank
  // reads as "no trend yet", never a false ↑ worsening on a symptom.
  const TREND_ICON  = { worsening:'↑', improving:'↓', stable:'→', insufficient:'' };
  const TREND_COLOR = { worsening:'#EF4444', improving:'#22C55E', stable:'#888780', insufficient:'#888780' };
  const TIME_LABEL  = { morning:'morning', afternoon:'afternoon', evening:'evening',
                        night:'night', all_day:'all day' };
  const SEV_COLOR   = s => s >= 8 ? '#EF4444' : s >= 5 ? '#F59E0B' : '#22C55E';

  // ── Alerts banner ─────────────────────────────────────────────
  const alertsHTML = alerts.length ? `
    <div class="spp-alerts">
      <div class="spp-alerts-head">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
        Recurring this week
      </div>
      <div class="spp-alerts-list">
        ${alerts.map(a => `
          <div class="spp-alert-chip">
            <span class="spp-alert-name">${escHtml(a.name)}</span>
            <span class="spp-alert-count">${a.count}× · mostly ${TIME_LABEL[a.peak_time]}</span>
          </div>`).join('')}
      </div>
    </div>` : '';

  // ── Symptom frequency bars ────────────────────────────────────
  const maxCount = symptoms[0]?.count || 1;
  const freqRows = symptoms.slice(0, 8).map(s => `
    <div class="spp-freq-row">
      <div class="spp-freq-name">${escHtml(s.name)}</div>
      <div class="spp-freq-bar-wrap">
        <div class="spp-freq-bar" style="width:${Math.round(s.count/maxCount*100)}%;background:${SEV_COLOR(s.avg_severity)}"></div>
      </div>
      <div class="spp-freq-meta">
        <span>${s.count}×</span>
        <span style="color:${TREND_COLOR[s.trend] || '#888780'};font-weight:600">${TREND_ICON[s.trend] || ''}</span>
        <span style="color:var(--gray-400);font-size:11px">${TIME_LABEL[s.peak_time]}</span>
      </div>
    </div>`).join('');

  // ── Heatmap ───────────────────────────────────────────────────
  const heatDates    = heatmap.dates;
  const heatNames    = heatmap.names;
  const SHORT_DATES  = heatDates.map(d => {
    const dt = new Date(d + 'T12:00:00');
    return (dt.getMonth()+1) + '/' + dt.getDate();
  });

  const heatRows = heatNames.map(name => {
    const vals = heatmap.data[name] || [];
    const cells = vals.map((v, i) => {
      if (!v) return `<div class="spp-heat-cell spp-heat-0" title="${heatDates[i]}: none"></div>`;
      const bg = v >= 8 ? '#FCA5A5' : v >= 5 ? '#FCD34D' : '#86EFAC';
      return `<div class="spp-heat-cell" style="background:${bg}" title="${heatDates[i]}: severity ${v}"></div>`;
    }).join('');
    return `
      <div class="spp-heat-row">
        <div class="spp-heat-name">${escHtml(name)}</div>
        <div class="spp-heat-cells">${cells}</div>
      </div>`;
  }).join('');

  const heatLegend = `
    <div class="spp-heat-legend">
      <span class="spp-heat-leg-item"><span class="spp-heat-cell spp-heat-0" style="display:inline-block"></span> None</span>
      <span class="spp-heat-leg-item"><span class="spp-heat-cell" style="background:#86EFAC;display:inline-block"></span> Mild</span>
      <span class="spp-heat-leg-item"><span class="spp-heat-cell" style="background:#FCD34D;display:inline-block"></span> Moderate</span>
      <span class="spp-heat-leg-item"><span class="spp-heat-cell" style="background:#FCA5A5;display:inline-block"></span> Severe</span>
    </div>`;

  // ── Co-occurrence ─────────────────────────────────────────────
  const coHTML = co_occur.length ? `
    <div class="panel" style="padding:16px 20px">
      <div class="panel-header" style="margin-bottom:12px">
        <h2 class="panel-title">Often appear together</h2>
        <span class="panel-badge">30 days</span>
      </div>
      ${co_occur.map(pair => `
        <div class="spp-co-row">
          <span class="spp-co-name">${escHtml(pair.a)}</span>
          <span class="spp-co-plus">+</span>
          <span class="spp-co-name">${escHtml(pair.b)}</span>
          <span class="spp-co-count">${pair.count} days</span>
        </div>`).join('')}
    </div>` : '';

  // ── Cross-factor correlations (patterns, never causes) ────────
  const corrHTML = renderSymptomCorrelations(corr);

  panel.innerHTML = `
    ${alertsHTML}
    ${corrHTML}
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px">

      <!-- Frequency + trend -->
      <div class="panel" style="padding:16px 20px">
        <div class="panel-header" style="margin-bottom:14px">
          <h2 class="panel-title">Frequency (30 days)</h2>
        </div>
        <div class="spp-freq-legend" style="margin-bottom:10px">
          <span style="color:#22C55E">● mild</span>
          <span style="color:#F59E0B">● moderate</span>
          <span style="color:#EF4444">● severe</span>
          <span style="margin-left:8px;color:var(--gray-400);font-size:11px">↑ worsening  ↓ improving  → stable</span>
        </div>
        ${freqRows}
      </div>

      <!-- Heatmap + co-occurrence -->
      <div style="display:flex;flex-direction:column;gap:18px">
        <div class="panel" style="padding:16px 20px">
          <div class="panel-header" style="margin-bottom:12px">
            <h2 class="panel-title">14-day calendar</h2>
          </div>
          <div class="spp-heat-date-row">
            <div style="width:90px;flex-shrink:0"></div>
            ${SHORT_DATES.map(d => `<div class="spp-heat-date">${d}</div>`).join('')}
          </div>
          ${heatRows}
          ${heatLegend}
        </div>
        ${coHTML}
      </div>
    </div>`;
}


// ════════════════════════════════════════════════════════════════
// SLEEP TREND CHART
// ════════════════════════════════════════════════════════════════

let _sleepChart = null;

// Active sleep trend window — 7, 14, or 30
let _sleepTrendDays = 7;

async function loadSleepTrend(days) {
  if (days) _sleepTrendDays = days;
  const d = _sleepTrendDays;

  const data = await fetch(`/api/sleep/trend?days=30`, {cache: 'no-store'})
    .then(r => r.json()).catch(() => null);

  if (!data) return;

  // ── Stats strip ───────────────────────────────────────────────
  const strip = document.getElementById('sleep-summary-strip');
  const histEl = document.getElementById('sleep-history-sv');
  const s = data.stats;

  if (!data.total || !s.avg_duration) {
    if (strip) strip.innerHTML = `<div style="color:var(--gray-400);font-size:13px;text-align:center;padding:20px 0">${t('No sleep logged yet')}</div>`;
  } else {
    // 'insufficient' → a calm dash, not a red verdict. A trend needs a week of
    // nights (see the API); until then we say so plainly instead of alarming
    // the user off one short night.
    const TREND_ICON  = {improving: '↑ improving', worsening: '↓ worsening', stable: '→ stable', insufficient: '—'};
    const TREND_COLOR = {improving: '#22C55E',      worsening: '#EF4444',      stable: '#888780',  insufficient: '#888780'};
    const trendInsufficient = s.dur_trend === 'insufficient' || !TREND_ICON[s.dur_trend];
    if (strip) {
      strip.innerHTML = `
        <div class="sleep-stat-grid">
          <div class="sleep-stat-card">
            <div class="sleep-stat-val">${s.avg_duration}h</div>
            <div class="sleep-stat-lab">Avg duration</div>
          </div>
          <div class="sleep-stat-card">
            <div class="sleep-stat-val">${s.best_night}h</div>
            <div class="sleep-stat-lab">${t('Best night')}</div>
          </div>
          <div class="sleep-stat-card">
            <div class="sleep-stat-val">${s.good_pct}%</div>
            <div class="sleep-stat-lab">Nights ≥ 7h</div>
          </div>
          <div class="sleep-stat-card">
            <div class="sleep-stat-val" style="color:${TREND_COLOR[s.dur_trend] || '#888780'}">${TREND_ICON[s.dur_trend] || '—'}</div>
            <div class="sleep-stat-lab">${trendInsufficient ? 'Trend · need a week' : 'Trend'}</div>
          </div>
        </div>`;
    }
  }

  // ── Recent history list ──────────────────────────────────────
  const QMAP = {1:'😩',2:'😕',3:'😐',4:'😊',5:'😴'};
  if (histEl) {
    const recent = (data.logs || []).slice().reverse().slice(0, 7);
    const QCLS   = {1:'poor',2:'poor',3:'ok',4:'good',5:'great'};
    histEl.innerHTML = recent.length ? recent.map(r => {
      const pct = Math.min((r.duration_h / 9) * 100, 100).toFixed(0);
      return `
        <div class="sleep-log-row">
          <div class="sleep-log-date">${r.date_key.slice(5)}</div>
          <div class="sleep-log-dur">${r.duration_h}h</div>
          <div class="sleep-bar-col">
            <div class="sleep-bar-fill ${QCLS[r.quality]||'ok'}" style="width:${pct}%"></div>
          </div>
          <div class="sleep-log-qual">${QMAP[r.quality]||'😐'}</div>
          <button class="todo-act-btn del" data-ev-click="delSleep('${r.id}')" title="Delete">
            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 01-2 2H8a2 2 0 01-2-2L5 6"/></svg>
          </button>
        </div>`;
    }).join('') : '';
  }

  // ── Trend chart ───────────────────────────────────────────────
  const trendCard = document.getElementById('sleep-trend-card');
  if (!trendCard) return;
  trendCard.style.display = '';

  // Render toggle buttons
  const badge = document.getElementById('sleep-trend-badge');
  if (badge) {
    badge.innerHTML = `
      <div class="trend-toggle">
        <button class="trend-toggle-btn${d===7?' active':''}"  data-ev-click="loadSleepTrend(7)">${t('Weekly')}</button>
        <button class="trend-toggle-btn${d===14?' active':''}" data-ev-click="loadSleepTrend(14)">Bi-weekly</button>
        <button class="trend-toggle-btn${d===30?' active':''}" data-ev-click="loadSleepTrend(30)">${t('Monthly')}</button>
      </div>`;
  }

  // Build date range for selected window
  const today = new Date();
  const dateRange = Array.from({length: d}, (_, i) => {
    const dt = new Date(today);
    dt.setDate(dt.getDate() - (d - 1 - i));
    return dt.toISOString().split('T')[0];
  });

  // Index logs by date
  const logByDate = {};
  (data.logs || []).forEach(l => { logByDate[l.date_key] = l; });

  // Build labels — for 7d use day names, for 14/30 use M/D
  const labels = dateRange.map(date => {
    const dt = new Date(date + 'T12:00:00');
    if (d === 7) return ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][dt.getDay()];
    return (dt.getMonth()+1) + '/' + dt.getDate();
  });

  const durations  = dateRange.map(date => logByDate[date]?.duration_h ?? null);
  const qualities  = dateRange.map(date => logByDate[date]?.quality    ?? null);
  const hasAnyData = durations.some(v => v !== null);
  const logged     = durations.filter(v => v !== null).length;

  const sub = document.getElementById('sleep-trend-sub');
  if (sub) {
    if (!hasAnyData) {
      sub.textContent = t('No nights logged yet — start tracking to see your trend');
    } else {
      // Bed/wake consistency, stated as a neutral fact (no "you slept badly").
      const spread = (s && s.bedtime_spread != null && s.waketime_spread != null)
        ? Math.max(s.bedtime_spread, s.waketime_spread) : null;
      const consistency = (spread != null && s.avg_bedtime)
        ? `<br><span style="color:var(--gray-500)">${tformat('🌙 Usually asleep around %1, up around %2 · bed/wake times vary by ±%3 min', escHtml(_mc12h(s.avg_bedtime)), escHtml(_mc12h(s.avg_waketime)), spread)}</span>`
        : '';
      sub.innerHTML = `${tformat('%1 of %2 nights logged', logged, d)} · ${tformat('avg %1h', s?.avg_duration ?? '—')}${consistency}`;
    }
  }

  // Load Chart.js if needed
  if (!window.Chart) {
    await new Promise((res, rej) => {
      const sc = document.createElement('script');
      sc.src = 'https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js';
      sc.onload = res; sc.onerror = rej;
      document.head.appendChild(sc);
    });
  }

  const canvas = document.getElementById('sleep-chart');
  if (!canvas) return;
  if (_sleepChart) { _sleepChart.destroy(); _sleepChart = null; }

  const barColors  = durations.map(v =>
    v === null ? 'rgba(0,0,0,0.04)' : v >= 7 ? '#22C55E55' : v >= 6 ? '#F59E0B55' : '#EF444455'
  );
  const barBorders = durations.map(v =>
    v === null ? 'rgba(0,0,0,0.08)' : v >= 7 ? '#5A9E70' : v >= 6 ? '#E0A34E' : '#DC2626'
  );

  const isDark  = window.matchMedia('(prefers-color-scheme: dark)').matches;
  const grid    = isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.05)';
  const tickCol = '#9CA3AF';

  // Quality emoji color for tooltip
  const QUALITY_LABEL = {1:'😩 Terrible',2:'😕 Poor',3:'😐 Okay',4:'😊 Good',5:'😴 Great'};

  // Custom plugin: draw quality emoji below x-axis labels
  const qualityEmojiPlugin = {
    id: 'qualityEmoji',
    afterDraw(chart) {
      const ctx2  = chart.ctx;
      const xAxis = chart.scales.x;
      const QEMOJI = {1:'😩',2:'😕',3:'😐',4:'😊',5:'😴'};
      ctx2.save();
      ctx2.font = d <= 14 ? '16px serif' : '13px serif';
      ctx2.textAlign = 'center';
      xAxis.ticks.forEach((tick, i) => {
        const q = qualities[i];
        if (q == null) return;
        const x = xAxis.getPixelForTick(i);
        const y = chart.chartArea.bottom + (d <= 14 ? 38 : 34);
        ctx2.fillText(QEMOJI[q] || '', x, y);
      });
      ctx2.restore();
    },
  };

  _sleepChart = new window.Chart(canvas, {
    plugins: [qualityEmojiPlugin],
    data: {
      labels,
      datasets: [
        {
          type:            'bar',
          label:           'Duration (h)',
          data:            durations,
          backgroundColor: barColors,
          borderColor:     barBorders,
          borderWidth:     1.5,
          borderRadius:    5,
          yAxisID:         'y',
        },
        {
          type:        'line',
          label:       '7h target',
          data:        Array(d).fill(7),
          borderColor: '#22C55E',
          borderWidth: 1,
          borderDash:  [4, 4],
          pointRadius: 0,
          yAxisID:     'y',
        },
      ],
    },
    options: {
      responsive:          true,
      maintainAspectRatio: false,
      layout: { padding: { bottom: d <= 14 ? 28 : 22 } },  // room for emoji row
      interaction:         {mode: 'index', intersect: false},
      plugins: {
        legend: {
          position: 'bottom',
          labels: {
            boxWidth: 10, boxHeight: 3,
            font: {size: 11}, color: tickCol, padding: 14,
            filter: item => item.text !== '7h target',
          },
        },
        tooltip: {
          backgroundColor: 'rgba(17,24,39,0.88)',
          padding: 10,
          titleFont: {size: 12, weight: '600'},
          bodyFont:  {size: 12},
          callbacks: {
            label: ctx => {
              if (ctx.dataset.label === '7h target') return null;
              if (ctx.parsed.y === null || ctx.parsed.y === undefined) return null;
              return '  Duration: ' + ctx.parsed.y + 'h';
            },
            afterLabel: ctx => {
              if (ctx.dataset.label === '7h target') return null;
              const q = qualities[ctx.dataIndex];
              if (q == null) return null;
              return '  Quality: ' + (QUALITY_LABEL[q] || '');
            },
            afterBody: items => {
              const real = items.filter(i => i.dataset.label !== '7h target');
              if (real.every(i => i.parsed.y === null || i.parsed.y === undefined)) {
                return ['  Not logged'];
              }
              return [];
            },
          },
          filter: item => item.dataset.label !== '7h target',
        },
      },
      scales: {
        x: {
          grid:  {color: grid},
          ticks: {
            color: tickCol, font: {size: 10},
            maxTicksLimit: d === 30 ? 10 : d,
          },
          border: {display: false},
        },
        y: {
          min: 0, max: 11,
          grid: {color: grid},
          ticks: {
            color: tickCol, font: {size: 10},
            callback: v => v + 'h',
            stepSize: 2,
          },
          border: {display: false},
        },
      },
    },
  });

  // ── Week strip ────────────────────────────────────────────────
  const weekStrip = document.getElementById('sleep-week-strip');
  if (weekStrip && data.weekly?.length) {
    weekStrip.innerHTML = data.weekly.map(w => `
      <div class="sleep-week-card">
        <div class="sleep-week-label">${w.label}</div>
        <div class="sleep-week-dur">${w.avg_dur}h</div>
        <div class="sleep-week-nights">${w.good}/${w.nights} good nights</div>
      </div>`).join('');
  }
}


// ════════════════════════════════════════════════════════════════
// CALORIE BALANCE — 7-day trend chart
// ════════════════════════════════════════════════════════════════

let _calChart = null;

async function renderCalorieTrendChart(daily) {
  const section = document.getElementById('cbd-trend-section');
  const canvas  = document.getElementById('cbd-trend-chart');
  if (!section || !canvas || !daily.length) return;

  // Only show when at least 2 days have food logged
  const logged = daily.filter(d => d.logged);
  if (logged.length < 2) return;
  section.style.display = '';

  if (!window.Chart) {
    await new Promise((res, rej) => {
      const s = document.createElement('script');
      s.src = 'https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js';
      s.onload = res; s.onerror = rej;
      document.head.appendChild(s);
    });
  }

  if (_calChart) { _calChart.destroy(); _calChart = null; }

  const isDark   = window.matchMedia('(prefers-color-scheme: dark)').matches;
  const gridCol  = isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)';
  const tickCol  = '#888780';

  const labels = daily.map(d => {
    const dt = new Date(d.date + 'T12:00:00');
    return ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][dt.getDay()];
  });

  // Bar colour: green if under budget, red if over
  const barColors = daily.map(d =>
    !d.logged ? 'transparent' :
    d.net >= 0 ? '#22C55E66' : '#EF444466'
  );
  const barBorders = daily.map(d =>
    !d.logged ? 'transparent' :
    d.net >= 0 ? '#5A9E70' : '#DC2626'
  );

  _calChart = new window.Chart(canvas, {
    data: {
      labels,
      datasets: [
        {
          type:            'bar',
          label:           'Eaten',
          data:            daily.map(d => d.eaten || 0),
          backgroundColor: barColors,
          borderColor:     barBorders,
          borderWidth:     1,
          borderRadius:    3,
          yAxisID:         'y',
        },
        {
          type:            'line',
          label:           'Budget',
          data:            daily.map(d => d.budget),
          borderColor:     '#4F8D74',
          backgroundColor: 'transparent',
          borderWidth:     1.5,
          borderDash:      [4, 3],
          pointRadius:     0,
          yAxisID:         'y',
        },
      ],
    },
    options: {
      responsive:          true,
      maintainAspectRatio: false,
      interaction:         {mode: 'index', intersect: false},
      plugins: {
        legend: {
          position: 'bottom',
          labels: {
            boxWidth: 10, boxHeight: 2,
            font: {size: 10}, color: tickCol, padding: 10,
          },
        },
        tooltip: {
          callbacks: {
            afterBody: items => {
              const idx = items[0]?.dataIndex;
              if (idx == null) return '';
              const d = daily[idx];
              if (!d.logged) return 'Not logged';
              const diff = d.net;
              return diff >= 0
                ? `${diff} kcal under budget`
                : `${Math.abs(diff)} kcal over budget`;
            },
          },
        },
      },
      scales: {
        x: {
          grid:   {display: false},
          ticks:  {color: tickCol, font: {size: 10}},
          border: {display: false},
        },
        y: {
          min:    0,
          grid:   {color: gridCol},
          ticks:  {
            color: tickCol, font: {size: 10},
            callback: v => v >= 1000 ? (v/1000).toFixed(1) + 'k' : v,
            maxTicksLimit: 4,
          },
          border: {display: false},
        },
      },
    },
  });
}


// ════════════════════════════════════════════════════════════════
// FITNESS PERSONAL RECORDS (PRs)
// ════════════════════════════════════════════════════════════════

async function loadFitnessPRs() {
  const section = document.getElementById('fitness-pr-section');
  if (!section) return;

  const data = await fetch('/api/fitness/prs', {cache: 'no-store'})
    .then(r => r.json()).catch(() => null);

  if (!data?.has_data || !data.prs.length) {
    section.innerHTML = '';
    return;
  }

  const { prs, total_activities, recent_prs } = data;

  // Group PRs by category for display
  const grouped = {};
  prs.forEach(pr => {
    const cat = pr.category;
    if (!grouped[cat]) grouped[cat] = { icon: pr.icon, metrics: [] };
    grouped[cat].metrics.push(pr);
  });

  const PRCards = Object.entries(grouped).map(([cat, group]) => {
    const metricsHTML = group.metrics.map(pr => {
      const val    = pr.value_display || (pr.unit === 'km' ? pr.value + ' km' : pr.value + ' ' + pr.unit);
      const date   = new Date(pr.date + 'T12:00:00').toLocaleDateString(_locale(), {month:'short', day:'numeric', year:'numeric'});
      const newTag = pr.is_recent
        ? '<span class="pr-new-tag">🏆 New!</span>'
        : '';
      return `
        <div class="pr-metric-row">
          <div class="pr-metric-info">
            <div class="pr-metric-name">${escHtml(pr.metric)}</div>
            <div class="pr-metric-date">${escHtml(pr.name)} · ${date}</div>
          </div>
          <div class="pr-metric-right">
            ${newTag}
            <div class="pr-metric-val">${escHtml(String(val))}</div>
          </div>
        </div>`;
    }).join('');

    return `
      <div class="pr-card">
        <div class="pr-card-header">
          <span class="pr-card-icon">${group.icon}</span>
          <span class="pr-card-cat">${escHtml(cat)}</span>
        </div>
        ${metricsHTML}
      </div>`;
  }).join('');

  section.innerHTML = `
    <div class="panel" style="padding:18px 20px 20px">
      <div class="panel-header" style="margin-bottom:14px">
        <h2 class="panel-title">Personal Records</h2>
        <div style="display:flex;align-items:center;gap:8px">
          ${recent_prs > 0 ? `<span class="panel-badge" style="background:#DCFCE7;color:#468A5B">🏆 ${recent_prs} new this month</span>` : ''}
          <span class="panel-badge">${total_activities} workouts all-time</span>
        </div>
      </div>
      <div class="pr-grid">${PRCards}</div>
    </div>`;
}


// ════════════════════════════════════════════════════════════════
// MOOD × SLEEP CORRELATION
// ════════════════════════════════════════════════════════════════

let _moodSleepChart = null;
let _moodSleepDays  = 30;   // default Monthly

async function loadMoodSleepCorrelation(days) {
  if (days) _moodSleepDays = days;
  const d = _moodSleepDays;

  const section = document.getElementById('mood-sleep-section');
  if (!section) return;

  const data = await fetch(`/api/mood-sleep/correlation?days=${d}`, {cache: 'no-store'})
    .then(r => r.json()).catch(() => null);

  if (!data) return;

  const mscToggle = `
    <div class="trend-toggle">
      <button class="trend-toggle-btn${d===30?' active':''}"  data-ev-click="loadMoodSleepCorrelation(30)">${t('Monthly')}</button>
      <button class="trend-toggle-btn${d===90?' active':''}"  data-ev-click="loadMoodSleepCorrelation(90)">3 months</button>
    </div>`;

  // Not enough data yet
  if (!data.has_data || data.need_more) {
    const needed = data.need_count || 5;
    section.innerHTML = `
      <div class="panel" style="padding:20px 24px">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
          <h2 class="panel-title">Mood × Sleep correlation</h2>
          ${mscToggle}
        </div>
        <div style="text-align:center;padding:24px 0">
          <div style="font-size:28px;margin-bottom:10px">🌙😊</div>
          <div style="font-size:14px;font-weight:600;color:var(--gray-700);margin-bottom:6px">Not enough data yet</div>
          <div style="font-size:13px;color:var(--gray-400)">
            Log both mood (in Journal) and sleep on the same day ${needed} more time${needed !== 1 ? 's' : ''} to unlock this insight.
          </div>
        </div>
      </div>`;
    return;
  }

  const { paired, correlation, per_mood, threshold, insight, matched_days } = data;
  const r_val   = correlation?.r ?? 0;
  const strength = correlation?.strength || 'none';

  // Strength indicator color
  const STRENGTH_COLOR = { strong:'#22C55E', moderate:'#F59E0B', weak:'#9CA3AF', none:'#9CA3AF' };
  const strengthColor  = STRENGTH_COLOR[strength];

  // ── Per-mood sleep average bars ──────────────────────────────
  const MOOD_ORDER = ['excited','happy','calm','neutral','tired','anxious','sad','terrible'];
  const moodRows = MOOD_ORDER
    .filter(m => per_mood[m])
    .map(m => {
      const pm  = per_mood[m];
      const pct = Math.min(Math.round(pm.avg_duration / 10 * 100), 100);
      return `
        <div class="msc-mood-row">
          <div class="msc-mood-emoji">${moodEmoji(m)}</div>
          <div class="msc-mood-bar-wrap">
            <div class="msc-mood-bar" style="width:${pct}%;background:${moodColor(m)}"></div>
          </div>
          <div class="msc-mood-val">${pm.avg_duration}h</div>
          <div class="msc-mood-count">${pm.count}d</div>
        </div>`;
    }).join('');

  // ── 7h threshold split ────────────────────────────────────────
  const above = threshold?.above_7h || {};
  const below = threshold?.below_7h || {};
  const SCORE_LABELS = {1:'Rough',2:'Low',3:'Okay',4:'Neutral',5:'Calm',6:'Good',7:'Great'};
  const aboveLabel = above.avg_mood_score ? SCORE_LABELS[Math.round(above.avg_mood_score)] || '' : '—';
  const belowLabel = below.avg_mood_score ? SCORE_LABELS[Math.round(below.avg_mood_score)] || '' : '—';

  section.innerHTML = `
    <div class="panel" style="padding:18px 20px 20px">
      <div style="display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:14px">
        <div>
          <h2 class="panel-title">Mood × Sleep correlation</h2>
          <div style="font-size:12px;margin-top:3px;display:flex;gap:8px;align-items:center">
            <span style="background:${strengthColor}22;color:${strengthColor};padding:2px 8px;border-radius:99px;font-size:11px;font-weight:600">${strength} correlation</span>
            <span style="color:var(--gray-400)">${matched_days} matched days</span>
          </div>
        </div>
        ${mscToggle}
      </div>

      <!-- Insight banner -->
      <div class="msc-insight-banner">
        <span class="msc-insight-icon">💡</span>
        <span class="msc-insight-text">${escHtml(insight)}</span>
      </div>

      <div style="display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:16px">

        <!-- Left: per-mood sleep averages -->
        <div>
          <div style="font-size:12px;font-weight:600;color:var(--gray-500);text-transform:uppercase;letter-spacing:.05em;margin-bottom:10px">
            Avg sleep per mood
          </div>
          ${moodRows || '<div style="color:var(--gray-400);font-size:13px">Not enough data</div>'}
        </div>

        <!-- Right: 7h split + correlation badge -->
        <div style="display:flex;flex-direction:column;gap:12px">

          <!-- Correlation coefficient -->
          <div class="msc-r-card">
            <div class="msc-r-val" style="color:${strengthColor}">${r_val > 0 ? '+' : ''}${r_val.toFixed(2)}</div>
            <div class="msc-r-label">Pearson r</div>
            <div class="msc-r-sub">
              ${Math.abs(r_val) >= 0.3 ? 'Statistically meaningful' : 'More data needed'}
            </div>
          </div>

          <!-- 7h threshold split -->
          <div class="msc-split-card">
            <div style="font-size:12px;font-weight:600;color:var(--gray-500);margin-bottom:10px">Sleep ≥ 7h vs < 7h</div>
            <div class="msc-split-row">
              <div class="msc-split-block msc-split-block--good">
                <div class="msc-split-val">🌙 ${aboveLabel}</div>
                <div class="msc-split-sub">After ≥7h (${above.count || 0} nights)</div>
              </div>
              <div class="msc-split-block msc-split-block--low">
                <div class="msc-split-val">😪 ${belowLabel}</div>
                <div class="msc-split-sub">After &lt;7h (${below.count || 0} nights)</div>
              </div>
            </div>
          </div>

        </div>
      </div>

      <!-- Scatter plot -->
      <div id="msc-chart-section" style="margin-top:18px;display:none">
        <div style="font-size:12px;font-weight:600;color:var(--gray-500);text-transform:uppercase;letter-spacing:.05em;margin-bottom:10px">
          Sleep duration vs mood — scatter
        </div>
        <div style="position:relative;height:200px">
          <canvas id="msc-scatter"></canvas>
        </div>
        <div style="font-size:11px;color:var(--gray-400);margin-top:6px;text-align:center">
          Each dot = one day · horizontal = sleep hours · vertical = mood score
        </div>
      </div>

    </div>`;

  // Render scatter chart if 5+ points
  if (paired.length >= 5) {
    renderMoodSleepScatter(paired);
  }
}

async function renderMoodSleepScatter(paired) {
  const section = document.getElementById('msc-chart-section');
  const canvas  = document.getElementById('msc-scatter');
  if (!section || !canvas) return;
  section.style.display = '';

  if (!window.Chart) {
    await new Promise((res, rej) => {
      const s = document.createElement('script');
      s.src = 'https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js';
      s.onload = res; s.onerror = rej;
      document.head.appendChild(s);
    });
  }

  if (_moodSleepChart) { _moodSleepChart.destroy(); _moodSleepChart = null; }

  const isDark  = window.matchMedia('(prefers-color-scheme: dark)').matches;
  const gridCol = isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)';
  const tickCol = '#888780';

  const SCORE_LABELS = ['','Rough','Low','Okay','Neutral','Calm','Good','Great'];

  const points = paired.map(p => ({
    x: p.duration,
    y: p.score,
    mood: p.mood,
    date: p.date,
  }));

  // Colour each point by mood
  const pointColors = points.map(pt =>
    moodColor(pt.mood) + 'CC'
  );

  _moodSleepChart = new window.Chart(canvas, {
    type: 'scatter',
    data: {
      datasets: [{
        label:           'Days',
        data:            points,
        backgroundColor: pointColors,
        borderColor:     pointColors.map(c => c.slice(0,7)),
        borderWidth:     1,
        pointRadius:     6,
        pointHoverRadius:8,
      }],
    },
    options: {
      responsive:          true,
      maintainAspectRatio: false,
      plugins: {
        legend: { display: false },
        tooltip: {
          callbacks: {
            label: ctx => {
              const pt = ctx.raw;
              return ` ${moodEmoji(pt.mood)} ${pt.mood} after ${pt.x}h sleep (${pt.date})`;
            },
          },
        },
      },
      scales: {
        x: {
          title: { display: true, text: 'Sleep (hours)', color: tickCol, font: {size: 11} },
          min: 3, max: 11,
          grid:  { color: gridCol },
          ticks: { color: tickCol, font: {size: 10} },
          border:{ display: false },
        },
        y: {
          title: { display: true, text: 'Mood', color: tickCol, font: {size: 11} },
          min: 0.5, max: 7.5,
          grid:  { color: gridCol },
          ticks: {
            color: tickCol, font: {size: 10},
            callback: v => SCORE_LABELS[Math.round(v)] || '',
            stepSize: 1,
          },
          border:{ display: false },
        },
      },
    },
  });
}


// ════════════════════════════════════════════════════════════════
// WEEKLY DIGEST
// ════════════════════════════════════════════════════════════════

async function loadWeeklyDigest() {
  const section = document.getElementById('weekly-digest-section');
  if (!section) return;

  section.innerHTML = '<div style="height:4px"></div>'; // placeholder while loading

  const d = await fetch('/api/weekly-digest', {cache: 'no-store'})
    .then(r => r.json()).catch(() => null);

  if (!d) { section.innerHTML = ''; return; }

  const { headline, overall_score, scores, highlights, wins, concerns,
          period_label, tracked_areas } = d;

  // overall_score is null when there's nothing to score. It must not become 0:
  // a red 0 ring under "Nothing logged yet — start tracking" read as sarcasm,
  // and it said "you failed" where the truth was "you didn't track anything".
  const hasScore = overall_score != null;
  const scoreColor = overall_score >= 80 ? '#22C55E'
                   : overall_score >= 60 ? '#4F8D74'
                   : overall_score >= 40 ? '#F59E0B' : '#EF4444';

  // Mini score bars
  const SCORE_LABELS = {
    sleep: '🌙 Sleep', workouts: '🏃 Workouts',
    habits: '⭐ Habits', hydration: '💧 Hydration', nutrition: '🍽️ Nutrition',
  };
  // Only bar the areas they actually track. A null score means "not tracked",
  // and drawing it as an empty red 0% bar next to the real ones turns an
  // absence into a failure.
  const scoreBars = Object.entries(scores)
    .filter(([, val]) => val != null)
    .map(([key, val]) => `
    <div class="wd-score-row">
      <span class="wd-score-label">${SCORE_LABELS[key] || key}</span>
      <div class="wd-score-bar-wrap">
        <div class="wd-score-bar" style="width:${val}%;background:${
          val >= 80 ? '#22C55E' : val >= 60 ? '#4F8D74' : val >= 40 ? '#F59E0B' : '#EF4444'
        }"></div>
      </div>
      <span class="wd-score-pct">${val}%</span>
    </div>`).join('');

  // Highlights strip
  const highlightStrip = highlights.map(h => `
    <div class="wd-highlight">
      <div class="wd-highlight-icon">${h.icon}</div>
      <div class="wd-highlight-val">${escHtml(h.value)}</div>
      <div class="wd-highlight-label">${escHtml(h.label)}</div>
    </div>`).join('');

  // Wins and concerns
  const winsHTML = wins.length
    ? wins.map(w => `
        <div class="wd-item wd-item--win">
          <span class="wd-item-icon">${w.icon}</span>
          <span class="wd-item-text">${escHtml(w.text)}</span>
        </div>`).join('')
    : '<div style="font-size:13px;color:var(--gray-400);padding:8px 0">No highlights yet — keep logging!</div>';

  const concernsHTML = concerns.length
    ? concerns.map(c => `
        <div class="wd-item wd-item--concern">
          <span class="wd-item-icon">${c.icon}</span>
          <span class="wd-item-text">${escHtml(c.text)}</span>
        </div>`).join('')
    : '<div style="font-size:13px;color:var(--gray-400);padding:8px 0">Nothing to flag — great week!</div>';

  section.innerHTML = `
    <div class="wd-card" style="margin-bottom:20px">

      <!-- Header row -->
      <div class="wd-header">
        <div class="wd-header-left">
          <div class="wd-period">${escHtml(period_label)}</div>
          <div class="wd-headline">${escHtml(headline)}</div>
        </div>
        ${hasScore ? `
        <div class="wd-ring-wrap" title="Averaged across the ${tracked_areas} area${tracked_areas === 1 ? '' : 's'} you track">
          <svg width="64" height="64" viewBox="0 0 64 64">
            <circle cx="32" cy="32" r="26" fill="none" stroke="var(--gray-100)" stroke-width="6"/>
            <circle cx="32" cy="32" r="26" fill="none"
              stroke="${scoreColor}" stroke-width="6"
              stroke-dasharray="${Math.round(overall_score * 1.634)} 163.4"
              stroke-linecap="round"
              transform="rotate(-90 32 32)"/>
          </svg>
          <div class="wd-ring-num" style="color:${scoreColor}">${overall_score}</div>
        </div>` : ''}
      </div>

      <!-- Highlights strip -->
      ${highlights.length ? `<div class="wd-highlights">${highlightStrip}</div>` : ''}

      <!-- Scores + wins/concerns -->
      <div class="wd-body">
        <!-- Score bars (only the areas they track; hidden entirely if none) -->
        ${scoreBars ? `
        <div class="wd-scores">
          <div class="wd-section-title">Area scores</div>
          ${scoreBars}
        </div>` : ''}

        <!-- Wins and concerns -->
        <div class="wd-narrative">
          <div style="margin-bottom:14px">
            <div class="wd-section-title">✅ What went well</div>
            ${winsHTML}
          </div>
          <div>
            <div class="wd-section-title">📌 Worth watching</div>
            ${concernsHTML}
          </div>
        </div>
      </div>

    </div>`;
}


// ════════════════════════════════════════════════════════════════
// WEIGHT PROGRESS CHART
// ════════════════════════════════════════════════════════════════

let _weightChart = null;
let _weightTrendDays = 90;  // default 3 months

// Honest body-recomposition read. Weight, body-fat, and protein are logged
// separately; a young person doing recomp needs them combined, because the
// scale alone lies (muscle up + fat down can hold weight flat). Framed as an
// observation, never a plan or a causal claim.
async function loadRecompSignal() {
  const el = document.getElementById('bv-recomp-section');
  if (!el) return;
  const d = await fetch('/api/body/recomp', {cache: 'no-store'}).then(r => r.json()).catch(() => null);
  if (!d || !d.has_data || !d.read || d.read === 'keep_logging') { el.innerHTML = ''; return; }

  // read → headline + honest one-liner. No prescriptions.
  const READS = {
    recomp:      ['🔄', t('This looks like recomposition'),
                  t('Body-fat down while weight held — muscle likely up. The scale alone would have missed this.')],
    fat_loss:    ['📉', t('Losing body fat'),
                  t('Your body-fat readings are trending down over this window.')],
    lean_gain:   ['💪', t('Gaining, with protein behind it'),
                  t("You're gaining weight and hitting your protein — supportive of muscle, not just fat.")],
    weight_up:   ['⚖️', t('Weight is trending up'),
                  t('Protein is under target though — worth a look if muscle is the goal.')],
    protein_low: ['🍳', t('Protein is running low'),
                  t('You logged well under your protein target on the days you tracked. Protein builds and repairs muscle.')],
  };
  const r = READS[d.read];
  if (!r) { el.innerHTML = ''; return; }

  const stat = (label, val) => `<div class="recomp-stat"><b>${val}</b><span>${label}</span></div>`;
  const stats = [];
  if (d.weight) stats.push(stat(t('weight'), `${d.weight.change >= 0 ? '+' : ''}${d.weight.change} kg`));
  if (d.body_fat) stats.push(stat(t('body fat'), `${d.body_fat.change >= 0 ? '+' : ''}${d.body_fat.change}%`));
  if (d.protein) stats.push(stat(t('avg protein'), `${d.protein.avg} / ${d.protein.target}g`));

  el.innerHTML = `
    <div class="panel recomp-card" style="padding:18px 20px">
      <div class="recomp-head"><span class="recomp-emoji">${r[0]}</span>
        <div><div class="recomp-title">${r[1]}</div>
          <div class="recomp-sub">${r[2]}</div></div></div>
      ${stats.length ? `<div class="recomp-stats">${stats.join('')}</div>` : ''}
      <div class="recomp-window">${tformat('Based on the last %1 days you logged. An observation, not medical advice.', d.days)}</div>
    </div>`;
}

async function loadWeightProgressChart(days) {
  if (days) _weightTrendDays = days;
  const d = _weightTrendDays;

  const section = document.getElementById('bv-weight-chart-section');
  if (!section) return;

  const data = await fetch(`/api/body-metrics/trend?days=${d}`, {cache: 'no-store'})
    .then(r => r.json()).catch(() => null);

  if (!data) return;

  const { logs, projection, stats } = data;

  // Not enough data
  if (!logs.length) {
    section.innerHTML = `
      <div class="panel" style="padding:20px 24px">
        <div class="panel-header" style="margin-bottom:10px">
          <h2 class="panel-title">Weight progress</h2>
        </div>
        <div style="text-align:center;padding:20px 0">
          <div style="font-size:24px;margin-bottom:10px">⚖️</div>
          <div style="font-size:14px;font-weight:600;color:var(--gray-700);margin-bottom:6px">No weight logged yet</div>
          <div style="font-size:13px;color:var(--gray-400)">Log your first weight entry above to start tracking progress.</div>
        </div>
      </div>`;
    return;
  }

  const s      = stats;
  const goal   = s.goal || 'maintain';
  const GOAL_LABELS = {
    lose_fast:'Lose weight fast', lose:'Lose weight',
    maintain:'Maintain', gain:'Gain muscle', gain_fast:'Build mass',
  };

  // Progress toward goal
  const hasGoal     = s.target_weight != null && goal !== 'maintain';
  const change      = s.total_change;
  const changeDir   = change < 0 ? '↓' : change > 0 ? '↑' : '→';
  const changeColor = (goal.startsWith('lose') && change <= 0) || (goal.startsWith('gain') && change >= 0)
    ? '#22C55E' : change === 0 ? '#888780' : '#F59E0B';

  // ETA text — prefer the MEASURED pace ("at your current pace") over the plan's
  // assumed rate, so we never present the app's assumption as the user's reality.
  let etaText = '';
  if (s.measured_eta_date) {
    const eta = new Date(s.measured_eta_date + 'T12:00:00');
    const daysLeft = Math.round((eta - new Date()) / 86400000);
    etaText = daysLeft <= 0
      ? '🎉 Goal reached!'
      : `At your current pace, ~${daysLeft} days to your goal (${eta.toLocaleDateString(_locale(),{month:'short',day:'numeric'})})`;
  } else if (s.on_track === false && hasGoal) {
    etaText = "You're not moving toward your goal at your current pace yet.";
  } else if (s.eta_date) {
    const eta = new Date(s.eta_date + 'T12:00:00');
    const daysLeft = Math.round((eta - new Date()) / 86400000);
    if (daysLeft > 0)
      etaText = `On plan: ~${daysLeft} days to go (${eta.toLocaleDateString(_locale(),{month:'short',day:'numeric'})})`;
  }
  const etaColor = s.on_track === false ? '#B4443A' : '#468A5B';

  // Actual pace, measured from real weigh-ins (distinct from the plan's rate).
  const mRate = s.measured_rate_per_week;
  const mDir  = mRate == null ? '' : mRate < 0 ? '↓' : mRate > 0 ? '↑' : '→';

  // Stat cards
  const statCards = [
    {label: 'Current',   val: fmtWeight(s.latest_weight),              show: true},
    {label: 'Starting',  val: fmtWeight(s.start_weight),               show: !!s.start_weight},
    {label: 'Change',    val: `${changeDir} ${fmtWeight(Math.abs(change))}`, show: change !== 0, color: changeColor},
    {label: 'Target',    val: fmtWeight(s.target_weight),               show: hasGoal},
    {label: 'Progress',  val: `${s.pct_to_goal}%`,                      show: hasGoal && s.pct_to_goal != null},
    {label: 'Actual pace', val: `${mDir} ${fmtWeight(Math.abs(mRate))}/wk`, show: mRate != null && mRate !== 0},
  ].filter(c => c.show);

  const statsHTML = statCards.map(c => `
    <div class="wpc-stat">
      <div class="wpc-stat-val" ${c.color ? `style="color:${c.color}"` : ''}>${escHtml(c.val)}</div>
      <div class="wpc-stat-label">${c.label}</div>
    </div>`).join('');

  const toggleHTML = `
    <div class="trend-toggle">
      <button class="trend-toggle-btn${d===30?' active':''}"  data-ev-click="loadWeightProgressChart(30)">${t('Monthly')}</button>
      <button class="trend-toggle-btn${d===90?' active':''}"  data-ev-click="loadWeightProgressChart(90)">3 months</button>
      <button class="trend-toggle-btn${d===180?' active':''}" data-ev-click="loadWeightProgressChart(180)">6 months</button>
    </div>`;

  section.innerHTML = `
    <div class="panel" style="padding:18px 20px 20px">
      <div style="display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:12px">
        <div>
          <h2 class="panel-title">Weight progress</h2>
          ${etaText ? `<div style="font-size:12px;color:${etaColor};margin-top:3px">${escHtml(etaText)}</div>` : ''}
        </div>
        <div style="display:flex;align-items:center;gap:10px">
          <span class="panel-badge">${GOAL_LABELS[goal] || goal}</span>
          ${toggleHTML}
        </div>
      </div>

      <!-- Goal weight input -->
      <div class="wpc-goal-row">
        <label style="font-size:12.5px;color:var(--gray-600);flex-shrink:0">Target weight</label>
        <input type="number" class="form-input wpc-goal-input" id="wpc-target-weight"
               placeholder="${_userUnits.weight === 'lb' ? 'e.g. 150' : 'e.g. 68.0'}" step="0.5"
               value="${s.target_weight != null ? vitalToDisplay('weight', s.target_weight) : ''}"
               data-ev-change="saveTargetWeight(this.value)">
        <span style="font-size:12.5px;color:var(--gray-500);flex-shrink:0">${weightUnitLabel()}</span>
        ${hasGoal && s.pct_to_goal != null ? `
          <div class="wpc-progress-pill">
            <div class="wpc-progress-fill" style="width:${s.pct_to_goal}%"></div>
          </div>
          <span style="font-size:11.5px;color:var(--gray-500);flex-shrink:0">${s.pct_to_goal}%</span>
        ` : ''}
      </div>

      <!-- Stat strip -->
      <div class="wpc-stats">${statsHTML}</div>

      <!-- Chart -->
      <div style="position:relative;height:220px;margin-top:16px">
        <canvas id="wpc-chart"></canvas>
      </div>

      <!-- Legend -->
      <div style="display:flex;gap:16px;margin-top:8px;font-size:11.5px;color:var(--gray-500);flex-wrap:wrap">
        <span style="display:flex;align-items:center;gap:5px">
          <span style="width:18px;height:3px;background:#4F8D74;display:inline-block;border-radius:1px"></span>
          Actual weight
        </span>
        ${hasGoal && projection.length ? `
          <span style="display:flex;align-items:center;gap:5px">
            <span style="width:18px;height:2px;background:#F59E0B;display:inline-block;border-radius:1px;border-top:2px dashed #F59E0B;height:0"></span>
            Projected at ${fmtWeight(Math.abs(s.rate_per_week))}/week
          </span>
          <span style="display:flex;align-items:center;gap:5px">
            <span style="width:18px;height:2px;background:#22C55E;display:inline-block;border-radius:1px;border-top:2px dashed #22C55E;height:0"></span>
            Goal: ${fmtWeight(s.target_weight)}
          </span>` : ''}
      </div>
    </div>`;

  renderWeightChart(logs, projection, stats);
}

async function renderWeightChart(logs, projection, stats) {
  const canvas = document.getElementById('wpc-chart');
  if (!canvas) return;

  if (!window.Chart) {
    await new Promise((res, rej) => {
      const s = document.createElement('script');
      s.src = 'https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js';
      s.onload = res; s.onerror = rej;
      document.head.appendChild(s);
    });
  }

  if (_weightChart) { _weightChart.destroy(); _weightChart = null; }

  const isDark   = window.matchMedia('(prefers-color-scheme: dark)').matches;
  const gridCol  = isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)';
  const tickCol  = '#888780';

  // Actual weight dataset — all log dates
  const actualLabels = logs.map(l => {
    const d = new Date(l.date_key + 'T12:00:00');
    return (d.getMonth()+1) + '/' + d.getDate();
  });
  // Convert the series ONCE to the user's unit so the axis, min/max, tooltip,
  // projection and goal line can never disagree with each other.
  const _w = kg => vitalToDisplay('weight', kg);
  const actualData = logs.map(l => _w(l.weight_kg));

  // Combined date range for projection overlay
  const hasProjection = projection && projection.length > 0 && stats.target_weight;

  // Y-axis range
  const allWeights = actualData.slice();
  if (hasProjection) projection.forEach(p => allWeights.push(_w(p.weight)));
  if (stats.target_weight) allWeights.push(_w(stats.target_weight));
  const minW = Math.floor(Math.min(...allWeights) - 2);
  const maxW = Math.ceil(Math.max(...allWeights) + 2);

  // Projection labels (only dates beyond last actual entry)
  const lastActualDate = logs[logs.length - 1].date_key;
  const projFuture     = (projection || []).filter(p => p.date > lastActualDate);

  // Build unified label set for combined chart
  const projLabels = projFuture.map(p => {
    const d = new Date(p.date + 'T12:00:00');
    return (d.getMonth()+1) + '/' + d.getDate();
  });

  const allLabels = [...actualLabels, ...projLabels];

  // Actual data padded with nulls for future dates
  const actualPadded = [
    ...actualData,
    ...projLabels.map(() => null),
  ];

  // Projection data padded with nulls for past dates
  // Overlap one point at the last actual to connect the lines
  const lastActualIdx = actualLabels.length - 1;
  const projPadded = [
    ...actualLabels.map((_, i) => i === lastActualIdx ? actualData[lastActualIdx] : null),
    ...projFuture.map(p => _w(p.weight)),
  ];

  // Goal line
  const goalLine = stats.target_weight
    ? allLabels.map(() => _w(stats.target_weight))
    : null;

  const datasets = [
    {
      label:           'Weight',
      data:            actualPadded,
      borderColor:     '#4F8D74',
      backgroundColor: '#4F8D7418',
      borderWidth:     2.5,
      pointRadius:     logs.length > 30 ? 2 : 4,
      pointHoverRadius:6,
      tension:         0.35,
      fill:            true,
      spanGaps:        false,
    },
  ];

  if (hasProjection && projFuture.length) {
    datasets.push({
      label:           'Projected',
      data:            projPadded,
      borderColor:     '#F59E0B',
      backgroundColor: 'transparent',
      borderWidth:     2,
      borderDash:      [5, 4],
      pointRadius:     0,
      pointHoverRadius:4,
      tension:         0.2,
      fill:            false,
      spanGaps:        false,
    });
  }

  if (goalLine) {
    datasets.push({
      label:       'Goal',
      data:        goalLine,
      borderColor: '#22C55E',
      borderWidth: 1.5,
      borderDash:  [6, 4],
      pointRadius: 0,
      fill:        false,
    });
  }

  _weightChart = new window.Chart(canvas, {
    type: 'line',
    data: { labels: allLabels, datasets },
    options: {
      responsive:          true,
      maintainAspectRatio: false,
      interaction:         { mode: 'index', intersect: false },
      plugins: {
        legend: { display: false },
        tooltip: {
          callbacks: {
            label: ctx => {
              if (ctx.parsed.y == null) return 'Not logged';
              return ` ${ctx.dataset.label}: ${ctx.parsed.y} ${weightUnitLabel()}`;
            },
          },
        },
      },
      scales: {
        x: {
          grid:   { color: gridCol },
          ticks:  { color: tickCol, font: {size: 10}, maxTicksLimit: 10 },
          border: { display: false },
        },
        y: {
          min:    minW, max: maxW,
          grid:   { color: gridCol },
          ticks:  {
            color: tickCol, font: {size: 10},
            callback: v => v + ' ' + weightUnitLabel(),
            maxTicksLimit: 6,
          },
          border: { display: false },
        },
      },
    },
  });
}

async function saveTargetWeight(val) {
  // Typed in the user's unit; the profile column is canonical kg.
  const typed = parseFloat(val);
  if (!typed) return;
  const kg = weightInputToKg(typed);
  if (kg < 20 || kg > 300) return;
  const r = await fetch('/api/food/profile', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({ target_weight_kg: kg }),
  }).then(r => r.json()).catch(() => null);
  if (r?.success) {
    showToast(tformat('Target weight set: %1', fmtWeight(kg)), 'success');
    loadWeightProgressChart();
  }
}


